// ------------------------------------------------------------------ world

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Team {
    Blue,
    Red,
}

#[derive(Clone, Copy, Debug)]
pub struct Aabb {
    pub min: [f32; 3],
    pub max: [f32; 3],
}

impl Aabb {
    /// Slab-method ray hit; also returns the face normal. Public: the
    /// client reuses it for camera-boom collision and crosshair raycasts.
    pub fn ray_hit(&self, o: [f32; 3], d: [f32; 3], t_max: f32) -> Option<(f32, [f32; 3])> {
        let mut t0 = 0.0_f32;
        let mut t1 = t_max;
        let mut axis = 0usize;
        let mut sign = 1.0_f32;
        for i in 0..3 {
            if d[i].abs() < 1e-8 {
                if o[i] < self.min[i] || o[i] > self.max[i] {
                    return None;
                }
            } else {
                let inv = 1.0 / d[i];
                let (mut a, mut b) = ((self.min[i] - o[i]) * inv, (self.max[i] - o[i]) * inv);
                let mut s = -1.0_f32;
                if a > b {
                    std::mem::swap(&mut a, &mut b);
                    s = 1.0;
                }
                if a > t0 {
                    t0 = a;
                    axis = i;
                    sign = s;
                }
                t1 = t1.min(b);
                if t0 > t1 {
                    return None;
                }
            }
        }
        let mut n = [0.0; 3];
        n[axis] = sign;
        Some((t0, n))
    }
}

// ------------------------------------------------------- §9.1 broadphase

/// Uniform-grid broadphase over the static cover set (16 m cells in XZ).
/// A ray query costs O(cells traversed) instead of O(all geometry) —
/// required before maps grow, and before smoke/throwables/LOS pile more
/// rays onto the hot path. Results are EXACTLY the linear scan's nearest
/// hit (verified by test), so determinism is untouched.
#[derive(Clone, Debug)]
pub struct CoverGrid {
    cell: f32,
    origin: [f32; 2], // min corner (x, z)
    n: usize,         // cells per axis
    cells: Vec<Vec<u16>>,
}

impl CoverGrid {
    pub fn build(cover: &[Aabb], half: f32) -> Self {
        let cell = 16.0_f32;
        let pad = 4.0;
        let origin = [-half - pad, -half - pad];
        let span = (half + pad) * 2.0;
        let n = ((span / cell).ceil() as usize).max(1);
        let mut cells = vec![Vec::new(); n * n];
        let clamp_idx = |v: f32, o: f32| -> usize {
            (((v - o) / cell).floor() as isize).clamp(0, n as isize - 1) as usize
        };
        for (i, c) in cover.iter().enumerate() {
            let (x0, x1) = (clamp_idx(c.min[0], origin[0]), clamp_idx(c.max[0], origin[0]));
            let (z0, z1) = (clamp_idx(c.min[2], origin[1]), clamp_idx(c.max[2], origin[1]));
            for gx in x0..=x1 {
                for gz in z0..=z1 {
                    cells[gx * n + gz].push(i as u16);
                }
            }
        }
        CoverGrid {
            cell,
            origin,
            n,
            cells,
        }
    }

    /// Nearest cover hit along `o + t·d`, `t ∈ [0, t_max]` — identical
    /// result to scanning every box, via 2D DDA over the XZ cells
    /// (cover is ground-based; a 2D grid is the right shape for it).
    pub fn ray_hit(
        &self,
        cover: &[Aabb],
        o: [f32; 3],
        d: [f32; 3],
        t_max: f32,
    ) -> Option<(f32, [f32; 3])> {
        let mut best: Option<(f32, [f32; 3])> = None;
        let mut test_cell = |gx: usize, gz: usize, best: &mut Option<(f32, [f32; 3])>| {
            for &i in &self.cells[gx * self.n + gz] {
                let limit = best.map_or(t_max, |(bt, _)| bt);
                if let Some((t, nrm)) = cover[i as usize].ray_hit(o, d, limit) {
                    if best.map_or(true, |(bt, _)| t < bt) {
                        *best = Some((t, nrm));
                    }
                }
            }
        };
        // degenerate XZ direction (straight up/down): one cell column
        if d[0].abs() < 1e-8 && d[2].abs() < 1e-8 {
            let gx = (((o[0] - self.origin[0]) / self.cell).floor() as isize)
                .clamp(0, self.n as isize - 1) as usize;
            let gz = (((o[2] - self.origin[1]) / self.cell).floor() as isize)
                .clamp(0, self.n as isize - 1) as usize;
            test_cell(gx, gz, &mut best);
            return best;
        }
        // clip the ray to the grid bounds in XZ (everything sits inside)
        let (min_x, min_z) = (self.origin[0], self.origin[1]);
        let (max_x, max_z) = (
            self.origin[0] + self.cell * self.n as f32,
            self.origin[1] + self.cell * self.n as f32,
        );
        let mut t0 = 0.0_f32;
        let mut t1 = t_max;
        for (oc, dc, lo, hi) in [
            (o[0], d[0], min_x, max_x),
            (o[2], d[2], min_z, max_z),
        ] {
            if dc.abs() < 1e-8 {
                if oc < lo || oc > hi {
                    return None;
                }
            } else {
                let (mut a, mut b) = ((lo - oc) / dc, (hi - oc) / dc);
                if a > b {
                    std::mem::swap(&mut a, &mut b);
                }
                t0 = t0.max(a);
                t1 = t1.min(b);
                if t0 > t1 {
                    return None;
                }
            }
        }
        // Amanatides & Woo DDA from the entry point
        let (px, pz) = (o[0] + d[0] * t0, o[2] + d[2] * t0);
        let mut gx = (((px - self.origin[0]) / self.cell).floor() as isize)
            .clamp(0, self.n as isize - 1);
        let mut gz = (((pz - self.origin[1]) / self.cell).floor() as isize)
            .clamp(0, self.n as isize - 1);
        let step_x: isize = if d[0] > 0.0 { 1 } else { -1 };
        let step_z: isize = if d[2] > 0.0 { 1 } else { -1 };
        let next_boundary = |g: isize, step: isize, org: f32| -> f32 {
            org + self.cell * (g + if step > 0 { 1 } else { 0 }) as f32
        };
        let mut t_next_x = if d[0].abs() < 1e-8 {
            f32::INFINITY
        } else {
            (next_boundary(gx, step_x, self.origin[0]) - o[0]) / d[0]
        };
        let mut t_next_z = if d[2].abs() < 1e-8 {
            f32::INFINITY
        } else {
            (next_boundary(gz, step_z, self.origin[1]) - o[2]) / d[2]
        };
        let dt_x = if d[0].abs() < 1e-8 {
            f32::INFINITY
        } else {
            self.cell / d[0].abs()
        };
        let dt_z = if d[2].abs() < 1e-8 {
            f32::INFINITY
        } else {
            self.cell / d[2].abs()
        };
        loop {
            test_cell(gx as usize, gz as usize, &mut best);
            // the exit-t of this cell: a found hit closer than it is final
            let t_exit = t_next_x.min(t_next_z);
            if let Some((bt, _)) = best {
                if bt <= t_exit {
                    return best;
                }
            }
            if t_exit > t1 {
                return best;
            }
            if t_next_x < t_next_z {
                gx += step_x;
                if gx < 0 || gx >= self.n as isize {
                    return best;
                }
                t_next_x += dt_x;
            } else {
                gz += step_z;
                if gz < 0 || gz >= self.n as isize {
                    return best;
                }
                t_next_z += dt_z;
            }
        }
    }
}

// ------------------------------------------------------------------- maps

/// v5: three battlefields. Same arena bounds, same pickup lanes, different
/// architecture — the sim owns the layout so every map stays deterministic.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MapKind {
    /// The original dusty range: plateaus, stairs, center tower.
    Arena,
    /// A castle courtyard: central keep, corner drum towers, bailey walls.
    Bailey,
    /// Castle gardens: hedge lanes, ruined walls, trees, a stone gazebo.
    Gardens,
    /// §9.2 Battle tier (400×400 m): keep, forge district, cathedral
    /// ruin, river field with bridges, corner watchtowers to 36 m —
    /// verticality for the Robot Suit, ground routes for everyone else.
    Battlefield,
    /// §owner CLIFFHOLD (600×600 m): a castle on a cliff over half a
    /// city. Built for the flight that is coming — real OCCUPIED
    /// altitude bands (0 / 5-6 / 11-12 / 18 / 24-25 / 32 m) rather than
    /// a flat map with tall walls, so rooftops, benches and parapets are
    /// places rather than scenery. Every band is also reachable on foot,
    /// because the map has to play today.
    Cliffhold,
}

impl MapKind {
    pub fn name(self) -> &'static str {
        match self {
            MapKind::Arena => "DUST ARENA",
            MapKind::Bailey => "CASTLE BAILEY",
            MapKind::Gardens => "CASTLE GARDENS",
            MapKind::Battlefield => "BATTLEFIELD",
            MapKind::Cliffhold => "CLIFFHOLD",
        }
    }
    pub const ALL: [MapKind; 5] = [
        MapKind::Arena,
        MapKind::Bailey,
        MapKind::Gardens,
        MapKind::Battlefield,
        MapKind::Cliffhold,
    ];
}

/// §owner CLIFFHOLD: the height of every riser on the map, and the one
/// number that makes an eighteen-metre cliff walkable by BOTH a player
/// and a bot.
///
/// It has to clear two independent ceilings, and it is the lower of the
/// two that binds:
///
/// * `STEP_UP` (0.55 m) — the legs. Above it a soldier is stopped dead
///   by the tread; the mech, on `STEP_UP * MECH_SCALE`, would still walk
///   up, and the map would be a machine-only route. That is the exact
///   player/bot-parity split this project keeps re-shipping.
/// * `BOT_PROBE_Y` (0.75 m) — the eyes. `bot_act` fires ONE 1.2 m
///   whisker at that height and veers hard perpendicular if it is
///   blocked, so a tread that pokes above the probe reads to a bot as a
///   wall and it slides off the flight sideways. Bots have no vertical
///   pathing at all; a riser under the probe is the whole reason they
///   can climb anything.
pub const STAIR_RISE_M: f32 = 0.5;

/// §9.3: the soft flight ceiling — thrusters above this get pushed back
/// down, so aerial play stays inside the fight.
pub const SOFT_CEILING_M: f32 = 120.0;

/// What a cover block is MADE of — the client picks materials by this.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CoverKind {
    Crate,
    Stone,
    Hedge,
    Tree,
}

/// Everything a map defines: its architecture, its size, and where the
/// two respawn checkpoints sit.
struct MapLayout {
    cover: Vec<Aabb>,
    kind: Vec<CoverKind>,
    center_top: f32,
    half: f32,
    checkpoints: [[f32; 2]; 2],
}

/// A rectangle, in FINAL (post-scale) metres, the shared infill pass is
/// not allowed to drop furniture into: `[x0, z0, x1, z1]`.
///
/// The infill exists to stop a widened map being empty, and it scatters
/// its blocks at ground level by radius from the origin — which is fine
/// on a flat arena and wrong on a mountain, where "ground level" is
/// eighteen metres inside solid rock. A crate buried in a cliff is not
/// cover, it is a crate-shaped hole in the client's silhouette.
///
/// Empty for every map that predates this, so the infill's RNG draw
/// sequence is untouched for all of them.
type NoInfill = [f32; 4];

/// Build a map's cover set. The KOTH hill and the robot armor crown the
/// center structure, whatever its height. Pickup lanes stay clear on
/// every map. v6: castle maps grew (§10) — more room, more cover, and
/// real vertical layering (ramparts, terraces) with stairs up.
fn build_map(map: MapKind, rng: &mut Pcg32) -> MapLayout {
    let mut cover: Vec<Aabb> = Vec::new();
    let mut kind: Vec<CoverKind> = Vec::new();
    let push = |c: &mut Vec<Aabb>, k: &mut Vec<CoverKind>, a: Aabb, ck: CoverKind| {
        c.push(a);
        k.push(ck);
    };
    // shared center structure: a climbable block with stairs on both z sides
    let center = |cover: &mut Vec<Aabb>, kind: &mut Vec<CoverKind>, h: f32, steps: usize| {
        cover.push(Aabb {
            min: [-4.0, 0.0, -4.0],
            max: [4.0, h, 4.0],
        });
        kind.push(CoverKind::Stone);
        for s in 0..steps {
            let sh = (h / steps as f32) * (steps - s) as f32;
            let zoff = 4.0 + s as f32;
            cover.push(Aabb {
                min: [-2.0, 0.0, zoff],
                max: [2.0, sh, zoff + 1.0],
            });
            kind.push(CoverKind::Stone);
            cover.push(Aabb {
                min: [-2.0, 0.0, -zoff - 1.0],
                max: [2.0, sh, -zoff],
            });
            kind.push(CoverKind::Stone);
        }
    };
    let top;
    let half;
    let checkpoints;
    // set pieces the shared infill below must keep out of — see `NoInfill`
    let mut no_infill: Vec<NoInfill> = Vec::new();
    match map {
        MapKind::Arena => {
            half = ARENA_HALF;
            checkpoints = [[24.5, 0.0], [-24.5, 0.0]]; // the plateau tops
            // side plateaus (mirrored): 2.2 m high with stair slabs
            for sx in [-1.0_f32, 1.0] {
                let px = sx * (ARENA_HALF - 9.0);
                push(&mut cover, &mut kind, Aabb {
                    min: [px - 6.0, 0.0, -7.0],
                    max: [px + 6.0, 2.2, 7.0],
                }, CoverKind::Stone);
                for s in 0..4 {
                    let h = 0.55 * (4 - s) as f32;
                    let zoff = 7.0 + s as f32 * 1.1;
                    push(&mut cover, &mut kind, Aabb {
                        min: [px - 3.0, 0.0, zoff],
                        max: [px + 3.0, h, zoff + 1.1],
                    }, CoverKind::Stone);
                    push(&mut cover, &mut kind, Aabb {
                        min: [px - 3.0, 0.0, -zoff - 1.1],
                        max: [px + 3.0, h, -zoff],
                    }, CoverKind::Stone);
                }
            }
            center(&mut cover, &mut kind, 3.0, 6);
            top = 3.0;
            // scattered crates (mirrored pairs) — but never over a pickup
            // lane: a tall crate under a pad snaps the pickup onto a top
            // nobody can reach for the whole match
            for i in 0..9 {
                let x = rng.range(-ARENA_HALF + 5.0, ARENA_HALF - 5.0);
                let z = rng.range(6.0, ARENA_HALF - 6.0);
                let w = rng.range(0.9, 2.2);
                let h = if i % 3 == 0 { 2.1 } else { 1.3 };
                let d = rng.range(0.9, 2.2);
                let blocks_lane = [(19.0_f32, 14.0_f32), (-19.0, 14.0)]
                    .iter()
                    .any(|&(lx, lz)| {
                        (x - lx).abs() < w + 1.6 && (z - lz).abs() < d + 1.6
                    });
                if blocks_lane {
                    continue;
                }
                for sz in [1.0_f32, -1.0] {
                    push(&mut cover, &mut kind, Aabb {
                        min: [x - w, 0.0, sz * z - d],
                        max: [x + w, h, sz * z + d],
                    }, CoverKind::Crate);
                }
            }
            // low-ground trench walls flanking mid
            for sx in [-1.0_f32, 1.0] {
                push(&mut cover, &mut kind, Aabb {
                    min: [sx * 12.0 - 0.6, 0.0, -10.0],
                    max: [sx * 12.0 + 0.6, 1.5, 10.0],
                }, CoverKind::Stone);
            }
        }
        MapKind::Bailey => {
            half = 40.0;
            checkpoints = [[20.0, 0.0], [-20.0, 0.0]];
            // the keep — taller than the arena tower, same stair grammar
            center(&mut cover, &mut kind, 3.0, 6);
            top = 3.0;
            // corner drum towers: solid, unclimbable, fight around them
            for sx in [-1.0_f32, 1.0] {
                for sz in [-1.0_f32, 1.0] {
                    push(&mut cover, &mut kind, Aabb {
                        min: [sx * 30.0 - 2.5, 0.0, sz * 30.0 - 2.5],
                        max: [sx * 30.0 + 2.5, 3.4, sz * 30.0 + 2.5],
                    }, CoverKind::Stone);
                }
            }
            // bailey cross-walls with a wide-open center gate
            for sz in [-1.0_f32, 1.0] {
                for (x0, x1) in [(-28.0_f32, -8.0), (8.0, 28.0)] {
                    push(&mut cover, &mut kind, Aabb {
                        min: [x0, 0.0, sz * 18.0 - 0.6],
                        max: [x1, 2.6, sz * 18.0 + 0.6],
                    }, CoverKind::Stone);
                }
            }
            // RAMPARTS (v6 vertical layering): climbable wall-walks along
            // both flanks with stairs at each end — high ground with two
            // ways up and full exposure while you hold it
            for sx in [-1.0_f32, 1.0] {
                let px = sx * (half - 5.0);
                push(&mut cover, &mut kind, Aabb {
                    min: [px - 2.0, 0.0, -12.0],
                    max: [px + 2.0, 2.6, 12.0],
                }, CoverKind::Stone);
                for s in 0..5 {
                    let h = 0.52 * (5 - s) as f32;
                    let zoff = 12.0 + s as f32 * 1.05;
                    push(&mut cover, &mut kind, Aabb {
                        min: [px - 1.5, 0.0, zoff],
                        max: [px + 1.5, h, zoff + 1.05],
                    }, CoverKind::Stone);
                    push(&mut cover, &mut kind, Aabb {
                        min: [px - 1.5, 0.0, -zoff - 1.05],
                        max: [px + 1.5, h, -zoff],
                    }, CoverKind::Stone);
                }
                // parapet lip on the rampart's inner edge: hard cover up top
                push(&mut cover, &mut kind, Aabb {
                    min: [px - sx * 2.0 - 0.2, 0.0, -12.0],
                    max: [px - sx * 2.0 + 0.2, 3.3, -8.0],
                }, CoverKind::Stone);
                push(&mut cover, &mut kind, Aabb {
                    min: [px - sx * 2.0 - 0.2, 0.0, 8.0],
                    max: [px - sx * 2.0 + 0.2, 3.3, 12.0],
                }, CoverKind::Stone);
            }
            // stables clutter: crates + low walls in the yard, mirrored
            for (x, z, w, h, d) in [
                (6.0_f32, 10.0_f32, 1.2_f32, 1.3_f32, 1.2_f32),
                (-17.0, 7.0, 1.5, 1.3, 1.0),
                (22.0, 5.5, 1.0, 2.1, 1.0),
                (13.0, 24.0, 1.4, 1.3, 1.1),
                (-6.0, 26.0, 1.1, 2.1, 1.1),
            ] {
                for sz in [1.0_f32, -1.0] {
                    push(&mut cover, &mut kind, Aabb {
                        min: [-x - w, 0.0, sz * z - d],
                        max: [-x + w, h, sz * z + d],
                    }, CoverKind::Crate);
                    push(&mut cover, &mut kind, Aabb {
                        min: [x - w, 0.0, -sz * z - d],
                        max: [x + w, h, -sz * z + d],
                    }, CoverKind::Crate);
                }
            }
            // low chapel ruins flanking the keep
            for sx in [-1.0_f32, 1.0] {
                push(&mut cover, &mut kind, Aabb {
                    min: [sx * 12.0 - 0.6, 0.0, -6.0],
                    max: [sx * 12.0 + 0.6, 1.5, 6.0],
                }, CoverKind::Stone);
            }
        }
        MapKind::Gardens => {
            half = 38.0;
            checkpoints = [[24.0, 0.0], [-24.0, 0.0]];
            // the stone gazebo: lower than the keep, easier to storm
            center(&mut cover, &mut kind, 2.4, 5);
            top = 2.4;
            // hedge lanes flanking mid (trimmed, waist-to-shoulder high)
            for sx in [-1.0_f32, 1.0] {
                push(&mut cover, &mut kind, Aabb {
                    min: [sx * 12.0 - 0.5, 0.0, -10.0],
                    max: [sx * 12.0 + 0.5, 1.5, 10.0],
                }, CoverKind::Hedge);
            }
            // cross hedges with center gaps — two rings now
            for sz in [-1.0_f32, 1.0] {
                for (x0, x1) in [(-20.0_f32, -6.0), (6.0, 20.0)] {
                    push(&mut cover, &mut kind, Aabb {
                        min: [x0, 0.0, sz * 20.0 - 0.5],
                        max: [x1, 1.5, sz * 20.0 + 0.5],
                    }, CoverKind::Hedge);
                }
                for (x0, x1) in [(-16.0_f32, -4.0), (4.0, 16.0)] {
                    push(&mut cover, &mut kind, Aabb {
                        min: [x0, 0.0, sz * 28.0 - 0.5],
                        max: [x1, 1.5, sz * 28.0 + 0.5],
                    }, CoverKind::Hedge);
                }
            }
            // garden TERRACES (v6 vertical layering): raised platforms on
            // the mid-line with steps on the center-facing side
            for sz in [-1.0_f32, 1.0] {
                push(&mut cover, &mut kind, Aabb {
                    min: [-4.0, 0.0, sz * 24.0 - 2.0],
                    max: [4.0, 1.2, sz * 24.0 + 2.0],
                }, CoverKind::Stone);
                // steps descend from the terrace edge (|z| = 22) toward
                // center: 1.2 → 0.8 → 0.4, each riser within STEP_UP
                for s in 0..3 {
                    let h = 0.4 * (3 - s) as f32;
                    let near = 22.0 - s as f32 * 0.9; // edge closest to terrace
                    let (z0, z1) = if sz > 0.0 {
                        (near - 0.9, near)
                    } else {
                        (-near, -(near - 0.9))
                    };
                    push(&mut cover, &mut kind, Aabb {
                        min: [-2.0, 0.0, z0],
                        max: [2.0, h, z1],
                    }, CoverKind::Stone);
                }
            }
            // ruined garden walls on the diagonals (vaultable)
            for s in [-1.0_f32, 1.0] {
                push(&mut cover, &mut kind, Aabb {
                    min: [s * 16.0 - 4.0, 0.0, s * 7.0 - 0.5],
                    max: [s * 16.0 + 4.0, 1.1, s * 7.0 + 0.5],
                }, CoverKind::Stone);
                push(&mut cover, &mut kind, Aabb {
                    min: [-s * 16.0 - 4.0, 0.0, s * 11.0 - 0.5],
                    max: [-s * 16.0 + 4.0, 1.1, s * 11.0 + 0.5],
                }, CoverKind::Stone);
                // fountain-basin ruins on the far flanks
                push(&mut cover, &mut kind, Aabb {
                    min: [s * 30.0 - 2.0, 0.0, -2.0],
                    max: [s * 30.0 + 2.0, 0.9, 2.0],
                }, CoverKind::Stone);
            }
            // old trees: trunk is the collider, the client crowns them
            for (x, z) in [
                (23.0_f32, 9.0_f32),
                (-23.0, -9.0),
                (-23.0, 9.0),
                (23.0, -9.0),
                (9.0, 31.0),
                (-9.0, -31.0),
                (17.0, -15.0),
                (-17.0, 15.0),
            ] {
                push(&mut cover, &mut kind, Aabb {
                    min: [x - 0.3, 0.0, z - 0.3],
                    max: [x + 0.3, 2.8, z + 0.3],
                }, CoverKind::Tree);
            }
        }
        MapKind::Battlefield => {
            // §9.2 the Battle tier: 400×400 m. Set pieces give the map
            // its shape (§9.4); the §9.1 grid keeps rays cheap at this
            // scale; ground routes stay viable everywhere (§9.3).
            half = 200.0;
            checkpoints = [[150.0, 0.0], [-150.0, 0.0]];
            // THE KEEP: an 8 m block crowned by the armor pad/hill, with
            // a long climbable stair running south
            push(&mut cover, &mut kind, Aabb {
                min: [-8.0, 0.0, -8.0],
                max: [8.0, 8.0, 8.0],
            }, CoverKind::Stone);
            for s in 0..16 {
                let h = 8.0 - s as f32 * 0.5;
                let z0 = 8.0 + s as f32 * 1.2;
                push(&mut cover, &mut kind, Aabb {
                    min: [-2.5, 0.0, z0],
                    max: [2.5, h, z0 + 1.2],
                }, CoverKind::Stone);
            }
            top = 8.0;
            // corner WATCHTOWERS to 36 m — flight targets with rooftops;
            // ground fighters use them as landmarks, not ladders
            for sx in [-1.0_f32, 1.0] {
                for sz in [-1.0_f32, 1.0] {
                    let (cx, cz) = (sx * 170.0, sz * 170.0);
                    push(&mut cover, &mut kind, Aabb {
                        min: [cx - 3.5, 0.0, cz - 3.5],
                        max: [cx + 3.5, 36.0, cz + 3.5],
                    }, CoverKind::Stone);
                }
            }
            // FORGE DISTRICT (southwest): a work-yard grid of shops with
            // chimneys — the blacksmith hook from the project brief
            for gx in 0..4 {
                for gz in 0..4 {
                    let (bx, bz) = (-130.0 + gx as f32 * 20.0, -130.0 + gz as f32 * 20.0);
                    push(&mut cover, &mut kind, Aabb {
                        min: [bx, 0.0, bz],
                        max: [bx + 9.0, 4.0, bz + 9.0],
                    }, CoverKind::Stone);
                    if (gx + gz) % 2 == 0 {
                        push(&mut cover, &mut kind, Aabb {
                            min: [bx + 6.5, 0.0, bz + 6.5],
                            max: [bx + 8.5, 9.0, bz + 8.5],
                        }, CoverKind::Stone);
                    }
                }
            }
            // CATHEDRAL RUIN (northeast): two long walls + a column line
            push(&mut cover, &mut kind, Aabb {
                min: [70.0, 0.0, 70.0],
                max: [72.0, 10.0, 130.0],
            }, CoverKind::Stone);
            push(&mut cover, &mut kind, Aabb {
                min: [98.0, 0.0, 70.0],
                max: [100.0, 10.0, 130.0],
            }, CoverKind::Stone);
            for c in 0..6 {
                let cz = 74.0 + c as f32 * 10.0;
                push(&mut cover, &mut kind, Aabb {
                    min: [84.0, 0.0, cz],
                    max: [86.5, 12.0, cz + 2.5],
                }, CoverKind::Stone);
            }
            // RIVER FIELD: the |x| band around z=±? — an open crossing
            // lane |z|<14 kept clear of clutter, with three low bridges
            for bx in [-120.0_f32, 0.0, 120.0] {
                if bx == 0.0 {
                    continue; // the keep stair owns the center crossing
                }
                push(&mut cover, &mut kind, Aabb {
                    min: [bx - 6.0, 0.0, -16.0],
                    max: [bx + 6.0, 1.2, 16.0],
                }, CoverKind::Stone);
            }
            // §12.2 adventure landmarks: a RUINED SETTLEMENT to navigate
            // by (northwest), a FOREST stretch (southeast), and the MINE
            // MOUTH framing the extraction corner — the map teaches its
            // own route
            for (rx, rz) in [
                (-70.0_f32, 50.0_f32),
                (-52.0, 64.0),
                (-66.0, 76.0),
                (-46.0, 44.0),
                (-80.0, 62.0),
            ] {
                push(&mut cover, &mut kind, Aabb {
                    min: [rx, 0.0, rz],
                    max: [rx + 7.0, 2.6, rz + 1.2],
                }, CoverKind::Stone);
                push(&mut cover, &mut kind, Aabb {
                    min: [rx, 0.0, rz + 4.0],
                    max: [rx + 1.2, 3.2, rz + 8.0],
                }, CoverKind::Stone);
            }
            for k in 0..14 {
                let tx = 44.0 + (k % 5) as f32 * 18.0 + ((k * 37) % 7) as f32;
                let tz = -128.0 + (k / 5) as f32 * 22.0 + ((k * 53) % 9) as f32;
                push(&mut cover, &mut kind, Aabb {
                    min: [tx - 0.4, 0.0, tz - 0.4],
                    max: [tx + 0.4, 3.4, tz + 0.4],
                }, CoverKind::Tree);
            }
            // the mine mouth: two jambs + a lintel at the extraction corner
            push(&mut cover, &mut kind, Aabb {
                min: [158.0, 0.0, 174.0],
                max: [162.0, 6.0, 186.0],
            }, CoverKind::Stone);
            push(&mut cover, &mut kind, Aabb {
                min: [174.0, 0.0, 158.0],
                max: [186.0, 6.0, 162.0],
            }, CoverKind::Stone);
            // scattered crate clutter, never in the river band and never
            // on the pickup lanes
            for _ in 0..60 {
                let x = rng.range(-190.0, 190.0);
                let z = rng.range(-190.0, 190.0);
                if z.abs() < 16.0 {
                    continue; // river field stays open
                }
                if x.abs() < 32.0 && z.abs() < 34.0 {
                    continue; // keep + stair + pads stay clear
                }
                if x > 145.0 && z > 140.0 {
                    continue; // the extraction corner stays readable
                }
                let w = rng.range(1.0, 2.6);
                let h = rng.range(1.1, 2.4);
                let d = rng.range(1.0, 2.6);
                push(&mut cover, &mut kind, Aabb {
                    min: [x - w, 0.0, z - d],
                    max: [x + w, h, z + d],
                }, CoverKind::Crate);
            }
        }
        MapKind::Cliffhold => {
            build_cliffhold(&mut cover, &mut kind, &mut no_infill);
            half = CLIFFHOLD_HALF_M / MAP_SCALE;
            checkpoints = [
                // the city street crossing, on the floor of the low band
                [CH_CHECKPOINT_CITY[0] / MAP_SCALE, CH_CHECKPOINT_CITY[1] / MAP_SCALE],
                // the castle courtyard, eighteen metres up
                [CH_CHECKPOINT_KEEP[0] / MAP_SCALE, CH_CHECKPOINT_KEEP[1] / MAP_SCALE],
            ];
            top = CH_PLAZA_TOP;
        }
    }
    // ---- §owner MAP EXPANSION: every map, 25% bigger -------------------
    //
    // Applied here rather than by editing several hundred hand-placed
    // coordinates across six layouts, and applied in a specific way that
    // is the whole point of doing it centrally.
    //
    // POSITIONS scale. EXTENTS DO NOT. Growing the blocks along with the
    // map would leave the layout identical and just change the units -
    // the same fight at a different zoom. Moving them apart while they
    // stay the size a person hides behind is what actually makes the
    // space bigger: the GAPS grow, the cover does not.
    //
    // HEIGHT never scales, on either axis of that decision. Cover height
    // is a gameplay contract - waist-high is waist-high, this crate is
    // vaultable, that wall is not - and it is wired into crouch, the hit
    // bands, and the step-up. A 25% taller world would silently
    // re-tune all three.
    for a in cover.iter_mut() {
        for i in [0usize, 2] {
            let c = (a.min[i] + a.max[i]) * 0.5;
            let e = (a.max[i] - a.min[i]) * 0.5;
            let nc = c * MAP_SCALE;
            a.min[i] = nc - e;
            a.max[i] = nc + e;
        }
    }
    let half = half * MAP_SCALE;
    let checkpoints = [
        [checkpoints[0][0] * MAP_SCALE, checkpoints[0][1] * MAP_SCALE],
        [checkpoints[1][0] * MAP_SCALE, checkpoints[1][1] * MAP_SCALE],
    ];

    // ---- and the INFILL, because a bigger map is a worse map empty ----
    //
    // Spreading the layout opens a ring of dead ground between the old
    // edge and the new one, plus slack between everything that moved
    // apart. This is what the brief means by "avoid excessive empty
    // spaces" and "improve traversal routes": ground with nothing on it
    // is ground nobody crosses.
    //
    // Everything here is drawn from the map's OWN rng, so a seed still
    // reproduces its map exactly and the replay tests are untouched.
    {
        let old_half = half / MAP_SCALE;
        // ...and out of the map's own SET PIECES. Empty on every map
        // that predates `NoInfill`, so their draw sequences are byte
        // for byte what they were.
        let blocked = |x: f32, z: f32| -> bool {
            no_infill
                .iter()
                .any(|r| x > r[0] && x < r[2] && z > r[1] && z < r[3])
        };
        // 1. the OUTER RING - staggered blocks in the new band, at three
        //    heights so it is a broken skyline rather than a fence.
        //    Skipped near the checkpoints so the spawn approaches stay
        //    open.
        let ring_r = (old_half + half) * 0.5;
        let n_ring = 22;
        for i in 0..n_ring {
            let a = i as f32 / n_ring as f32 * std::f32::consts::TAU;
            let jitter = rng.range(-0.09, 0.09);
            let r = ring_r + rng.range(-2.4, 2.4);
            let (x, z) = ((a + jitter).cos() * r, (a + jitter).sin() * r);
            // KEEP OUT of the spawn rows. `spawn_point` puts both teams
            // at z = +-(half - 2.5), which is the same band this ring
            // wants - so without this the very first thing the expansion
            // did was bury eight fighters inside a crate. The band is
            // generous because a spawn you have to walk out of sideways
            // is barely better than one you start inside.
            if z.abs() > half - SPAWN_CLEAR_M {
                continue;
            }
            // and keep the checkpoint approaches open
            if checkpoints
                .iter()
                .any(|c| (c[0] - x).powi(2) + (c[1] - z).powi(2) < 8.0 * 8.0)
            {
                continue;
            }
            if blocked(x, z) {
                continue;
            }
            let h = match i % 3 {
                0 => rng.range(0.9, 1.3),  // vaultable
                1 => rng.range(1.6, 2.2),  // shoulder - shoot over crouched
                _ => rng.range(2.6, 3.4),  // hard cover
            };
            let w = rng.range(1.6, 3.2);
            let d = rng.range(1.6, 3.2);
            push(&mut cover, &mut kind, Aabb {
                min: [x - w, 0.0, z - d],
                max: [x + w, h, z + d],
            }, if i % 4 == 0 { CoverKind::Crate } else { CoverKind::Stone });
        }
        // 2. MID-FIELD STEPPING STONES - low pairs on the diagonals, so
        //    crossing the widened middle is a route with beats on it and
        //    not a sprint across a plate.
        for i in 0..8 {
            let a = i as f32 / 8.0 * std::f32::consts::TAU + 0.39;
            let r = old_half * rng.range(0.42, 0.72);
            let (x, z) = (a.cos() * r, a.sin() * r);
            if blocked(x, z) {
                continue;
            }
            for k in 0..2 {
                let off = k as f32 * 2.6 - 1.3;
                let h = rng.range(0.85, 1.25);
                push(&mut cover, &mut kind, Aabb {
                    min: [x - 1.4 + off, 0.0, z - 1.0],
                    max: [x + 1.4 + off, h, z + 1.0],
                }, CoverKind::Crate);
            }
        }
        // 3. FLANK LANES - long low walls set at an angle to the main
        //    axis, which is what turns extra width into a ROUTE instead
        //    of extra emptiness. Two per corner quadrant.
        for qx in [-1.0_f32, 1.0] {
            for qz in [-1.0_f32, 1.0] {
                for k in 0..2 {
                    let bx = qx * old_half * rng.range(0.55, 0.80);
                    let bz = qz * old_half * rng.range(0.55, 0.80);
                    if blocked(bx, bz) {
                        continue;
                    }
                    let long = rng.range(5.0, 8.5);
                    let h = rng.range(1.1, 1.7);
                    // alternate the lane's axis so the pair forms a
                    // dog-leg rather than a corridor
                    let (w, d) = if k == 0 { (long, 0.9) } else { (0.9, long) };
                    push(&mut cover, &mut kind, Aabb {
                        min: [bx - w, 0.0, bz - d],
                        max: [bx + w, h, bz + d],
                    }, CoverKind::Stone);
                }
            }
        }
    }

    MapLayout {
        cover,
        kind,
        center_top: top,
        half,
        checkpoints,
    }
}

// ------------------------------------------------------ §owner CLIFFHOLD

/// Cliffhold's playable half-extent, in FINAL metres: a 600 x 600 m
/// field, half again the Arena and a fifth bigger than the Battlefield.
pub const CLIFFHOLD_HALF_M: f32 = 300.0;
/// The muster plaza at the map origin — the KOTH hill and the contested
/// chassis pad both crown it, so it has to be a real, climbable place.
pub const CH_PLAZA_TOP: f32 = 7.0;
/// The cliff top, the castle courtyard floor, and the top of every
/// approach: Cliffhold's headline band.
pub const CH_PLATEAU: f32 = 18.0;
/// The curtain wall-walk, six metres above its own courtyard.
pub const CH_RAMPART: f32 = 24.0;
/// The keep parapet — the highest surface a man can stand on unaided.
pub const CH_KEEP_TOP: f32 = 32.0;
/// The city's low roof course and the aqueduct deck.
pub const CH_ROOF_LOW: f32 = 5.0;
/// The mesa's eastern apron, the gentle side.
pub const CH_BENCH_EAST: f32 = 6.0;
/// The middle shelf, west and east alike.
pub const CH_SHELF: f32 = 12.0;
/// The two capture rings, in FINAL metres (x, z): one on the city floor,
/// one in the castle courtyard eighteen metres up. Deliberately NOT
/// mirrored across the origin the way the older maps' are — a map about
/// height whose two objectives sit at the same altitude would be lying.
pub const CH_CHECKPOINT_CITY: [f32; 2] = [-132.0, -134.0];
pub const CH_CHECKPOINT_KEEP: [f32; 2] = [0.0, 175.0];
/// Where the keep's own floor is measured, for the tests that prove the
/// centrepiece is a building rather than a block.
pub const CH_KEEP_INNER: [f32; 4] = [-31.0, 164.0, -9.0, 186.0];
/// The keep's doorway gap, in x, on the z = 160..164 south wall.
pub const CH_KEEP_DOOR_X: [f32; 2] = [-27.0, -13.0];

/// §owner CLIFFHOLD — a castle on a cliff above half a city.
///
/// THE ASK was a bigger, messier map built around VERTICAL difference,
/// because flight is coming. So the thing that had to be got right is
/// not the silhouette, it is that the altitude bands are OCCUPIED:
/// rooftops with floors on them, benches you can hold, a cliff with a
/// playable top and a playable bottom, a keep you walk into. A flat map
/// with tall walls looks the same from the ground and has to be thrown
/// away the day thrusters land.
///
/// The bands, and what is on them:
///
/// ```text
///   32 m  keep parapet         highest unaided surface
///   24 m  curtain wall-walk    ring route round the courtyard
///   18 m  THE PLATEAU          cliff top + castle courtyard
///   12 m  west bench / east shelf
///  5-6 m  city roofs, aqueduct deck, mesa apron
///    7 m  the muster plaza     the KOTH hill, at the map origin
///    0 m  city streets, commons, ravine floor, both spawn plains
/// ```
///
/// LAID OUT IN FINAL METRES and divided back out by `MAP_SCALE` on the
/// way into the box list. That is not a convenience. The central +25%
/// pass moves box CENTRES and leaves EXTENTS alone — correct, and the
/// whole point of doing it centrally — but the corollary is that two
/// slabs which abut before it are a quarter of their centre distance
/// APART after it. On furniture that is a slightly wider gap; on a
/// mountain assembled from overlapping slabs it is a crack you fall
/// eighteen metres down. Designing in the output space removes the
/// class of bug rather than paying attention to it.
///
/// WHAT THE BOTS CAN AND CANNOT DO WITH IT. There is no pathfinder in
/// this project — `Fighter::waypoint` is `[f32; 2]`, x and z, with no
/// height component at all; `bot_think` samples it uniformly from a
/// square of half-extent `self.half` and never checks it for
/// reachability; `bot_act` steers straight at it behind a single 1.2 m
/// whisker at `BOT_PROBE_Y`. So a bot cannot CHOOSE to go up, ever, and
/// a good share of its sampled waypoints land inside this mountain.
///
/// The map is built anyway, and deliberately not shaped down to what the
/// AI copes with today — that answer is "nothing vertical", which is the
/// map this one exists to replace. What IS shaped for it is cheap and
/// worth having: the two long flights are aimed down the x = 0 line, the
/// same line the castle capture ring sits on and the same line both
/// spawn rows straddle, so a bot walking straight at the objective walks
/// onto a flight rather than into a wall; and every riser clears
/// `BOT_PROBE_Y`, so a bot that lands on one climbs instead of veering.
/// Real navigation is WORK TO BE BUDGETED, not a constraint that got
/// designed around here.
///
/// WHAT IT DOES NOT DO: there are no overhangs, arches, tunnels or
/// bridge spans anywhere on this map, and there cannot be. The support
/// rule in the integrate loop stands a body on the tallest box top
/// within its step-up and pushes it out of everything else — a box has
/// a top and no underside, so a deck at 18 m is a solid mass from the
/// ground up. Every "building" here is therefore a solid mass or a ring
/// of walls around an open court. The keep is the second kind, on
/// purpose.
fn build_cliffhold(
    cover: &mut Vec<Aabb>,
    kind: &mut Vec<CoverKind>,
    no_infill: &mut Vec<NoInfill>,
) {
    // a box given in FINAL metres — see the note above on why
    let slab = |cover: &mut Vec<Aabb>,
                kind: &mut Vec<CoverKind>,
                x0: f32,
                z0: f32,
                x1: f32,
                z1: f32,
                h: f32,
                ck: CoverKind| {
        let (ex, ez) = ((x1 - x0) * 0.5, (z1 - z0) * 0.5);
        let (cx, cz) = ((x0 + x1) * 0.5 / MAP_SCALE, (z0 + z1) * 0.5 / MAP_SCALE);
        cover.push(Aabb {
            min: [cx - ex, 0.0, cz - ez],
            max: [cx + ex, h, cz + ez],
        });
        kind.push(ck);
    };
    // A CLIMBABLE RUN. `x0..x1, z0..z1` is the LOWEST tread; each
    // following one is offset by (dx, dz) — so |dx| or |dz| is the tread
    // depth and the other is zero — and stands `STAIR_RISE_M` higher.
    //
    // Treads are solid to the ground rather than floating, because they
    // have to be: see the no-overhangs note. A flight up a 12 m shelf is
    // a row of pillars whose tops happen to form a ramp.
    let flight = |cover: &mut Vec<Aabb>,
                  kind: &mut Vec<CoverKind>,
                  x0: f32,
                  z0: f32,
                  x1: f32,
                  z1: f32,
                  dx: f32,
                  dz: f32,
                  base: f32,
                  n: usize| {
        for s in 0..n {
            let k = s as f32;
            slab(
                cover,
                kind,
                x0 + dx * k,
                z0 + dz * k,
                x1 + dx * k,
                z1 + dz * k,
                base + STAIR_RISE_M * (s + 1) as f32,
                CoverKind::Stone,
            );
        }
    };

    // ---- THE MOUNTAIN ------------------------------------------------
    // One massif, assembled from nine overlapping slabs with staggered
    // edges so the cliff line reads as broken rock rather than a wall.
    // The bite out of its south face is THE RAVINE (x -18..14, open from
    // the plaza north to z = 94), and the ravine is where the frontal
    // route up lives.
    for (x0, z0, x1, z1, h) in [
        (-110.0_f32, 30.0_f32, -18.0_f32, 216.0_f32, CH_PLATEAU), // west massif, the great cliff
        (14.0, 44.0, 96.0, 216.0, CH_PLATEAU),                    // east massif, cliff line stepped back
        (-18.0, 94.0, 14.0, 216.0, CH_PLATEAU),                   // the head block: closes the ravine, joins both
        (-152.0, 70.0, -100.0, 160.0, CH_PLATEAU),                // west spur over the quarry
        (90.0, 150.0, 150.0, 200.0, CH_PLATEAU),                  // east spur
        (-62.0, 190.0, 62.0, 232.0, CH_PLATEAU),                  // the north shoulder — the mountain's back
        (-205.0, 84.0, -142.0, 176.0, CH_SHELF),                  // west bench
        (70.0, 16.0, 205.0, 150.0, CH_BENCH_EAST),                // east apron, the gentle side
        (94.0, 46.0, 178.0, 142.0, CH_SHELF),                     // east shelf
    ] {
        slab(cover, kind, x0, z0, x1, z1, h, CoverKind::Stone);
    }

    // ---- THE WAYS UP -------------------------------------------------
    // Six flights, every riser `STAIR_RISE_M`. Two of them are aimed
    // deliberately down the x = 0 line — THE BREACH out of the ravine and
    // THE NORTH ROAD off Red's plain — because a roaming bot walks a
    // STRAIGHT LINE at its waypoint and the castle checkpoint sits at
    // x = 0. A flight a bot never crosses is a flight only the player
    // uses, and that is the parity split this codebase keeps shipping.
    //
    // Every one of these is positioned so its TOP TREAD lands INSIDE the
    // slab it is climbing onto rather than flush against its face. That
    // is not tidiness. A flight that merely touches a taller neighbour
    // leaves a one-tread band of open ground between the two, and the
    // support rule drops you the whole way to zero in it — after which
    // the thing you were climbing onto is an unclimbable wall in your
    // face. The `every_cliffhold_band_is_reachable_on_foot` walker found
    // exactly this on the North Road, and it is invisible by inspection.
    for (x0, z0, x1, z1, dx, dz, base, n) in [
        // THE BREACH: 0 -> 18 up the ravine floor, 36 treads, fully
        // exposed from both rims. The frontal assault.
        (-4.0_f32, 52.0_f32, 4.0_f32, 53.2_f32, 0.0_f32, 1.2_f32, 0.0_f32, 36usize),
        // THE NORTH ROAD: 0 -> 18 up the mountain's back, off Red's plain
        (-8.0, 280.0, 8.0, 281.4, 0.0, -1.4, 0.0, 36),
        // THE GREAT STAIR: 0 -> 6 onto the east apron, twelve metres wide
        (104.0, 0.6, 116.0, 2.0, 0.0, 1.4, 0.0, 12),
        // the BENCH STAIR: 6 -> 12 onto the east shelf
        (120.0, 30.6, 130.0, 32.0, 0.0, 1.4, CH_BENCH_EAST, 12),
        // the SHOULDER STAIR: 12 -> 18, climbing west onto the plateau
        (111.0, 64.0, 112.5, 76.0, -1.5, 0.0, CH_SHELF, 12),
        // the WEST RAMP: 0 -> 12 out of the quarry onto the west bench
        (-239.5, 120.0, -238.0, 132.0, 1.5, 0.0, 0.0, 24),
        // the QUARRY STEPS: 12 -> 18, west bench onto the west spur
        (-168.5, 118.0, -167.0, 130.0, 1.5, 0.0, CH_SHELF, 12),
    ] {
        flight(cover, kind, x0, z0, x1, z1, dx, dz, base, n);
    }

    // ---- THE MUSTER PLAZA (the map origin, the KOTH hill) ------------
    // Stairs on BOTH z faces, which is the one thing the old shared
    // `center` helper got right and is worth keeping: a hill with one
    // stair is a hill one team owns, and a bot approaching the blank
    // face just slides along it.
    slab(cover, kind, -10.0, -10.0, 10.0, 10.0, CH_PLAZA_TOP, CoverKind::Stone);
    flight(cover, kind, -5.0, -25.6, 5.0, -24.4, 0.0, 1.2, 0.0, 14);
    flight(cover, kind, -5.0, 24.4, 5.0, 25.6, 0.0, -1.2, 0.0, 14);
    // corner merlons: hard cover ON the hill, clear of the 4.5 m capture
    // ring so they never wall the objective off from itself
    for (x0, z0, x1, z1) in [
        (6.0_f32, 6.0_f32, 10.0_f32, 10.0_f32),
        (-10.0, 6.0, -6.0, 10.0),
        (6.0, -10.0, 10.0, -6.0),
        (-10.0, -10.0, -6.0, -6.0),
    ] {
        slab(cover, kind, x0, z0, x1, z1, CH_PLAZA_TOP + 1.6, CoverKind::Stone);
    }

    // ---- THE CASTLE, on the plateau ----------------------------------
    // Curtain wall with a 24 m gate gap; the wall-walk is a real band at
    // 24 reached by a mural stair inside the courtyard.
    for (x0, z0, x1, z1, h) in [
        (-72.0_f32, 132.0_f32, -18.0_f32, 135.0_f32, CH_RAMPART), // south wall, west of the gate
        (6.0, 132.0, 32.0, 135.0, CH_RAMPART),                    // south wall, east of the gate
        (-72.0, 132.0, -69.0, 214.0, CH_RAMPART),                 // west wall
        (29.0, 132.0, 32.0, 214.0, CH_RAMPART),                   // east wall
        // north wall, with a POSTERN on the x = 0 line. A castle wants
        // one gate; this one gets two, because the landward face is
        // where the North Road arrives and a solid wall there would put
        // an 18 m plateau, a 36-tread climb and Red's entire approach on
        // the wrong side of it. It also happens to be the one line a
        // bot steering at the courtyard capture ring actually walks.
        (-72.0, 211.0, -6.0, 214.0, CH_RAMPART),
        (6.0, 211.0, 32.0, 214.0, CH_RAMPART),
        (-26.0, 127.0, -16.0, 141.0, 28.0),                       // gatehouse tower, west
        (4.0, 127.0, 14.0, 141.0, 28.0),                          // gatehouse tower, east
        // corner turrets: half a metre over the walk, so you can STEP on
        // them rather than admire them
        (-72.0, 132.0, -66.0, 138.0, CH_RAMPART + 0.5),
        (26.0, 132.0, 32.0, 138.0, CH_RAMPART + 0.5),
        (-72.0, 208.0, -66.0, 214.0, CH_RAMPART + 0.5),
        (26.0, 208.0, 32.0, 214.0, CH_RAMPART + 0.5),
    ] {
        slab(cover, kind, x0, z0, x1, z1, h, CoverKind::Stone);
    }
    // the mural stair, 18 -> 24, against the inside of the west wall
    flight(cover, kind, -69.0, 180.1, -62.0, 181.4, 0.0, 1.3, CH_PLATEAU, 12);

    // ---- THE KEEP ----------------------------------------------------
    // The centrepiece, and the one piece of this map with a named
    // failure to avoid: the Gardens' "stone gazebo" and the Bailey's
    // "keep" are both solid blocks nobody can enter, the second of them
    // byte-identical to the Arena's centre tower. A centrepiece you can
    // only walk AROUND is scenery with a name on it.
    //
    // So this one is FOUR WALLS AND A DOORWAY. The courtyard floor is
    // the plateau itself at 18; the gap in the south wall is fourteen
    // metres, which admits a 1.16 m-wide chassis with room to spare; and
    // a two-flight stair inside climbs 18 -> 25 -> 32 to the parapet,
    // which is the highest place on the map a man can stand.
    for (x0, z0, x1, z1) in [
        (-35.0_f32, 160.0_f32, CH_KEEP_DOOR_X[0], 164.0_f32), // south wall, west of the door
        (CH_KEEP_DOOR_X[1], 160.0, -5.0, 164.0),              // south wall, east of the door
        (-35.0, 160.0, -31.0, 190.0),                         // west wall
        (-9.0, 160.0, -5.0, 190.0),                           // east wall
        (-35.0, 186.0, -5.0, 190.0),                          // north wall
    ] {
        slab(cover, kind, x0, z0, x1, z1, CH_KEEP_TOP, CoverKind::Stone);
    }
    // first flight, 18 -> 25, north up the inside of the west wall
    flight(cover, kind, -31.0, 166.5, -26.0, 167.8, 0.0, 1.3, CH_PLATEAU, 14);
    // the half-landing that turns the stair back on itself
    slab(cover, kind, -26.0, 184.0, -14.0, 186.0, 25.0, CoverKind::Stone);
    // second flight, 25 -> 32, south up the inside of the east wall
    flight(cover, kind, -14.0, 183.4, -9.0, 184.7, 0.0, -1.3, 25.0, 14);

    // ---- THE LOWER CITY (south-west) ---------------------------------
    // "Half a city": built out to the west and centre, and simply NOT
    // built to the east, which is what leaves the commons open. The
    // grid is irregular by construction — heights come off a six-entry
    // course and a seventh of the plots are rubble — so it reads as a
    // town that grew rather than a lattice.
    const CITY_COURSE: [f32; 6] = [5.0, 8.0, 5.4, 11.0, 14.0, 7.6];
    for gx in 0..5usize {
        for gz in 0..5usize {
            let x0 = -250.0 + gx as f32 * 42.0;
            let z0 = -240.0 + gz as f32 * 38.0;
            if (gx * 5 + gz * 11) % 7 == 0 {
                // a burnt-out plot: a rubble stub, and a hole in the skyline
                slab(cover, kind, x0 + 3.0, z0 + 3.0, x0 + 20.0, z0 + 16.0, 2.4, CoverKind::Stone);
            } else {
                let h = CITY_COURSE[(gx * 7 + gz * 3) % 6];
                slab(cover, kind, x0, z0, x0 + 26.0, z0 + 22.0, h, CoverKind::Stone);
            }
        }
    }
    // a ragged sixth column, so the city does not end on a straight line
    for gz in 1..4usize {
        let z0 = -240.0 + gz as f32 * 38.0;
        let h = CITY_COURSE[(5 * 7 + gz * 3) % 6];
        slab(cover, kind, -40.0, z0, -16.0, z0 + 20.0, h, CoverKind::Stone);
    }
    // THE AQUEDUCT: a 5 m deck running the width of the city, overlapping
    // the north faces of the middle terrace by a metre so the roofs it
    // touches are one step off it — this is what makes the low roof
    // course a BAND and not five separate islands.
    // (the deck STOPS where its top tread begins — the same-height joint
    // is safe, but running the deck out over the lower treads would bury
    // half the flight under it)
    slab(cover, kind, -262.0, -143.0, -40.0, -138.0, CH_ROOF_LOW, CoverKind::Stone);
    flight(cover, kind, -29.6, -143.0, -28.3, -138.0, -1.3, 0.0, 0.0, 10);
    // and a six-tread stub off the deck onto the 8 m course. Kept to
    // 2.5 m of the deck's 5 m width so the deck stays a through route
    // under it (2.5 m still passes a 1.16 m chassis).
    //
    // §owner "what you see is what you get": with flight coming, a roof
    // that LOOKS landable had better be landable, and that call is free
    // now and expensive after an art pass. So every roof course on this
    // map is decided, not left to chance — 5.0, 5.4, 8.0 and 11.0 have
    // grounded routes; 7.6 and 14.0 are deliberately air-only and are
    // the tallest things in the city, which is how they read as such.
    flight(cover, kind, -173.0, -143.0, -171.0, -140.5, -2.0, 0.0, CH_ROOF_LOW, 6);
    // the BELL TOWER: the grounded way onto the 11 m course. Its head is
    // FLUSH with a real eleven-metre roof rather than a lonely platform
    // of its own, and it stands south of the aqueduct so the two routes
    // cross nowhere.
    slab(cover, kind, -98.0, -236.0, -84.0, -224.0, 11.0, CoverKind::Stone);
    flight(cover, kind, -95.0, -198.8, -87.0, -197.6, 0.0, -1.2, 0.0, 22);
    // two rubble ramps onto low roofs, mid-city
    flight(cover, kind, -118.0, -93.3, -110.0, -92.0, 0.0, -1.3, 0.0, 10);
    flight(cover, kind, -160.0, -100.0, -152.0, -98.7, 0.0, 1.3, 0.0, 10);

    // ---- THE COMMONS (south-east) ------------------------------------
    // The open half. Field walls, hedgerows and orchard, at heights that
    // read as cover and never as architecture — plus one earthwork
    // redoubt so the openness has a thing in it worth taking.
    for (x0, z0, x1, z1, h) in [
        (60.0_f32, -120.0_f32, 96.0_f32, -118.0_f32, 2.4_f32),
        (110.0, -96.0, 112.0, -60.0, 1.8),
        (150.0, -210.0, 186.0, -208.0, 2.8),
        (70.0, -240.0, 72.0, -206.0, 1.2),
        (196.0, -140.0, 230.0, -138.0, 2.0),
        (44.0, -180.0, 46.0, -148.0, 1.6),
        (130.0, -60.0, 166.0, -58.0, 1.4),
        (210.0, -80.0, 212.0, -46.0, 2.6),
    ] {
        slab(cover, kind, x0, z0, x1, z1, h, CoverKind::Stone);
    }
    for (x0, z0, x1, z1) in [
        (88.0_f32, -160.0_f32, 120.0_f32, -158.5_f32),
        (88.0, -160.0, 89.5, -128.0),
        (170.0, -110.0, 202.0, -108.5),
        (240.0, -170.0, 241.5, -138.0),
        (56.0, -100.0, 88.0, -98.5),
        (200.0, -230.0, 232.0, -228.5),
    ] {
        slab(cover, kind, x0, z0, x1, z1, 1.5, CoverKind::Hedge);
    }
    for (tx, tz) in [
        (50.0_f32, -70.0_f32),
        (78.0, -88.0),
        (104.0, -132.0),
        (136.0, -170.0),
        (162.0, -118.0),
        (190.0, -96.0),
        (216.0, -150.0),
        (240.0, -200.0),
        (66.0, -196.0),
        (120.0, -224.0),
        (180.0, -244.0),
        (250.0, -110.0),
    ] {
        slab(cover, kind, tx - 0.4, tz - 0.4, tx + 0.4, tz + 0.4, 3.4, CoverKind::Tree);
    }
    for (x0, z0, h) in [
        (96.0_f32, -72.0_f32, 1.6_f32),
        (102.0, -76.0, 2.2),
        (146.0, -100.0, 1.3),
        (152.0, -104.0, 2.4),
        (174.0, -62.0, 1.8),
        (58.0, -134.0, 1.4),
        (64.0, -138.0, 2.0),
        (206.0, -176.0, 1.6),
        (212.0, -180.0, 1.2),
        (128.0, -206.0, 2.2),
    ] {
        slab(cover, kind, x0, z0, x0 + 3.0, z0 + 3.0, h, CoverKind::Crate);
    }
    slab(cover, kind, 150.0, -170.0, 180.0, -140.0, 4.0, CoverKind::Stone);
    flight(cover, kind, 158.0, -180.4, 168.0, -179.1, 0.0, 1.3, 0.0, 8);

    // ---- THE CLIFF FOOT and THE QUARRY -------------------------------
    // Talus below the cliff line, so the eighteen-metre face meets the
    // ground in broken rock rather than a mitre joint; and the quarry
    // the castle was cut from, which is the west approach's low ground.
    for (x0, z0, x1, z1, h) in [
        (-104.0_f32, 20.0_f32, -96.0_f32, 28.0_f32, 3.4_f32),
        (-88.0, 16.0, -80.0, 25.0, 2.2),
        (-70.0, 22.0, -60.0, 31.0, 4.5),
        (-52.0, 14.0, -45.0, 22.0, 2.6),
        (-38.0, 20.0, -30.0, 27.0, 3.8),
        (-26.0, 12.0, -20.0, 19.0, 2.0),
        (18.0, 30.0, 26.0, 38.0, 3.2),
        (32.0, 22.0, 41.0, 30.0, 4.0),
        (46.0, 34.0, 53.0, 41.0, 2.4),
        (-14.0, 62.0, -8.0, 69.0, 2.8),
        (6.0, 74.0, 12.0, 80.0, 3.6),
        (-16.0, 40.0, -10.0, 47.0, 2.2),
        // quarry spoil
        (-248.0, -12.0, -232.0, 6.0, 6.0),
        (-226.0, 18.0, -212.0, 34.0, 4.2),
        (-250.0, 44.0, -236.0, 58.0, 7.0),
        (-206.0, -4.0, -194.0, 10.0, 3.4),
        (-190.0, 30.0, -178.0, 44.0, 5.2),
        (-232.0, 62.0, -220.0, 74.0, 3.0),
    ] {
        slab(cover, kind, x0, z0, x1, z1, h, CoverKind::Stone);
    }
    // cut blocks waiting on the quarry floor — timber-crated, so a
    // grenade behaves differently off them than off the rock they came
    // out of
    for (x0, z0, h) in [
        (-240.0_f32, 70.0_f32, 1.6_f32),
        (-228.0, 84.0, 2.2),
        (-216.0, 60.0, 1.2),
        (-244.0, 96.0, 1.8),
        (-200.0, 74.0, 1.4),
        (-186.0, 58.0, 2.6),
        (-214.0, 100.0, 1.2),
        (-232.0, 108.0, 2.0),
    ] {
        slab(cover, kind, x0, z0, x0 + 6.0, z0 + 6.0, h, CoverKind::Crate);
    }

    // ---- what the shared infill may not touch ------------------------
    // The commons is deliberately NOT listed: scattering low cover over
    // the open half is exactly what the infill is for.
    no_infill.extend_from_slice(&[
        [-245.0, 10.0, 215.0, 250.0],   // the mountain, its flights and the castle
        [-32.0, -32.0, 32.0, 12.0],     // the plaza and its south stair
        [-268.0, -252.0, -14.0, -58.0], // the lower city
        [100.0, -6.0, 122.0, 20.0],     // the Great Stair's foot
        [-255.0, -35.0, -170.0, 15.0],  // the quarry floor
        [145.0, -185.0, 185.0, -135.0], // the redoubt
    ]);
}

// --------------------------------------------------------------- fighters

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HitZone {
    Legs,
    Torso,
    Arms,
    Head,
}

impl HitZone {
    pub fn name(self) -> &'static str {
        match self {
            HitZone::Legs => "legs",
            HitZone::Torso => "torso",
            HitZone::Arms => "arms",
            HitZone::Head => "HEAD",
        }
    }
    pub fn mult(self) -> f32 {
        match self {
            HitZone::Head => HEAD_MULT,
            HitZone::Torso => 1.0,
            HitZone::Arms => ARM_MULT,
            HitZone::Legs => LEG_MULT,
        }
    }

    /// The band of the capsule this zone occupies, as a fraction of the
    /// fighter's height: (low edge, high edge).
    ///
    /// A SECOND statement of the bands `apply_hit_dmg` selects on, and
    /// deliberately so. That code needs them as comparisons and answers
    /// "which zone"; the per-piece mapping needs them as NUMBERS, to ask
    /// "how far up this zone did the round land" - and deriving one from
    /// the other would mean either rewriting a hit path that 300-odd
    /// tests stand on, or reconstructing the edges from the comparisons
    /// at the call site. Two statements that must agree are only safe if
    /// something checks they do: `the_zone_bands_and_the_piece_bands_agree`
    /// fires real rounds up the whole capsule and matches the zone the
    /// hit path REPORTS against this table.
    pub fn band(self) -> (f32, f32) {
        match self {
            HitZone::Legs => (0.00, 0.35),
            HitZone::Torso => (0.35, 0.66),
            HitZone::Arms => (0.66, 0.82),
            HitZone::Head => (0.82, 1.00),
        }
    }
}

// ------------------------------------------------------------- difficulty

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Difficulty {
    Easy,
    Normal,
    Hard,
}

impl Difficulty {
    pub fn name(self) -> &'static str {
        match self {
            Difficulty::Easy => "EASY",
            Difficulty::Normal => "NORMAL",
            Difficulty::Hard => "HARD",
        }
    }
    pub const ALL: [Difficulty; 3] = [Difficulty::Easy, Difficulty::Normal, Difficulty::Hard];
}

/// Bot brain tuning per difficulty: aim, reflexes, and aggression.
pub struct BotParams {
    pub aim_sigma: f32,
    pub reaction_s: f32,
    pub engage_range: f32,
    pub aggression: f32,
}

pub fn bot_params(d: Difficulty) -> BotParams {
    match d {
        Difficulty::Easy => BotParams {
            aim_sigma: 0.055,
            reaction_s: 0.45,
            engage_range: 22.0,
            aggression: 0.6,
        },
        Difficulty::Normal => BotParams {
            aim_sigma: 0.030,
            reaction_s: 0.28,
            engage_range: 35.0,
            aggression: 1.0,
        },
        Difficulty::Hard => BotParams {
            aim_sigma: 0.014,
            reaction_s: 0.15,
            engage_range: 50.0,
            aggression: 1.4,
        },
    }
}

// ------------------------------------------------------------ match config

/// Player-picked loadout: [primary, secondary, special]. The SHIELD is
/// always carried in its own dedicated slot — it cannot be dropped.
/// §owner: the FOUR CLASSES - a standing choice made in the Forge, not
/// a pickup found on the floor.
///
/// This is deliberately a different axis from `ArmorSet`. Armour is
/// found mid-match, covers the whole body, and can be lost; a class is
/// who you ARE for the match and shapes the four things a player feels
/// every second: how much killing you take, how fast you cross ground,
/// how tight your shots land, and how quickly a weapon comes up.
///
/// Every multiplier is relative to `Line`, which is exactly 1.0 across
/// the board on purpose - a baseline you can read the others against,
/// and a class that is never the wrong answer.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum Class {
    /// The baseline. No bonus, no penalty, no learning curve.
    #[default]
    Line,
    /// Fast and light: crosses ground and swaps weapons quickest, pays
    /// for it in health and in shots that land looser.
    Skirmisher,
    /// The anchor: soaks the most and shoots steadily, but is slow to
    /// arrive and slow to bring a weapon up.
    Warden,
    /// The precision answer: by far the tightest shots, slightly frail,
    /// and deliberately clumsy at swapping - it wants the FIRST shot.
    Marksman,
}

// ---- SEGMENT-MAPPED ARMOUR (Brief IX §C tier 2) --------------------------
//
// Armour was five whole-body PRESETS found as loot: you had a set or you
// did not, and every part of you was equally protected by it. The brief
// asks for plate you assemble piece by piece, where taking the gauntlets
// off is a real decision with a real cost on the hand that then catches a
// round.
//
// THE BRIEF'S OWN TABLE SUMS TO 24, NOT 26. Six singles (helmet, gorget,
// cuirass front and back, fauld, pelvis plate) plus nine mirrored pairs
// is 6 + 18 = 24, and the section is titled "26-piece" throughout. Built
// as 24, because the table is the specification and the title is a label
// on it; inventing two pieces to reach a round number would be building
// to the label. Recorded here rather than silently reconciled.
//
// Every piece maps onto a `HitZone` THAT ALREADY EXISTS. That is the
// whole reason this is a one-session change rather than a subsystem: the
// hit path already resolves head / arms / torso / legs, so a missing
// piece has somewhere to be missing FROM without a new geometry pass.

/// One plate. Left/right pairs are separate variants because they are
/// separately losable - the asymmetry after one pauldron goes is a thing
/// you can see at range.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArmorPiece {
    Helmet,
    Gorget,
    CuirassFront,
    CuirassBack,
    Fauld,
    PelvisPlate,
    PauldronL,
    PauldronR,
    RerebraceL,
    RerebraceR,
    VambraceL,
    VambraceR,
    GauntletL,
    GauntletR,
    TassetL,
    TassetR,
    CuisseL,
    CuisseR,
    PoleynL,
    PoleynR,
    GreaveL,
    GreaveR,
    SabatonL,
    SabatonR,
}

impl ArmorPiece {
    /// Every piece, in the order the Forge grid lists them: head down.
    pub const ALL: [ArmorPiece; ARMOR_PIECES] = [
        ArmorPiece::Helmet,
        ArmorPiece::Gorget,
        ArmorPiece::CuirassFront,
        ArmorPiece::CuirassBack,
        ArmorPiece::Fauld,
        ArmorPiece::PelvisPlate,
        ArmorPiece::PauldronL,
        ArmorPiece::PauldronR,
        ArmorPiece::RerebraceL,
        ArmorPiece::RerebraceR,
        ArmorPiece::VambraceL,
        ArmorPiece::VambraceR,
        ArmorPiece::GauntletL,
        ArmorPiece::GauntletR,
        ArmorPiece::TassetL,
        ArmorPiece::TassetR,
        ArmorPiece::CuisseL,
        ArmorPiece::CuisseR,
        ArmorPiece::PoleynL,
        ArmorPiece::PoleynR,
        ArmorPiece::GreaveL,
        ArmorPiece::GreaveR,
        ArmorPiece::SabatonL,
        ArmorPiece::SabatonR,
    ];

    /// Brief IX §C's weight table, verbatim. Pair weights are PER PIECE -
    /// the brief lists 1.0 kg x2 for a pauldron, so each one is 1.0.
    pub fn weight_kg(self) -> f32 {
        use ArmorPiece::*;
        match self {
            Helmet => 1.2,
            Gorget => 0.8,
            CuirassFront => 4.0,
            CuirassBack => 3.0,
            Fauld => 2.5,
            PelvisPlate => 1.5,
            PauldronL | PauldronR => 1.0,
            RerebraceL | RerebraceR => 1.2,
            VambraceL | VambraceR => 0.9,
            GauntletL | GauntletR => 0.6,
            TassetL | TassetR => 1.5,
            CuisseL | CuisseR => 2.0,
            PoleynL | PoleynR => 0.8,
            GreaveL | GreaveR => 1.5,
            SabatonL | SabatonR => 0.7,
        }
    }

    /// Which hit zone this plate covers.
    ///
    /// The gorget is a throat plate and rides with the HEAD, not the
    /// torso: the whole point of a gorget is that it protects the one
    /// thing a cuirass cannot reach. The fauld and pelvis plate hang at
    /// the waist and count as torso; tassets hang lower and cover the
    /// upper thigh, so they count as legs.
    pub fn zone(self) -> HitZone {
        use ArmorPiece::*;
        match self {
            Helmet | Gorget => HitZone::Head,
            CuirassFront | CuirassBack | Fauld | PelvisPlate => HitZone::Torso,
            PauldronL | PauldronR | RerebraceL | RerebraceR | VambraceL | VambraceR
            | GauntletL | GauntletR => HitZone::Arms,
            TassetL | TassetR | CuisseL | CuisseR | PoleynL | PoleynR | GreaveL
            | GreaveR | SabatonL | SabatonR => HitZone::Legs,
        }
    }

    /// The label the Forge grid puts on a pill.
    ///
    /// Shorter than `name` because the ROW already says which part of the
    /// body this is - "SHOULDERS: PAULDRON L" spends four characters
    /// repeating its own heading, and at six pills to a row that is what
    /// pushed every label onto two lines. The pair suffix stays: which
    /// side is the one thing the row cannot tell you.
    ///
    /// `name` is still the full form, for anywhere with room for it.
    pub fn short_name(self) -> &'static str {
        use ArmorPiece::*;
        match self {
            Helmet => "HELMET",
            Gorget => "GORGET",
            CuirassFront => "FRONT",
            CuirassBack => "BACK",
            Fauld => "FAULD",
            PelvisPlate => "PELVIS",
            PauldronL => "PAULDRON L",
            PauldronR => "PAULDRON R",
            RerebraceL => "REREBRACE L",
            RerebraceR => "REREBRACE R",
            VambraceL => "VAMBRACE L",
            VambraceR => "VAMBRACE R",
            GauntletL => "GAUNTLET L",
            GauntletR => "GAUNTLET R",
            TassetL => "TASSET L",
            TassetR => "TASSET R",
            CuisseL => "CUISSE L",
            CuisseR => "CUISSE R",
            PoleynL => "POLEYN L",
            PoleynR => "POLEYN R",
            GreaveL => "GREAVE L",
            GreaveR => "GREAVE R",
            SabatonL => "SABATON L",
            SabatonR => "SABATON R",
        }
    }

    pub fn name(self) -> &'static str {
        use ArmorPiece::*;
        match self {
            Helmet => "HELMET",
            Gorget => "GORGET",
            CuirassFront => "CUIRASS FRONT",
            CuirassBack => "CUIRASS BACK",
            Fauld => "FAULD",
            PelvisPlate => "PELVIS PLATE",
            PauldronL => "PAULDRON L",
            PauldronR => "PAULDRON R",
            RerebraceL => "REREBRACE L",
            RerebraceR => "REREBRACE R",
            VambraceL => "VAMBRACE L",
            VambraceR => "VAMBRACE R",
            GauntletL => "GAUNTLET L",
            GauntletR => "GAUNTLET R",
            TassetL => "TASSET L",
            TassetR => "TASSET R",
            CuisseL => "CUISSE L",
            CuisseR => "CUISSE R",
            PoleynL => "POLEYN L",
            PoleynR => "POLEYN R",
            GreaveL => "GREAVE L",
            GreaveR => "GREAVE R",
            SabatonL => "SABATON L",
            SabatonR => "SABATON R",
        }
    }

    /// **Which PLATE a hit landed on**, given the zone the hit path
    /// already resolved, how far up the capsule it landed, and which side
    /// and face of the body the impact point sits on.
    ///
    /// This is the whole reason armour damage states waited: the hit path
    /// names a ZONE, and per-piece HP needs it to name a PIECE. A zone
    /// holds between two and ten plates, so something has to choose.
    ///
    /// Three answers were considered:
    ///
    /// 1. **Roll for it.** One seeded draw per hit picks a plate in the
    ///    zone. REJECTED outright - it inserts an RNG call into the
    ///    hottest path in the sim, which moves every subsequent draw and
    ///    breaks the bit-identical replay guarantee for every OTHER
    ///    system. Determinism is not a thing to spend here.
    /// 2. **Spread the wear over every plate in the zone.** No choice to
    ///    make, and no new information needed. REJECTED because it makes
    ///    the whole feature invisible: ten leg plates would degrade in
    ///    lockstep and fall off on the same round, which is a whole-zone
    ///    armour bar wearing a per-piece costume. The brief's own worked
    ///    example - one pauldron gone, an asymmetry you can read at range
    ///    - cannot happen under it.
    /// 3. **Ask the geometry the hit already carries.** TAKEN. `frac` is
    ///    already computed to pick the zone; the impact point is already
    ///    passed in to place the damage number. Between them they say how
    ///    high, which side, and which face - which is exactly a plate.
    ///
    /// So: the zone's band is cut into as many sub-bands as it has plate
    /// LAYERS, head-down (a leg is tasset, cuisse, poleyn, greave,
    /// sabaton from hip to boot), and left/right - or front/back for the
    /// cuirass - picks between the mirrored halves. It costs no state, no
    /// RNG and no second geometry pass, and it means the plate you lose is
    /// the one that was being shot at.
    ///
    /// `right` is the fighter's OWN right (see `muzzle_origin` for this
    /// game's yaw convention), `front` is true when the impact point is on
    /// the facing half of the body.
    ///
    /// `frac` is CLAMPED into the zone's own band rather than trusted.
    /// The two disagree on purpose in one place: a fighter mid-somersault
    /// is UNIFORM (§4.3), so a boot-height round is called a torso hit,
    /// and the plate it names must then be a torso plate. The zone is
    /// authoritative about which part of the man was hit; this only
    /// decides which of that part's plates caught it.
    pub fn struck(zone: HitZone, frac: f32, right: bool, front: bool) -> ArmorPiece {
        use ArmorPiece::*;
        // Which layer of the zone, counting DOWN from the top of the band.
        // Anything at or above the band's top edge is layer 0.
        let layers = |n: usize| -> usize {
            let (lo, hi) = zone.band();
            let u = ((frac - lo) / (hi - lo)).clamp(0.0, 1.0);
            // 1-u so index 0 is the TOP layer, which is the order the
            // tables below are written in - shoulder to hand, hip to boot
            (((1.0 - u) * n as f32) as usize).min(n - 1)
        };
        match zone {
            // throat plate below, skull above
            HitZone::Head => [Helmet, Gorget][layers(2)],
            // the cuirass is the only plate that is chosen by FACE rather
            // than by side: a man has one chest and one back, and the
            // round that came from behind hit the back one
            HitZone::Torso => match layers(3) {
                0 => {
                    if front {
                        CuirassFront
                    } else {
                        CuirassBack
                    }
                }
                1 => Fauld,
                _ => PelvisPlate,
            },
            HitZone::Arms => {
                let l = [
                    [PauldronL, RerebraceL, VambraceL, GauntletL],
                    [PauldronR, RerebraceR, VambraceR, GauntletR],
                ];
                l[right as usize][layers(4)]
            }
            HitZone::Legs => {
                let l = [
                    [TassetL, CuisseL, PoleynL, GreaveL, SabatonL],
                    [TassetR, CuisseR, PoleynR, GreaveR, SabatonR],
                ];
                l[right as usize][layers(5)]
            }
        }
    }
}

/// How many plates a full harness has. See the note above about 24 vs 26.
pub const ARMOR_PIECES: usize = 24;

/// Brief IX §C: an unarmoured SEGMENT takes this much more. Max HP is
/// unchanged - bare places are simply fragile.
pub const EXPOSED_SEGMENT_MULT: f32 = 1.25;

// ---- ARMOUR DAMAGE STATES (Brief IX §C, "Armour damage states") ---------
//
// Until now a plate was equipped or it was not. The brief's table gives it
// a CONDITION, and every number below is read straight off that table:
//
//   Threshold |    HP | State   | Mechanical
//       100%  | 80/80 | Fresh   | No bonus
//        70%  | 56/80 | Scuffed | +5% damage resistance
//        40%  | 32/80 | Cracked | +10% resistance, piece tilts
//        15%  | 12/80 | Severed | Detaches on next hit
//
// Nothing here is invented except the wear RATE, which the brief does not
// state - see `wear_plate` for what was chosen and why.

/// Brief IX §C: every plate starts at 80 and is scored out of 80. The same
/// pool for a sabaton as for a cuirass front, because the table gives one
/// column, not one per piece - a heavier plate is not a tougher one here.
pub const PLATE_HP: f32 = 80.0;

/// The brief's thresholds, as fractions of `PLATE_HP`. A plate is in a
/// state once it is AT or BELOW the threshold - the table's own HP column
/// (56/80, 32/80, 12/80) is what pins that reading, and
/// `the_four_damage_states_are_the_briefs_table` checks against those
/// numbers rather than against these.
pub const PLATE_SCUFFED_FRAC: f32 = 0.70;
pub const PLATE_CRACKED_FRAC: f32 = 0.40;
pub const PLATE_SEVERED_FRAC: f32 = 0.15;

/// The Mechanical column, verbatim: a battered plate turns a round a
/// little better than a clean one.
///
/// Counter-intuitive on its face, and deliberately kept: it is the thing
/// stopping plate wear from being a death spiral, where the first plate to
/// crack makes the second crack faster. The brief chose a shallow reward
/// for wearing the damage instead, and this is it.
pub const PLATE_SCUFFED_RESIST: f32 = 0.05;
pub const PLATE_CRACKED_RESIST: f32 = 0.10;

/// The four visible conditions of one plate.
///
/// SEVERED is a state a plate sits IN, not the moment it leaves: "detached
/// or hanging by strap ... detaches on next hit". So a severed plate is
/// still equipped, still drawn, and comes off on the round after.
#[derive(Clone, Copy, PartialEq, Eq, Debug, PartialOrd, Ord)]
pub enum ArmorStage {
    Fresh,
    Scuffed,
    Cracked,
    Severed,
}

impl ArmorStage {
    /// Worst-first is the order they are REACHED in, which is what makes
    /// the `PartialOrd` derive above meaningful: a plate's stage only ever
    /// increases.
    pub const ALL: [ArmorStage; 4] = [
        ArmorStage::Fresh,
        ArmorStage::Scuffed,
        ArmorStage::Cracked,
        ArmorStage::Severed,
    ];

    /// The one place the strings live - same rule as `TurretMode::label`.
    pub fn label(self) -> &'static str {
        match self {
            ArmorStage::Fresh => "FRESH",
            ArmorStage::Scuffed => "SCUFFED",
            ArmorStage::Cracked => "CRACKED",
            ArmorStage::Severed => "SEVERED",
        }
    }

    /// Incoming-damage resistance this plate grants on a hit that lands on
    /// IT.
    ///
    /// SEVERED grants nothing, and that is a reading of the table rather
    /// than an oversight. The Mechanical column states each row's total,
    /// not an increment - Fresh spells out "No bonus" rather than leaving
    /// it blank, which is what proves the column is absolute. Severed's
    /// cell says only "Detaches on next hit". A plate hanging off a strap
    /// protecting you as well as a cracked one bolted down would also be
    /// the odd reading physically.
    pub fn resist(self) -> f32 {
        match self {
            ArmorStage::Fresh => 0.0,
            ArmorStage::Scuffed => PLATE_SCUFFED_RESIST,
            ArmorStage::Cracked => PLATE_CRACKED_RESIST,
            ArmorStage::Severed => 0.0,
        }
    }

    /// "piece tilts" - the plate has lost a rivet and hangs crooked. Pure
    /// presentation, published so the client is not re-deriving which
    /// stages tilt on the far side of the sim boundary.
    pub fn tilts(self) -> bool {
        self == ArmorStage::Cracked || self == ArmorStage::Severed
    }
}

/// Per-plate HP for one fighter: 24 pools of `PLATE_HP`.
///
/// A plain array rather than bits packed beside `ArmorLoadout`, because
/// this is a CONTINUOUS quantity - the client wants a wear bar, and the
/// resistance step happens at thresholds the HP crosses. The loadout stays
/// exactly what it was, one bit per plate, and detaching clears that bit:
/// there is one answer to "is this plate on me", and the Forge's switch and
/// a round through the shoulder both write it.
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct ArmorCondition {
    hp: [f32; ARMOR_PIECES],
}

impl Default for ArmorCondition {
    /// Every plate fresh. A fighter who has not been shot yet.
    fn default() -> Self {
        ArmorCondition {
            hp: [PLATE_HP; ARMOR_PIECES],
        }
    }
}

impl ArmorCondition {
    fn idx(p: ArmorPiece) -> usize {
        ArmorPiece::ALL.iter().position(|q| *q == p).unwrap()
    }

    /// This plate's remaining pool, 0..=`PLATE_HP`.
    pub fn hp(&self, p: ArmorPiece) -> f32 {
        self.hp[Self::idx(p)]
    }

    /// 0..1, for a wear bar.
    pub fn frac(&self, p: ArmorPiece) -> f32 {
        self.hp(p) / PLATE_HP
    }

    /// Which of the brief's four states this plate is in.
    pub fn stage(&self, p: ArmorPiece) -> ArmorStage {
        let f = self.frac(p);
        if f > PLATE_SCUFFED_FRAC {
            ArmorStage::Fresh
        } else if f > PLATE_CRACKED_FRAC {
            ArmorStage::Scuffed
        } else if f > PLATE_SEVERED_FRAC {
            ArmorStage::Cracked
        } else {
            ArmorStage::Severed
        }
    }

    /// Take `d` out of this plate's pool. Never below zero.
    pub fn wear(&mut self, p: ArmorPiece, d: f32) {
        let i = Self::idx(p);
        self.hp[i] = (self.hp[i] - d).max(0.0);
    }

    /// §C Forge, "Piece repair ... reverts to fresh visually and
    /// mechanically". The sim side of that, so the economy around it can
    /// be built without a second definition of what "fresh" means.
    ///
    /// Deliberately NOT called on respawn or on detach - see
    /// `plate_condition_survives_a_respawn`.
    pub fn repair(&mut self, p: ArmorPiece) {
        self.hp[Self::idx(p)] = PLATE_HP;
    }
}

/// Which plates are on, as one bit per `ArmorPiece::ALL` index.
///
/// A bitmask rather than 24 bools because it has to survive a save file
/// and a network packet someday, and because "is this harness the same as
/// that one" is then a single comparison.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct ArmorLoadout(pub u32);

impl Default for ArmorLoadout {
    /// Fully plated - 33.4 kg, which is over EVERY class ceiling.
    ///
    /// This is the right default for the type and the wrong one for a
    /// fighter, and the difference is worth stating because getting it
    /// backwards is what the first version of this did. Defaulting the
    /// TYPE to empty would make every unarmoured segment fragile the
    /// moment the field existed; defaulting a FIGHTER to full puts every
    /// class over budget and slows the entire game down by ~0.9 m/s.
    ///
    /// Fighters get `default_harness(class)` instead. See there.
    fn default() -> Self {
        ArmorLoadout((1u32 << ARMOR_PIECES) - 1)
    }
}

/// What a class spawns wearing.
///
/// Brief IX §C's table has TWO columns - "default armour weight" and
/// "weight ceiling" - and they are not the same number: 22/25 for
/// Assault, 16/20 Scout, 28/32 Heavy, 20/24 Support. A fresh fighter
/// wears the default, comfortably under his own ceiling, and the gap is
/// the room the Forge gives you to add plate.
///
/// So a full harness is NOT the neutral state. It is a deliberate choice
/// to be slow, available to every class and free to none - which is what
/// makes stripping pieces a decision instead of a menu.
///
/// These lists are built to land on the brief's default weights, and
/// `every_class_spawns_under_its_own_ceiling` checks both halves: under
/// the ceiling, and near the stated default.
pub fn default_harness(c: Class) -> ArmorLoadout {
    use ArmorPiece::*;
    let pieces: &[ArmorPiece] = match c {
        // 22.0 kg of 25 - the full torso, arms at the shoulder, legs to
        // the shin. No gauntlets, no sabatons: the baseline gives up its
        // extremities first, as everyone does.
        Class::Line => &[
            Helmet, Gorget, CuirassFront, CuirassBack, Fauld, PelvisPlate,
            PauldronL, PauldronR, CuisseL, CuisseR, GreaveL, GreaveR,
        ],
        // 15.7 kg of 20 - torso and shoulders, shins, and nothing else.
        // The lightest harness in the game, on the class that pays for
        // speed everywhere else too.
        Class::Skirmisher => &[
            Helmet, CuirassFront, CuirassBack, Fauld, PauldronL, PauldronR,
            GreaveL, GreaveR,
        ],
        // 28.4 kg of 32 - everything but the gorget, gauntlets, poleyns
        // and sabatons. The anchor wears nearly all of it and still has
        // 3.6 kg of headroom, which is the only class that does.
        Class::Warden => &[
            Helmet, CuirassFront, CuirassBack, Fauld, PelvisPlate,
            PauldronL, PauldronR, RerebraceL, RerebraceR, VambraceL, VambraceR,
            TassetL, TassetR, CuisseL, CuisseR, GreaveL, GreaveR,
        ],
        // 20.5 kg of 24.
        Class::Marksman => &[
            Helmet, Gorget, CuirassFront, CuirassBack, Fauld,
            PauldronL, PauldronR, CuisseL, CuisseR, GreaveL, GreaveR,
        ],
    };
    let mut l = ArmorLoadout::EMPTY;
    for p in pieces {
        l.set(*p, true);
    }
    l
}

impl ArmorLoadout {
    pub const EMPTY: ArmorLoadout = ArmorLoadout(0);

    fn bit(p: ArmorPiece) -> u32 {
        1u32 << ArmorPiece::ALL.iter().position(|q| *q == p).unwrap()
    }

    pub fn has(self, p: ArmorPiece) -> bool {
        self.0 & Self::bit(p) != 0
    }

    pub fn set(&mut self, p: ArmorPiece, on: bool) {
        if on {
            self.0 |= Self::bit(p);
        } else {
            self.0 &= !Self::bit(p);
        }
    }

    pub fn toggle(&mut self, p: ArmorPiece) {
        let on = self.has(p);
        self.set(p, !on);
    }

    /// Total plate weight carried.
    pub fn weight_kg(self) -> f32 {
        ArmorPiece::ALL
            .into_iter()
            .filter(|p| self.has(*p))
            .map(|p| p.weight_kg())
            .sum()
    }

    /// Incoming-damage multiplier for one zone: 1.0 fully plated, up to
    /// `EXPOSED_SEGMENT_MULT` fully bare.
    ///
    /// Proportional rather than all-or-nothing, because a zone holds
    /// between two and ten plates and a rule that only fired when EVERY
    /// plate on a leg was gone would almost never fire. Losing one greave
    /// should cost something on the very next hit that lands low.
    pub fn zone_mult(self, zone: HitZone) -> f32 {
        let (total, on) = ArmorPiece::ALL
            .into_iter()
            .filter(|p| p.zone() == zone)
            .fold((0u32, 0u32), |(t, o), p| (t + 1, o + self.has(p) as u32));
        if total == 0 {
            return 1.0;
        }
        let bare = 1.0 - on as f32 / total as f32;
        1.0 + bare * (EXPOSED_SEGMENT_MULT - 1.0)
    }
}

/// §C tier 2: the five standard harnesses, so nobody has to click
/// twenty-four switches to get dressed.
///
/// The grid is the fine control and it should stay - "remove both
/// gauntlets" is the brief's own worked example, and that decision needs
/// a per-plate toggle. But a player who does not care about plate should
/// be able to say "heavy" and leave, and one who has been experimenting
/// should be able to get back to sane in one click. A customiser with no
/// presets is a customiser most people bounce off.
///
/// The ladder is monotone by WEIGHT: every step up is strictly more
/// plate than the step below, which is what makes it a ladder rather
/// than five opinions. `the_preset_ladder_only_ever_adds` pins that.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArmorPreset {
    /// Helmet and nothing else. The fastest a class can be.
    Stripped,
    /// Head and chest. Everything that covers a lung, nothing that does
    /// not.
    Light,
    /// Whatever this CLASS spawns in - the only preset that varies by
    /// who you are, because "standard" is a statement about a soldier
    /// and not about a weight.
    Standard,
    /// Everything but the extremities - no gauntlets, no sabatons.
    Heavy,
    /// All twenty-four. Over every ceiling; a deliberate choice to be
    /// slow.
    Full,
}

impl ArmorPreset {
    pub const ALL: [ArmorPreset; 5] = [
        ArmorPreset::Stripped,
        ArmorPreset::Light,
        ArmorPreset::Standard,
        ArmorPreset::Heavy,
        ArmorPreset::Full,
    ];

    pub fn name(self) -> &'static str {
        match self {
            ArmorPreset::Stripped => "STRIPPED",
            ArmorPreset::Light => "LIGHT",
            ArmorPreset::Standard => "STANDARD",
            ArmorPreset::Heavy => "HEAVY",
            ArmorPreset::Full => "FULL",
        }
    }
}

/// The harness a preset means, for a given class.
pub fn preset_harness(p: ArmorPreset, c: Class) -> ArmorLoadout {
    use ArmorPiece::*;
    let mut l = ArmorLoadout::EMPTY;
    match p {
        ArmorPreset::Stripped => {
            l.set(Helmet, true);
        }
        ArmorPreset::Light => {
            for q in [Helmet, CuirassFront, CuirassBack, PauldronL, PauldronR] {
                l.set(q, true);
            }
        }
        ArmorPreset::Standard => l = default_harness(c),
        ArmorPreset::Heavy => {
            l = ArmorLoadout::default();
            for q in [GauntletL, GauntletR, SabatonL, SabatonR] {
                l.set(q, false);
            }
        }
        ArmorPreset::Full => l = ArmorLoadout::default(),
    }
    l
}

/// Which preset a harness currently matches, if any.
///
/// So the picker can light the row a player is actually on, and go dark
/// the moment they touch a single plate. A preset row that stayed lit
/// while the harness underneath it had changed would be lying about
/// what is equipped.
pub fn preset_of(l: ArmorLoadout, c: Class) -> Option<ArmorPreset> {
    ArmorPreset::ALL
        .into_iter()
        .find(|p| preset_harness(*p, c) == l)
}

/// What a class actually changes. Four multipliers, each hooked to a
/// system that already existed - no new subsystem, so no new place for
/// the numbers to drift out of sync with what the player feels.
pub struct ClassSpec {
    pub name: &'static str,
    /// Scales spawn and respawn health off `MAX_HEALTH`.
    pub health_mult: f32,
    /// Multiplies the movement ladder, ALONGSIDE the armour set's own
    /// `move_mult` - a Warden in a mech is slow twice over, correctly.
    pub move_mult: f32,
    /// Scales the fired cone. BELOW 1.0 is tighter (better).
    pub spread_mult: f32,
    /// Scales `SWITCH_S`. BELOW 1.0 is a faster weapon swap.
    pub switch_mult: f32,
    /// §owner RETREAT: scales `ROUT_TOLERANCE`. ABOVE 1.0 holds longer.
    ///
    /// The fifth trade, and the one that makes a class read as a
    /// TEMPERAMENT rather than a stat block. It replaces `jk_wall`'s
    /// rolled per-man tolerance, which this build cannot copy - a roll
    /// would desync every replay test - and it is the better answer
    /// regardless: a Warden that stands when a Skirmisher runs is a
    /// difference the player can name.
    pub nerve_mult: f32,
    /// §C tier 2: how much plate this class carries free. Past it,
    /// `armor_weight_movement_penalty` bites at -0.15 m/s per kg.
    ///
    /// The brief names four classes of its own (Assault/Scout/Heavy/
    /// Support) with ceilings of 25/20/32/24 kg. This game's four are
    /// LINE/SKIRMISHER/WARDEN/MARKSMAN, which line up one-to-one by
    /// temperament, so the brief's ceilings are carried over onto them
    /// rather than a fifth set of classes being invented to hold them.
    ///
    /// A FULL harness is 33.4 kg, over EVERY ceiling including the
    /// Warden's 32. Nobody wears all of it free, which is the design
    /// working: full plate is a deliberate choice to be slow rather than
    /// the obvious pick, and what you leave off is a decision instead of
    /// a menu. What a class spawns in is `default_harness`, which sits
    /// under the ceiling with room to add.
    pub weight_budget_kg: f32,
    /// One line, shown on the class picker.
    pub blurb: &'static str,
}

impl Class {
    pub const ALL: [Class; 4] =
        [Class::Line, Class::Skirmisher, Class::Warden, Class::Marksman];
}

/// The class table. Read it as a row of trades: nobody is strictly
/// better than `Line`, and each of the other three pays for its edge in
/// a currency the player can name.
pub fn class_spec(c: Class) -> ClassSpec {
    match c {
        Class::Line => ClassSpec {
            name: "LINE",
            health_mult: 1.0,
            move_mult: 1.0,
            spread_mult: 1.0,
            switch_mult: 1.0,
            nerve_mult: 1.0,
            weight_budget_kg: 25.0,
            blurb: "the baseline - no bonus, no penalty, never wrong",
        },
        Class::Skirmisher => ClassSpec {
            name: "SKIRMISHER",
            health_mult: 0.85,
            move_mult: 1.12,
            spread_mult: 1.15,
            switch_mult: 0.72,
            nerve_mult: 0.78,
            weight_budget_kg: 20.0,
            blurb: "fastest on foot and to the trigger - thin, and sprays",
        },
        Class::Warden => ClassSpec {
            name: "WARDEN",
            health_mult: 1.28,
            move_mult: 0.90,
            spread_mult: 0.92,
            switch_mult: 1.28,
            nerve_mult: 1.35,
            weight_budget_kg: 32.0,
            blurb: "soaks the most and shoots steady - slow to arrive",
        },
        Class::Marksman => ClassSpec {
            name: "MARKSMAN",
            health_mult: 0.92,
            move_mult: 0.96,
            spread_mult: 0.70,
            switch_mult: 1.15,
            nerve_mult: 0.92,
            weight_budget_kg: 24.0,
            blurb: "the tightest shot in the game - wants the FIRST one",
        },
    }
}

pub type Loadout = [GunKind; 3];

pub const DEFAULT_LOADOUT: Loadout = [GunKind::M4, GunKind::Glock, GunKind::Awm];

#[derive(Clone, Copy, Debug)]
pub struct MatchConfig {
    pub seed: u64,
    pub per_team: usize, // 5..=8 (owner's cap: 8v8)
    pub mode: Mode,
    pub map: MapKind,
    pub difficulty: Difficulty,
    pub loadout: Loadout,
    /// §owner: kills needed to win a TDM. Selectable per match.
    pub tdm_target: u32,
    /// §owner: the player's chosen class. Bots pick their own.
    pub class: Class,
    /// §6 (Brief IV): the player's melee slot carries the axe.
    pub melee_axe: bool,
    /// §8 (Brief IV): index into GRENADE_PRESETS for the player's
    /// 6-point throwable budget.
    pub grenade_preset: usize,
    /// §C tier 2: the plate the PLAYER assembled in the Forge. `None`
    /// takes the class default, which is what every bot gets and what a
    /// harness-unaware caller (the capture harness, older tests) should
    /// keep getting rather than being silently stripped naked.
    pub armor_pieces: Option<ArmorLoadout>,
}

impl Default for MatchConfig {
    fn default() -> Self {
        MatchConfig {
            seed: 0x7EA9,
            per_team: 5,
            mode: Mode::Tdm,
            map: MapKind::Arena,
            difficulty: Difficulty::Normal,
            loadout: DEFAULT_LOADOUT,
            tdm_target: TDM_TARGET,
            class: Class::Line,
            melee_axe: false,
            grenade_preset: 0,
            armor_pieces: None,
        }
    }
}

/// A capturable forward-spawn checkpoint. Stand in the ring uncontested
/// to charge it toward your team; once owned, your dead respawn there.
#[derive(Clone, Debug)]
pub struct Checkpoint {
    pub pos: [f32; 3],
    pub owner: Option<Team>,
    /// −CAP..+CAP: positive charges Blue, negative Red.
    pub charge: f32,
}

#[derive(Clone, Debug)]
pub struct Fighter {
    pub name: &'static str,
    pub team: Team,
    /// The ACTIVE weapon (mirror of `inventory[active]` for fast access).
    pub gun: GunKind,
    /// [primary, secondary, special] — the shield is its own stance below.
    pub inventory: Loadout,
    /// Per-slot (magazine, reserve) so switching keeps each gun's state.
    pub slot_ammo: [(u32, u32); 3],
    pub active: usize,
    /// Shield raised: front-arc protection, no firing, slow walk.
    pub shield_up: bool,
    /// −1..+1 sideways lean (peek): shifts the muzzle, trims recoil.
    pub lean: f32,
    pub crouch: bool,
    /// §3.6: holding the walk key this tick. AUTHORITATIVE state, not
    /// raw intent — `try_fire` and the noise pass both read it, and a
    /// speed-derived guess would be wrong for one tick every time the
    /// key is tapped, which is exactly when a stealth player cares.
    pub walking: bool,
    /// §4.5: was the shot that is currently in flight fired while aimed?
    /// Latched in `try_fire`, read when the kill resolves — the kill site
    /// is several calls downstream of the trigger and has no other way
    /// to know how the shot was taken.
    pub fired_ads: bool,
    /// §4.5: did the last trigger pull's ray pass THROUGH a smoke bloom?
    /// Same latch pattern as `fired_ads`, same reason.
    pub fired_smoke: bool,
    /// §4.5: did the last landed shot punch THROUGH cover first?
    pub fired_wallbang: bool,
    /// Melee v1: staggered after being parried - no firing, no swinging,
    /// half pace, until it ticks out.
    pub stagger_t: f32,
    /// Melee v1: successful parries, for the scoreboard-adjacent toast.
    pub parries: u32,
    /// Hull climbing: `Some` while gripping a mech (DESIGN.md). Both
    /// hands are on the hull - no ranged weapon until release.
    /// §owner SQUAD AI: the enemy this bot is currently engaging, or -1.
    /// Squadmates read it to converge their fire instead of each
    /// shooting whoever happens to be nearest to them personally.
    pub engaging: i32,
    /// §owner SQUAD AI: anchor or flanker within a shared engagement.
    /// Derived every tick from index order among the squadmates on the
    /// same target - never stored across ticks, never rolled.
    pub squad_role: SquadRole,
    /// §owner SQUAD AI: which half of a bounding pair this bot is in.
    /// Derived, like the role, from the clock and index order.
    pub bound_phase: BoundPhase,
    /// §owner PLASMA BOW: the precision shot's own cooldown, and how
    /// far the current charge has run. Separate from the rapid mount's
    /// gatling_cd because the two modes cycle independently - firing
    /// rapid must not eat the precision timer, and vice versa.
    pub plasma_cd: f32,
    pub plasma_charge_t: f32,
    /// §owner AGILE SUPPORT MECH: who the repair beam is currently
    /// mending, or -1. Published so the client can DRAW the beam without
    /// re-deriving the choice - two independent answers to "who is being
    /// healed" is exactly the split-brain the bow draw already had to be
    /// rescued from.
    pub repair_target: i32,
    /// §owner SUPPRESSION: seconds of "rounds are cracking past me" left,
    /// capped at `SUPPRESS_MAX_S`.
    ///
    /// Written for EVERY fighter, player included - the geometry does not
    /// ask who you are. What reads it differs: a bot's aim degrades and it
    /// stops pushing, while the player's copy drives a viewmodel shake and
    /// nothing else. A human's aim is his own; taking it away is not
    /// tension, it is the game playing itself.
    pub suppress_t: f32,
    /// §owner SUPPRESSION: where the last close round came FROM.
    ///
    /// Suppression without a bearing is half a message. "You are being
    /// shot at" tells a player to move; "you are being shot at from
    /// THERE" tells them where to move TO, and only the second is
    /// actionable. The shooter's MUZZLE origin rather than his feet, so a
    /// hull mount high on a chassis reads from where its rounds actually
    /// leave.
    ///
    /// Latest round wins: the freshest line is the one still live.
    pub suppress_from: [f32; 3],
    /// §owner RETREAT: accumulated nerve loss, 0..`FEAR_MAX`.
    ///
    /// The first genuinely REMEMBERED bot state in this sim - every other
    /// squad behaviour is re-derived each tick from live positions. It has
    /// to be, because breaking is a response to what has been happening to
    /// you, and there is no such thing as an instantaneous reading of
    /// that. Never written for the player: a human's nerve is the human's
    /// problem.
    pub fear: f32,
    /// §owner RETREAT: broken and pulling out. Hysteretic - see
    /// `RALLY_FEAR`.
    pub routing: bool,
    /// §C tier 2: which plates this fighter is wearing.
    ///
    /// Defaults to the FULL harness, which is what keeps this change from
    /// silently re-balancing everything that came before it: every
    /// existing fighter was uniformly armoured, so full plate is the
    /// no-op, and only a player who takes something OFF sees a
    /// difference.
    pub armor_pieces: ArmorLoadout,
    /// §C: how battered each of those plates is - the four damage states.
    ///
    /// AUTHORITATIVE, not display: the struck plate's stage multiplies
    /// incoming damage (`ArmorStage::resist`), and the round after it
    /// reaches SEVERED clears its bit out of `armor_pieces`. A client
    /// reads it through `armor_stage_of`; nothing outside the sim writes
    /// it.
    ///
    /// Deliberately NOT cleared on respawn, which is the opposite of the
    /// house rule and needs the reason stated: §C repairs plate in the
    /// FORGE, at 50 points a piece, between matches. Dying is not a
    /// repair. `plate_condition_survives_a_respawn` pins that so it reads
    /// as a decision rather than as the recurring bug it resembles.
    pub armor_cond: ArmorCondition,
    /// §owner: which of the four classes this fighter is fighting as.
    /// Set at spawn and kept for the match - `class_spec` turns it into
    /// the four multipliers that actually bite.
    pub class: Class,
    pub climbing: Option<ClimbState>,
    /// Grip stamina carried BETWEEN climbs (rest-only recovery needs a
    /// meter that persists when `climbing` is `None`).
    pub grip_pool: f32,
    pub switch_t: f32,
    pub pos: [f32; 3], // feet
    pub vel: [f32; 2], // xz
    pub vy: f32,
    pub grounded: bool,
    pub yaw: f32,
    /// Last tick's yaw — the aim's angular rate for the §4 stability
    /// model is (yaw − prev_yaw)/DT. Updated at the end of every step.
    pub prev_yaw: f32,
    /// >0 → mid-somersault: fast, low, can't shoot. Set by the dodge key
    /// or automatically by a hard landing (parkour breakfall).
    pub roll_t: f32,
    pub roll_cd: f32,
    pub roll_dir: [f32; 2],
    /// Task 3 rule 3: burst multiplier snapshotted at the dodge trigger -
    /// 1.0 + ROLL_COUNTER_BONUS when the dodge cut against real prior
    /// movement, 1.0 otherwise (and always 1.0 for the mech and the
    /// breakfall, which is momentum conversion, not a counter-move).
    pub roll_boost: f32,
    pub health: f32,
    /// §6: the Robot Suit's POWER CORE charge (0 for every other set) —
    /// thrusters and repulsors spend it, explosions drain it, the ground
    /// recharges it. The HUD's second bar.
    pub armor: f32,
    /// §6: the equipped armor set — found in-world, lost on death.
    pub armor_set: ArmorSet,
    /// §11: the mech's hull pool (450, NEVER regenerates). >0 means the
    /// chassis is intact; at zero the pilot ejects on foot at 25 HP.
    pub hull: f32,
    /// Pyro flame-projector fuel seconds.
    pub fuel: f32,
    /// §6.2 (Brief VII v2): mounting AND dismounting the mech are
    /// COMMITTED, not instant - counts down from MECH_ENTER_S or
    /// MECH_EXIT_S; while >0 the chassis is sealing up or powering down
    /// and can't fight (blocked in try_fire).
    pub mech_transition_t: f32,
    /// Which direction `mech_transition_t` is running. On an exit, the
    /// chassis teardown is DEFERRED to the end of the window - that
    /// deferral is what makes leaving committal rather than a one-tick
    /// state flip.
    pub mech_exiting: bool,
    /// §6.3: HP-threshold armor-drop events already fired this life -
    /// bitmask (bit0=70%, bit1=40%, bit2=15%) so each stage fires once.
    pub mech_plates_dropped: u8,
    /// Folk Shieldwall Brace held: planted, shielded, slow.
    pub brace: bool,
    /// §A: Mech Brace held - wide stance, near-stationary, damped recoil.
    /// Deliberately a separate field from `brace`: see the constants.
    pub mech_brace: bool,
    /// §owner MECH SHIELD: the barrier's remaining pool. Falls as it
    /// eats hits, comes back after a lull. Zero = collapsed.
    pub mech_shield_hp: f32,
    /// Time since the barrier last took a hit, for the recharge delay.
    pub mech_shield_quiet_t: f32,
    /// §C: which hull mount the trigger currently drives. Both mounts
    /// are always present on a live chassis - this is a targeting mode,
    /// not an inventory slot (see `MechWeapon`).
    pub mech_weapon: MechWeapon,
    /// §12 (owner): the hull TURRET's fire mode. Read by the HUD via
    /// `TdmSim::turret_mode_of` - one source of truth for the readout
    /// and for the trigger.
    ///
    /// Cleared to `Auto` on respawn, alongside `mech_weapon`, which the
    /// respawn block right beside it already resets to the turret: a
    /// dead chassis takes its selector switches with it, and `Auto` is
    /// the behaviour every caller in the file (bot brain included)
    /// expects when nobody has said otherwise.
    pub turret_mode: TurretMode,
    /// §12: rounds fired so far in the CURRENT trigger pull. Drives the
    /// growing kick and the 3-round burst cap; reset on the press edge.
    pub turret_burst_i: u32,
    /// §12: the settle after a burst (or after a single). The mount
    /// takes nothing at all while this is running.
    pub turret_recover_t: f32,
    /// §C: the hull gatling's own 0..100 heat pool and forced-vent lock.
    /// Kept SEPARATE from the minigun's `heat`/`vent_t` for the same
    /// reason `stride_heat` is: those two drive the MINIGUN's vent state
    /// machine (barrel glow, vent audio, fire lockout) gated purely on
    /// `gun == Minigun` - and a mech pilot may well be carrying the
    /// minigun, in which case a hot hull mount would hand him an
    /// instant, unearned lockout on the gun in his hands.
    pub gatling_heat: f32,
    pub gatling_vent_t: f32,
    /// §C: the gatling's own cycle clock. Its own field, not `fire_cd`,
    /// for the reason stated one field down and violated by the first
    /// cut: `fire_cd` is the PILOT'S carried-gun clock, so a gatling
    /// that set it left the dismounting pilot throttled by a gun bolted
    /// to a chassis he just climbed out of.
    pub gatling_cd: f32,
    /// §C: the gatling's TRIGGER-HELD hold timer — the same shape and
    /// the same 70 ms as the minigun's `spin_cmd`, and set at the top of
    /// `try_fire_gatling` BEFORE every early return for the same reason:
    /// it must mean "the trigger is down", not "a round left the mount".
    ///
    /// The first cut gated the heat decay on `fire_cd <= 0.0` instead,
    /// reasoning that the cycle clock running IS the trigger being down.
    /// It is not. `fire_cd <= 0.0` is true for exactly ONE tick per fire
    /// cycle, so the mount still shed `GATLING_HEAT_DECAY * DT` of heat
    /// every cycle — 88.9% suppression, not the minigun's 100%. That
    /// residual is LINEAR IN DT, which made the time to a forced vent
    /// tick-rate dependent: 11.18 s at 60 Hz, 9.08 s at 120 Hz, 8.22 s
    /// at 240 Hz. A hold timer suppresses the decay outright, so what is
    /// left moving with the tick rate is only the quantisation of the
    /// fire period itself.
    pub gatling_trigger_t: f32,
    /// §C: the autocannon's slow cycle clock. Its own field, not
    /// `fire_cd`, so the two mounts cannot silently share a cooldown.
    pub autocannon_cd: f32,
    /// §5 knife swing clock — 0 idle; counts up through wind → active →
    /// recovery. `knife_committed` = the held lunge variant.
    pub knife_phase: f32,
    pub knife_committed: bool,
    /// §owner MELEE v2: the line THIS swing travels. Latched when the
    /// wind starts and held for the whole strike, so wiggling a strafe
    /// key mid-swing cannot re-aim a blade already in motion.
    pub knife_dir: MeleeDir,
    pub knife_struck: bool,
    /// §6 (Brief IV): the melee slot carries the AXE instead of the
    /// knife — slower, harder, and the swing sweeps the whole arc.
    pub melee_axe: bool,
    /// §7 (Brief IV): minigun barrel spin (0..=MINIGUN_SPINUP_S — firing
    /// starts at the top), current heat (0..=100), and the vent lock.
    pub spin_t: f32,
    pub heat: f32,
    pub vent_t: f32,
    /// §7.4 (BRIEF VIII): power-stride WIND-UP progress, 0..
    /// POWER_STRIDE_WINDUP_S. Cancels if sprint is released or heat
    /// caps out before it completes - the burst itself hasn't fired
    /// yet, so nothing is owed.
    pub stride_wind_t: f32,
    /// §7.4: power-stride ACTIVE window remaining. >0 means the burst
    /// is live - speed override, missile pod locked, turn capped. Once
    /// triggered it's committed (an interrupted "sustained push" isn't
    /// one), counting down on its own regardless of continued input.
    pub stride_t: f32,
    /// §7.4: power-stride's own 0..100 heat-style budget. The brief
    /// says striding "costs heat (§7.8)" - deliberately kept SEPARATE
    /// from the minigun's `heat`/`vent_t` rather than sharing the
    /// field: those drive the minigun's forced-vent state machine
    /// (barrel glow, vent audio, fire lockout) purely on `heat > 0`
    /// gated by `gun == Minigun`, so a mech that strides then SWITCHES
    /// to the minigun would walk into an instant, unearned vent lockout
    /// if the two pools were one. Same 0-100 shape and cooldown rhythm,
    /// zero cross-wiring.
    pub stride_heat: f32,
    /// §21: which stage of a heavy-chassis JUMP this fighter is in, and
    /// the clock for it (the compression countdown, then the landing
    /// recovery countdown - `Air` carries no clock because the ground
    /// decides when flight ends, not a timer).
    ///
    /// AUTHORITATIVE, not display: the phase gates a second jump, gates
    /// crouch, and - through `chassis_kneeling` - moves `height()`, which
    /// is the hitbox and the hit bands. It is reset on respawn beside
    /// `stride_*` and is in the bot-mech replay digest for the same
    /// reason `mech_brace` is.
    pub mech_jump_phase: MechJumpPhase,
    pub mech_jump_t: f32,
    /// Trigger-held HOLD TIMER (seconds): refreshed by `try_fire`, drained
    /// by the timer loop. A short 0.07 s hold (not a per-tick bool) so a
    /// far bot thinking at the 15 Hz LOD still keeps its barrels climbing
    /// between thinks; for the player it is refreshed every held tick.
    pub spin_cmd: f32,
    /// §7: the primary the minigun pickup displaced — restored on death.
    pub prev_primary: GunKind,
    /// §2 (Brief VI): the punch channels — (pitch°, yaw°) angle and its
    /// velocity. Bullets fly at punch × RECOIL_SCALE; the camera shows
    /// 45% of that; the crosshair never moves.
    pub punch: [f32; 2],
    pub punch_vel: [f32; 2],
    /// Deterministic spray-table index (decays while not firing).
    pub spray_i: f32,
    pub last_shot_at: f32,
    /// §5.3 (Brief VI): the mech's missile pod — tubes left, relaunch
    /// cooldown, the acquiring lock (target index, seconds held), and
    /// the VICTIM-side warning timer (set from lock START).
    pub pod_ammo: u8,
    /// §owner: the hull gatling's belt (see MECH_ROUNDS).
    pub mech_rounds: u32,
    pub pod_cd: f32,
    pub pod_lock_t: f32,
    pub pod_lock_id: i32,
    pub pod_aim_held: bool,
    pub lock_warn_t: f32,
    /// §3: spear windup clock (counts down to the release), the aim
    /// tracked through the wind, and the charge the trigger locked in.
    pub spear_wind_t: f32,
    /// §owner JAVELIN: how long the trigger has been held winding this
    /// throw. Zero when not charging.
    pub spear_charge_t: f32,
    /// The velocity multiplier the pending throw was charged to. Set at
    /// release, consumed by `try_fire`, reset after - bots never touch
    /// it and so keep throwing at exactly the old fixed power.
    pub spear_power: f32,
    pub spear_aim: [f32; 3],
    pub spear_v0: f32,
    /// §4.1 (Brief VII v2): the bow's draw clock - counts UP while aim
    /// is held (unlike the spear's committal countdown), 0.15s to
    /// 0.7s mapping 35%-100% power, held past 10s force-letdown.
    /// `bow_aim` tracks the aim direction through the hold, same as the
    /// spear's `spear_aim`.
    pub bow_draw_t: f32,
    pub bow_aim: [f32; 3],
    /// §4 aerial flip: remaining rotation time, direction of travel,
    /// the flip kind (0 front / 1 back / 2 left / 3 right), whether this
    /// airborne period's one flip is spent, and the landing recovery.
    pub flip_t: f32,
    pub flip_dir: [f32; 2],
    pub flip_kind: u8,
    pub flip_used: bool,
    pub flip_recover_t: f32,
    /// §6: >0 → the raised shield is DIPPED for a throw (blocks nothing).
    pub shield_dip_t: f32,
    /// Ability cooldown (repulsor).
    pub ability_cd: f32,
    /// Sim time of last ability use (gates power recharge).
    pub last_ability_at: f32,
    /// Sim time of last damage taken (gates Recon regen).
    pub last_dmg_at: f32,
    pub ammo: u32,
    pub reserve: u32,
    pub reload_t: f32,
    /// §3.4 (BRIEF VIII): sprint-out - the weapon is LOWERED at sprint
    /// and takes a per-class beat to ready after leaving it (SMG 0.15s /
    /// rifle 0.20s / heavy 0.30s). Counts down once planar speed drops
    /// below the sprint-carry threshold; firing is blocked while > 0.
    /// The COD/CSGO skill lever the brief names: sprinting around a
    /// corner cannot ALSO mean instantly shooting whoever is there.
    pub sprint_gate_t: f32,
    /// §5.4 (BRIEF VIII): continuous time spent at/above the
    /// running-throw speed threshold - resets the instant speed drops
    /// below it. Feeds the spear's running-throw bonus: a throw
    /// released with real approach momentum behind it launches faster,
    /// exactly like a real thrower's run-up pays off over a standing
    /// throw. A tap of forward input can't fake this - it has to be
    /// sustained.
    pub running_momentum_t: f32,
    pub fire_cd: f32,
    pub bloom: f32,
    pub respawn_t: f32,
    pub protect_t: f32,
    pub kills: u32,
    pub deaths: u32,
    pub assists: u32,
    /// §4.8: career damage dealt to ENEMIES this match. Team damage and
    /// self damage deliberately do not count - crediting a player's DMG
    /// column for shooting their own team would reward the exact thing
    /// the team-kill scoring gate exists to punish. Never reset on
    /// respawn (a career stat, like kills/deaths).
    pub dmg_dealt: f32,
    pub hits_dealt: u32,
    /// §4.5 (BRIEF VIII): assist tracking. The most recent OTHER
    /// fighter to damage this one, with the sim time it happened - not
    /// a full history, just the single latest distinct attacker, which
    /// is what "who else hit them" needs. Read (and cleared) at death;
    /// anything older than ASSIST_WINDOW_S doesn't count.
    pub last_hit_by: Option<(usize, f32)>,
    /// §3: >0 → a walk-over pickup was refused because the reserve is at
    /// cap; the HUD surfaces "AMMO FULL" (the missing feedback that hid
    /// the pickup bug).
    pub ammo_full_t: f32,
    // §5 throwables
    /// Remaining grenades per ThrowKind::ALL slot.
    pub grenades: [u8; 4],
    /// Selected throwable slot (G cycles).
    pub throw_sel: u8,
    /// §26 (owner): seconds the throw has been WOUND UP for — NOT a cook
    /// clock any more, despite the name.
    ///
    /// The name is a fossil: it used to burn the frag's fuse in your
    /// hand, and holding past 2.4 s killed you. It now buys nothing but
    /// distance (`throw_power`), and the fuse is lit at release. The
    /// field kept its name only because the client reads it in six
    /// places; `throw_wind_s()` is the honest accessor and new code
    /// should use that.
    pub cook_t: f32,
    /// §5.3 flashbang blind seconds remaining (bots aim ×4 worse).
    pub blind_t: f32,
    /// Burning marker (client flame FX), set by fire pools.
    pub burn_t: f32,
    // bot brain
    pub waypoint: [f32; 2],
    pub strafe_phase: f32,
    pub los_time: f32,
    pub think_offset: u32,
}

impl Fighter {
    pub fn alive(&self) -> bool {
        self.respawn_t <= 0.0 && self.health > 0.0
    }

    /// §26 (owner): seconds this fighter has been winding up a throw, 0
    /// if not winding. THE name for what `cook_t` actually holds — see
    /// that field's doc for why the storage still carries the old one.
    ///
    /// A HUD that wants "how charged is this throw" wants
    /// `throw_power(f.throw_wind_s())`; a HUD that wants "how long until
    /// this frag goes off" is asking about a grenade that has already
    /// left the hand, and there is no such number while it is held.
    pub fn throw_wind_s(&self) -> f32 {
        self.cook_t
    }
    /// Is this fighter currently piloting a live chassis?
    pub fn in_mech(&self) -> bool {
        self.armor_set.is_mech() && self.hull > 0.0
    }

    /// §owner AGILE SUPPORT MECH: is this the LIGHT chassis?
    ///
    /// Named rather than compared inline, because "is a mech" and "is
    /// the heavy one" are two different questions and the code that
    /// wants the second is code that would silently do the wrong thing
    /// for the first.
    pub fn in_scout_mech(&self) -> bool {
        self.armor_set == ArmorSet::ScoutMech && self.hull > 0.0
    }

    /// The hull this fighter's chassis spawns with.
    pub fn mech_hull_max(&self) -> f32 {
        match self.armor_set {
            ArmorSet::ScoutMech => SCOUT_HULL,
            _ => MECH_HULL,
        }
    }
    /// §21: is this fighter piloting the HEAVY chassis specifically?
    ///
    /// The bare `armor_set == RobotSuit && hull > 0.0` test is written out
    /// inline in a dozen places in this file; every §21 rule asks it, so
    /// it gets the name `in_scout_mech` already has for the other side.
    /// "Is a mech" and "is the heavy one" are different questions, and
    /// jumping, kneeling and the 1.7x hitbox belong only to the second.
    pub fn in_heavy_mech(&self) -> bool {
        self.armor_set == ArmorSet::RobotSuit && self.hull > 0.0
    }

    /// §21: is the heavy chassis ON ITS KNEES right now?
    ///
    /// Three states, ONE pose: deliberately crouched, coiled for a jump,
    /// or absorbing a landing. They are the same thing physically - hull
    /// low, stance wide, machine planted - so they are one predicate, and
    /// `height()` and `stance_speed_mult` both read it. Splitting them
    /// would mean the renderer could squat for a compression the hitbox
    /// knew nothing about, which is exactly the defect the old crouch ban
    /// was papering over.
    pub fn chassis_kneeling(&self) -> bool {
        self.in_heavy_mech()
            && (self.crouch
                || self.mech_jump_phase == MechJumpPhase::Compress
                || self.mech_jump_phase == MechJumpPhase::Recover)
    }

    /// §21: how far through the pre-jump COMPRESSION this chassis is,
    /// 0 at the first tick of the coil and 1 at the launch; 0 whenever it
    /// is not compressing.
    ///
    /// **The named accessor the client renders the wind-up from** - the
    /// knees bending, the hips dropping - so the visual telegraph and the
    /// sim's own launch timing can never disagree about how loaded the
    /// machine is. Also reachable as `TdmSim::mech_jump_compression_of`.
    pub fn mech_jump_compression(&self) -> f32 {
        if self.mech_jump_phase == MechJumpPhase::Compress {
            (1.0 - self.mech_jump_t / MECH_JUMP_COMPRESS_S).clamp(0.0, 1.0)
        } else {
            0.0
        }
    }

    /// §6/§21: apply crouch INTENT.
    ///
    /// The heavy chassis CAN kneel now. It could not before, and the ban
    /// was correct at the time: `height()` returned the full 3.03 m
    /// unconditionally, so a crouching mech kept a standing hitbox while
    /// the renderer played the squat and the x2.0 visor band floated in
    /// empty air above the model. `height()` now follows the pose (see
    /// `chassis_kneeling`), which is the fix for the CAUSE rather than
    /// for the symptom, so the ban can go.
    ///
    /// What survives the ban, as rules rather than as a refusal:
    /// - MID-AIR is not a stance. A walker cannot fold its legs with
    ///   nothing under them, and letting it would drop the hitbox of a
    ///   target that is already hard to lead.
    /// - a DESTROYED chassis is not a chassis: `in_heavy_mech()` is false
    ///   at hull 0, so the ejected pilot falls through to the soldier
    ///   branch and crouches like the man he now is.
    /// - the LIGHT chassis still refuses outright. Its `height()` has no
    ///   crouch term at all, so letting it set the flag would recreate the
    ///   original bug on the other machine. Deliberately deferred, not
    ///   forgotten.
    ///
    /// This lives on `Fighter` so the PLAYER and BOT paths cannot drift -
    /// the original guard was added to the player path only, leaving every
    /// bot-piloted mech still able to crouch. Both callers still go
    /// through here and so get every rule above for free.
    pub fn set_crouch(&mut self, want: bool) {
        if self.in_heavy_mech() {
            self.crouch = want && self.grounded;
        } else {
            self.crouch = want && !self.in_mech();
        }
    }
    /// How tall a ledge this body can step onto.
    ///
    /// §A (VIII-B addendum) requires the mech's traversal envelope to
    /// scale WITH the chassis, and this was missed when MECH_SCALE moved
    /// to 1.7: `STEP_UP` was a flat global, so a 3-metre walker stepped
    /// over exactly the same knee-high ledge a soldier does - and, worse,
    /// was *blocked* by the same one. A machine that size being stopped
    /// by a crate a man can stride over is the kind of detail that reads
    /// instantly as fake.
    ///
    /// An accessor rather than a constant for the same reason `height()`
    /// and `radius()` are: every consumer then scales for free, and a
    /// future chassis size cannot leave one call site behind.
    pub fn step_up(&self) -> f32 {
        if self.armor_set == ArmorSet::RobotSuit && self.hull > 0.0 {
            STEP_UP * MECH_SCALE
        } else {
            STEP_UP
        }
    }

    pub fn height(&self) -> f32 {
        if self.in_heavy_mech() {
            // §11: a 3.03 m powered walker - and §21: it KNEELS. The
            // hitbox (`ray_vs_cylinder`) and the hit bands (the `frac`
            // tests in `apply_hit_dmg` and the projectile path) are both
            // expressed against this number, so lowering it here lowers
            // the capsule and the x2.0 visor weak point TOGETHER and
            // leaves the visor at the same 0.90 of the machine it always
            // sat at. That single fact is what makes the crouch legal.
            let standing = BODY_HEIGHT * MECH_SCALE;
            if self.chassis_kneeling() {
                standing * MECH_CROUCH_HEIGHT_FRAC
            } else {
                standing
            }
        } else if self.in_scout_mech() {
            // §owner AGILE SUPPORT MECH: SCOUT_SCALE was declared and never
            // consumed anywhere - a piloted scout fell through to the plain
            // player branches below and stood, crouched and rolled at
            // exactly player size. No kneel state for this chassis (it has
            // none - see `chassis_kneeling`'s heavy-only gate), so this is
            // unconditional: the whole point of the light chassis is that
            // it does not fold.
            BODY_HEIGHT * SCOUT_SCALE
        } else if self.roll_t > 0.0 {
            ROLL_HEIGHT
        } else if self.crouch {
            CROUCH_HEIGHT
        } else {
            BODY_HEIGHT
        }
    }
    /// §11: the chassis is wide — it cannot fit through doorways.
    pub fn radius(&self) -> f32 {
        if self.armor_set == ArmorSet::RobotSuit && self.hull > 0.0 {
            MECH_RADIUS
        } else {
            BODY_RADIUS
        }
    }
    /// §21: the pilot's eye height inside THIS hull, in world Y - the
    /// stance-aware companion to the free function `mech_visor_eye_y`.
    ///
    /// Identical to it for a standing chassis (`height()` is exactly
    /// `BODY_HEIGHT * MECH_SCALE` then), and correct for a kneeling one,
    /// which the free function cannot be: it only ever sees `pos_y` and so
    /// has no way to know the machine folded. The free function is kept
    /// because the client still calls it; every NEW caller wants this.
    ///
    /// It is `height() * MECH_VISOR_Y_FRAC` and not a second formula on
    /// purpose - the visor is the x2.0 weak point at frac 0.90, and
    /// `apply_hit_dmg` finds that band by dividing by `height()`. One
    /// expression, so the camera and the hit band cannot disagree about
    /// where the pilot's head is.
    pub fn visor_eye_y(&self) -> f32 {
        self.pos[1] + self.height() * MECH_VISOR_Y_FRAC
    }
    pub fn armed(&self) -> bool {
        self.gun != GunKind::Fists
    }
    /// §4.3: the zone mode `apply_hit` must use for this fighter.
    /// `flip_used` stays true from flip start through landing recovery —
    /// exactly the "full duration + recovery" window the rule demands.
    pub fn hit_zone_mode(&self) -> HitZoneMode {
        if self.flip_t > 0.0 || self.flip_used {
            HitZoneMode::Uniform
        } else {
            HitZoneMode::Banded
        }
    }
}

#[derive(Clone, Copy, Debug, Default)]
pub struct PlayerCmd {
    pub move_x: f32,
    pub move_z: f32,
    pub sprint: bool,
    /// §3.6: hold-to-WALK (CS:GO grammar). Slower, silent, and steadier
    /// on the trigger. The opposite end of `sprint` on the same axis, so
    /// both held at once resolves to walk — the careful intent wins,
    /// which is the safe way round for a stealth input.
    pub walk: bool,
    pub yaw: f32,
    pub aim: [f32; 3],
    pub shoot: bool,
    pub reload: bool,
    pub ads: bool,
    pub crouch: bool,
    pub jump: bool,
    /// Duck-spin dodge: a fast forward somersault in the move direction.
    pub dodge: bool,
    /// Select an inventory slot (0 primary, 1 secondary, 2 special).
    pub slot: Option<u8>,
    /// Toggle the shield stance (E). Edge-triggered like jump/reload.
    pub shield: bool,
    /// −1..+1 lean input.
    pub lean: f32,
    /// §5: holding a live grenade — release throws (cooking a frag past
    /// its fuse detonates it in hand).
    pub throw_hold: bool,
    /// §1 (Brief V): cancel the aimed throw — exits aim mode without
    /// throwing and without consuming the grenade. Edge-triggered.
    pub throw_cancel: bool,
    /// §4.6 (Brief VI): dismount the mech (U). Edge-triggered.
    pub exit_mech: bool,
    /// §5.3 (Brief VI): HOLD = missile targeting (lock acquires on
    /// mechs); RELEASE locked = launch; a quick tap dumb-fires.
    pub pod_aim: bool,
    /// §5: cycle the selected throwable (G). Edge-triggered.
    pub cycle_throw: bool,
    /// §6: armor ability held (now C — §5 took F) — Folk brace / Pyro
    /// flame / Robot repulsor.
    pub ability: bool,
    /// §5: knife held (F). Tap = quick slash, hold = committed lunge.
    pub knife_hold: bool,
    // §12 (owner) NOTE: there is deliberately no `cycle_fire_mode` here.
    // The turret's mode cycles on a RE-PRESS of the mount's own number
    // key - the same idiom G already uses for throwables ("G on an
    // already-equipped grenade cycles the type") - so the feature needs
    // no new input channel and no new binding. See the slot handler in
    // `step` and `TdmSim::last_slot_cmd`.
}

// ---------------------------------------------------------------- events

#[derive(Clone, Debug)]
pub struct KillEvent {
    pub killer: usize,
    pub victim: usize,
    pub headshot: bool,
    /// §4.5 modifier: the victim was flash-blind when they died.
    pub blind: bool,
    /// §4.5 modifier: a scoped-class weapon fired without being scoped.
    /// Only ever true for `GunSpec::scoped` guns - a rifle has no scope
    /// to not be looking through, so calling its shot a "noscope" would
    /// hand out the badge for nothing.
    pub noscope: bool,
    /// §4.5 modifier: the killing ray passed through a smoke bloom.
    pub smoke: bool,
    /// §4.5 modifier: the killing round punched through cover first.
    pub wallbang: bool,
    /// §4.5 (BRIEF VIII): the most recent OTHER fighter who damaged the
    /// victim within ASSIST_WINDOW_S of the kill. `None` if the killer
    /// landed every recent hit alone, or nobody else hit them recently
    /// enough to count.
    pub assist: Option<usize>,
}

/// §4.5: how recent a non-killing hit has to be to still count as an
/// assist - long enough to credit real teamwork, short enough that a
/// hit from ten seconds ago doesn't ride in on someone else's kill.
pub const ASSIST_WINDOW_S: f32 = 6.0;

#[derive(Clone, Debug)]
pub struct HitEvent {
    pub shooter: usize,
    pub victim: usize,
    pub zone: HitZone,
    pub damage: f32,
    /// True if the victim's raised shield ate most of this hit.
    pub shielded: bool,
    pub from: [f32; 3],
    /// impact point — part of the event API even when the client skips it
    #[allow(dead_code)]
    pub at: [f32; 3],
    pub fatal: bool,
}

#[derive(Clone, Debug)]
pub struct Impact {
    pub at: [f32; 3],
    pub normal: [f32; 3],
}

#[derive(Clone, Debug)]
pub struct Tracer {
    pub from: [f32; 3],
    pub to: [f32; 3],
    pub team: Team,
    pub ttl: f32,
    /// Who fired it. Pure presentation data - the renderer needs it to
    /// know which streak is the LOCAL player's, because a first-person
    /// shot has to be drawn leaving the weapon on screen rather than the
    /// eye the ray was actually cast from.
    pub shooter: usize,
}

/// §owner What a missile IS, as opposed to how it flies.
///
/// This started as a lone `is_spear: bool`, which was honest while there
/// were exactly two kinds. Then the plasma cannon landed and reused the
/// arrow's flight model - deliberately, and the comment in
/// `try_fire_plasma` says so: same gravity, same hit rule, no pierce.
///
/// But `is_spear: false` does not mean "flies like an arrow". Every
/// caller read it as "IS an arrow", and two of them were right to,
/// because that is what the name says. So a bolt of superheated plasma
/// rendered as a fletched wooden shaft with SPINNING VANES, and when it
/// came to rest it converted into a recoverable arrow 65% of the time -
/// which made a weapon that has no ammunition, only heat, into a
/// fountain of free arrows for whoever walked past the impact.
///
/// A third state cannot be added to a bool. It can be added here, and
/// every match on it has to say what it means about plasma before it
/// compiles - which is the entire reason to spend the refactor.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum MissileKind {
    #[default]
    Arrow,
    Spear,
    /// §owner the medic's plasma bolt. Flies as an arrow, is made of
    /// nothing you can pick up, and glows.
    Plasma,
}

/// Arrow / thrown spear / plasma bolt in flight (or stuck).
#[derive(Clone, Debug)]
pub struct Missile {
    /// stable identity — part of the sim API even when the client pools by index
    #[allow(dead_code)]
    pub id: u32,
    pub pos: [f32; 3],
    pub vel: [f32; 3],
    pub team: Team,
    pub shooter: usize,
    pub damage: f32,
    /// What this shot is. Read `is_spear()` for the flight question and
    /// `recoverable_as()` for the pickup question - the two used to be
    /// the same field, and that is exactly how plasma became wood.
    pub kind: MissileKind,
    pub stuck_t: Option<f32>,
    /// §3.2 (Brief VII v2): set at the moment of a world/ground hit -
    /// true = embedded (steep enough to stick), false = a shallow
    /// glancing hit that bounced off with a clatter. Only meaningful for
    /// spears (arrows always use their own recovery-probability roll);
    /// body/zombie hits never touch this (always effectively embedded).
    pub embedded: bool,
    /// §4.2 (Brief VII v2): arrows only - how many more bodies this
    /// shot can pass through (starts at BOW_MAX_PIERCES, 0 = the next
    /// body hit embeds instead of piercing).
    pub pierces_left: u8,
    /// §4.2: fighters already pierced by THIS shot - a multi-tick
    /// overlap with the same body must not double-count.
    pub pierced: Vec<usize>,
    /// §4.1: this shot's draw-power fraction (0.35-1.0) - scales every
    /// pierce's damage, not just the first.
    pub power: f32,
}

impl Missile {
    /// The FLIGHT question: does this fly and land like a thrown spear?
    ///
    /// Plasma answers no, which is what the old field already meant for
    /// it and the one reading of `is_spear: false` that was correct.
    /// Gravity, the stick angle and the head multiplier all key off
    /// this, and plasma is meant to share the arrow's numbers there.
    pub fn is_spear(&self) -> bool {
        matches!(self.kind, MissileKind::Spear)
    }

    /// The PICKUP question: what, if anything, does this leave on the
    /// ground for someone to walk over?
    ///
    /// Plasma answers `None`. It is a discharge, not an object; there is
    /// nothing to recover and no quiver it would go into. This is the
    /// half `is_spear` got WRONG - it made every non-spear an arrow, so
    /// a weapon with no ammunition minted ammunition for both teams.
    pub fn recoverable_as(&self) -> Option<AmmoKind> {
        match self.kind {
            MissileKind::Arrow => Some(AmmoKind::Arrow),
            MissileKind::Spear => Some(AmmoKind::Spear),
            MissileKind::Plasma => None,
        }
    }
}

/// §3.2 (Brief VII v2): impact angle from surface (0 deg = grazing,
/// 90 deg = straight-on), given the travel direction and surface normal.
pub fn impact_angle_to_surface_deg(dir: [f32; 3], normal: [f32; 3]) -> f32 {
    let dot = (dir[0] * normal[0] + dir[1] * normal[1] + dir[2] * normal[2]).clamp(-1.0, 1.0);
    dot.abs().asin().to_degrees()
}

/// §3.2: at or above this angle-to-surface, a thrown spear embeds;
/// shallower and it bounces off (arrows are unaffected - own mechanic).
pub const SPEAR_STICK_ANGLE_DEG: f32 = 30.0;

// ---- §4.1/§4.2 (Brief VII v2): the bow's draw-and-pierce rework -----------
/// Release under this = letdown, no shot (prevents accidental dribbles).
pub const BOW_DRAW_MIN_S: f32 = 0.15;
/// Full draw - 100% power reached here; holding longer doesn't add more.
pub const BOW_DRAW_FULL_S: f32 = 0.7;
/// Held this long total with no release - forced letdown, no shot.
pub const BOW_DRAW_FORCE_S: f32 = 10.0;
/// Full-draw arrow speed, gravity ×0.42 (unchanged factor from Brief II).
pub const BOW_V0_FULL: f32 = 55.0 * MISSILE_SPEED_MULT;
/// §4.2: passes through up to 3 soldiers - 90 -> 68 -> 45 (×0.75/pierce),
/// each scaled by the shot's own draw-power fraction.
pub const BOW_PIERCE_DMG: [f32; 3] = [90.0, 67.5, 50.625];
pub const BOW_MAX_PIERCES: u8 = 3;

/// §4.1: the power a shot carries at the MINIMUM valid draw. Named
/// because the client's arc preview needs the same floor to draw the
/// early-draw arc correctly.
pub const BOW_POWER_MIN: f32 = 0.35;
/// §4.1-B (owner): holding PAST full draw keeps charging. From full
/// (0.7s) to overdraw-full (1.6s) the shot gains a further 15% launch
/// speed and damage - the archer leaning into the string. It stacks
/// with nothing else and tops out well before the 4s sway window, so
/// the reward for patience arrives before the punishment for staring.
pub const BOW_OVERDRAW_MAX: f32 = 1.15;
pub const BOW_OVERDRAW_FULL_S: f32 = 1.6;

/// §4.1: draw power fraction (35% -> 100%, linear) for a hold of
/// `held_s` seconds; `None` means letdown (too short or forced at 10s).
pub fn bow_power_fraction(held_s: f32) -> Option<f32> {
    if held_s < BOW_DRAW_MIN_S || held_s >= BOW_DRAW_FORCE_S {
        return None;
    }
    let t = ((held_s - BOW_DRAW_MIN_S) / (BOW_DRAW_FULL_S - BOW_DRAW_MIN_S)).clamp(0.0, 1.0);
    let base = BOW_POWER_MIN + (1.0 - BOW_POWER_MIN) * t;
    if held_s <= BOW_DRAW_FULL_S {
        return Some(base);
    }
    // §4.1-B overdraw: base is exactly 1.0 here, and the extra ramps in
    // over the overdraw window
    let over = ((held_s - BOW_DRAW_FULL_S) / (BOW_OVERDRAW_FULL_S - BOW_DRAW_FULL_S))
        .clamp(0.0, 1.0);
    Some(base * (1.0 + (BOW_OVERDRAW_MAX - 1.0) * over))
}

// ---- §4.1: full-draw hold sway --------------------------------------
// "Full-draw hold: steady 4s; then rotational aim sway ramps +/-0.4deg
// -> +/-1.2deg over the next 4s... forced letdown at 10s total.
// Crouching halves sway." A real archer's hold degrades with time; the
// bow rewards a snappy release over a held stare, exactly like the
// running-throw bonus rewards committing rather than waiting.
pub const BOW_SWAY_HOLD_S: f32 = 4.0; // steady window before sway starts
pub const BOW_SWAY_RAMP_S: f32 = 4.0; // 4s..8s: sway grows over this span
pub const BOW_SWAY_MIN_DEG: f32 = 0.4;
pub const BOW_SWAY_MAX_DEG: f32 = 1.2;

/// Current sway MAGNITUDE (the +/- half-angle) for a hold of `held_s`
/// seconds; 0 before the steady window ends. The actual perturbation
/// applied to a shot is a random draw within [-this, +this], using the
/// sim's own seeded stream (see the fire path) so it stays replay-exact.
pub fn bow_sway_deg(held_s: f32, crouched: bool) -> f32 {
    if held_s <= BOW_SWAY_HOLD_S {
        return 0.0;
    }
    let t = ((held_s - BOW_SWAY_HOLD_S) / BOW_SWAY_RAMP_S).clamp(0.0, 1.0);
    let deg = BOW_SWAY_MIN_DEG + (BOW_SWAY_MAX_DEG - BOW_SWAY_MIN_DEG) * t;
    if crouched {
        deg * 0.5
    } else {
        deg
    }
}

