/// A grenade in flight or at rest, fuse burning. Point-mass integration
/// at the fixed 120 Hz tick — tumble spin is CLIENT-side only.
#[derive(Clone, Debug)]
pub struct Grenade {
    pub id: u32,
    pub kind: ThrowKind,
    pub pos: [f32; 3],
    pub vel: [f32; 3],
    pub thrower: usize,
    pub team: Team,
    pub fuse_t: f32,
    pub bounces: u32,
    pub rest: bool,
}

/// What one grenade physics tick concluded.
pub enum GrenadeTick {
    Fly,
    Boom,
    Rest,
}

/// Brief IX-B "Bounce & Rolling Physics": each cover material's own
/// bounce coefficient, overriding the throw kind's default restitution
/// on contact with that specific material. Organic surfaces (brief:
/// "cloth, flesh, sandbagged positions") are sticky - effectively zero
/// bounce, the grenade stays where it lands - mapped onto the two
/// vegetation `CoverKind`s (hedge/tree) as this game's closest analog;
/// stone is stone, crates stand in for the brief's "wood/metal".
fn surface_restitution(kind: CoverKind) -> f32 {
    match kind {
        CoverKind::Stone => 0.40,
        CoverKind::Crate => 0.50,
        CoverKind::Hedge | CoverKind::Tree => 0.05,
    }
}

/// R&D Cycle 2 (backlog #3): per-surface FRICTION, alongside the
/// already-existing per-surface restitution above. [S-01, RoyMech
/// tribology table]: metal-on-wood sliding friction runs 0.2-0.6 (dry,
/// clean) against metal-on-masonry/rock in the 0.3-0.6 family
/// (concrete+rock 0.3 sliding was the only steel-specific masonry row
/// found; broader rock-family rows run higher but are rock-on-rock, not
/// metal-on-rock) - real data with real overlap, not a crisp single
/// answer, honestly not oversold into more precision than the source
/// supports. Direction taken: worked masonry (this game's stone cover)
/// is smoother than a rough-grain wood crate, so a bounce skids FURTHER
/// across stone than off a crate - low end of the wood range for
/// crates, low end of the masonry range for stone, keeping both
/// comfortably inside the source's own bracket.
fn surface_friction(kind: CoverKind) -> f32 {
    match kind {
        CoverKind::Stone => 0.30,
        CoverKind::Crate => 0.45,
        // moot in practice - Hedge/Tree stick on contact (zero bounce,
        // velocity zeroed below) before tangential friction would ever
        // apply, but a real number belongs here regardless of reachability
        CoverKind::Hedge | CoverKind::Tree => 0.60,
    }
}

/// Which cover object (if any) a bounce contact point actually landed
/// on, to look up its material. An independent short scan rather than
/// threading an index through `CoverGrid::ray_hit`'s return type (used
/// by seven unrelated systems - bullets, LOS, rockets, smoke) - cover
/// counts are small (tens, not thousands) per map, so this stays cheap.
fn cover_kind_at(cover: &[Aabb], cover_kind: &[CoverKind], contact: [f32; 3]) -> Option<CoverKind> {
    const PAD: f32 = 0.05;
    cover.iter().position(|a| {
        (0..3).all(|k| contact[k] >= a.min[k] - PAD && contact[k] <= a.max[k] + PAD)
    })
    .and_then(|i| cover_kind.get(i).copied())
}

/// One 120 Hz grenade physics tick — THE integrator, shared verbatim by
/// the live flight (`step_grenades`) and the §1 (Brief V) aim preview
/// (`predict_grenade`). There is deliberately no second arc formula
/// anywhere: a preview that can diverge from the throw is worse than no
/// preview. 9.81 gravity, friction+restitution bounce (material-specific
/// per Brief IX-B where the contact is a known cover object), rest test,
/// settle guarantee, molotov shatter, fuse expiry.
pub fn grenade_tick(
    g: &mut Grenade,
    grid: &CoverGrid,
    cover: &[Aabb],
    cover_kind: &[CoverKind],
) -> GrenadeTick {
    g.fuse_t -= DT;
    if g.fuse_t <= 0.0 {
        return GrenadeTick::Boom;
    }
    if g.rest {
        return GrenadeTick::Rest;
    }
    g.vel[1] -= 9.81 * DT;
    let old = g.pos;
    let new = [
        old[0] + g.vel[0] * DT,
        old[1] + g.vel[1] * DT,
        old[2] + g.vel[2] * DT,
    ];
    let seg = [new[0] - old[0], new[1] - old[1], new[2] - old[2]];
    let seg_len = (seg[0] * seg[0] + seg[1] * seg[1] + seg[2] * seg[2])
        .sqrt()
        .max(1e-6);
    let dn = [seg[0] / seg_len, seg[1] / seg_len, seg[2] / seg_len];
    // first surface on the path: cover (via the §9.1 grid) or ground
    let mut hit: Option<(f32, [f32; 3])> = grid.ray_hit(cover, old, dn, seg_len);
    if new[1] <= 0.0 && old[1] > 0.0 {
        let t = (0.0 - old[1]) / (new[1] - old[1]) * seg_len;
        if hit.map_or(true, |(ht, _)| t < ht) {
            hit = Some((t, [0.0, 1.0, 0.0]));
        }
    }
    if let Some((t, n)) = hit {
        let spec = throw_spec(g.kind);
        if g.kind == ThrowKind::Molotov {
            // shatters on ANY surface — the pool spawns at impact
            g.pos = [
                old[0] + dn[0] * t,
                (old[1] + dn[1] * t).max(0.02),
                old[2] + dn[2] * t,
            ];
            return GrenadeTick::Boom;
        }
        let contact = [
            old[0] + dn[0] * (t - 0.01).max(0.0),
            old[1] + dn[1] * (t - 0.01).max(0.0),
            old[2] + dn[2] * (t - 0.01).max(0.0),
        ];
        // Brief IX-B: a contact on a KNOWN cover object uses that
        // material's own bounce coefficient in place of the throw kind's
        // default (ground-plane hits, with no cover object, keep the
        // kind's own restitution unchanged - unaffected by this).
        let material = cover_kind_at(cover, cover_kind, contact);
        let base_restitution = material.map_or(spec.restitution, surface_restitution);
        // R&D Cycle 2: friction is now ALSO per-material on a known
        // cover object, same fallback rule as restitution above - a
        // ground-plane hit with no cover object keeps the throw kind's
        // own uniform friction, exactly as before this cycle.
        let friction = material.map_or(spec.friction, surface_friction);
        let sticky = matches!(material, Some(CoverKind::Hedge) | Some(CoverKind::Tree));
        let vn = g.vel[0] * n[0] + g.vel[1] * n[1] + g.vel[2] * n[2];
        let vnv = [n[0] * vn, n[1] * vn, n[2] * vn];
        let vt = [g.vel[0] - vnv[0], g.vel[1] - vnv[1], g.vel[2] - vnv[2]];
        g.bounces += 1;
        let rest_coef = if g.bounces > 3 {
            base_restitution * 0.5_f32.powi(g.bounces as i32 - 3)
        } else {
            base_restitution
        };
        g.vel = [
            vt[0] * (1.0 - friction) - vnv[0] * rest_coef,
            vt[1] * (1.0 - friction) - vnv[1] * rest_coef,
            vt[2] * (1.0 - friction) - vnv[2] * rest_coef,
        ];
        g.pos = contact;
        if sticky {
            // "sticks on contact... does not bounce; detonates in place"
            g.rest = true;
            g.vel = [0.0; 3];
        }
        // §5.2 rest test — without it: infinite micro-bounces
        let speed = (g.vel[0] * g.vel[0] + g.vel[1] * g.vel[1] + g.vel[2] * g.vel[2]).sqrt();
        if !g.rest && vn.abs() * rest_coef < 0.35 && speed < 0.6 {
            g.rest = true;
            g.vel = [0.0; 3];
            g.pos[1] = g.pos[1].max(0.02);
        }
    } else {
        g.pos = new;
    }
    GrenadeTick::Fly
}

/// §5.4: an active smoke sphere — occludes bot LOS via path length.
#[derive(Clone, Debug)]
pub struct SmokeVolume {
    pub pos: [f32; 3],
    pub ttl: f32,
}

/// §5.5: a molotov fire pool — 4 Hz damage ticks, blocks bot pathing.
#[derive(Clone, Debug)]
pub struct FirePool {
    pub pos: [f32; 3],
    pub ttl: f32,
    pub thrower: usize,
    pub tick_t: f32,
}

/// Detonation event for client FX (kind + where), with a display ttl.
#[derive(Clone, Debug)]
pub struct Boom {
    pub at: [f32; 3],
    pub kind: ThrowKind,
}

// ---- §6 (Brief II): armor sets with full powers --------------------------

/// Found and equipped in-world, never spawned with. Lost on death.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArmorSet {
    None,
    /// Mail and plate; Shieldwall Brace (hold F).
    Folk,
    /// RETIRED as a wearable set. §owner MECHANICAL MEDIC took its
    /// slot on the pad rotation: the owner asked for the Pyro role to
    /// be replaced by a support-focused mech, and a flamethrower and a
    /// repair beam are the same slot answered two ways.
    ///
    /// The variant SURVIVES rather than being deleted, because it is
    /// still what a fire pool and the flame projector check against,
    /// and ripping it out would have meant rewriting the burn model to
    /// close a cosmetic gap. Nothing spawns it any more.
    Pyro,
    /// The grounded walker chassis; side-step (Q) + Repulsor Blast (C),
    /// running on a power core. (Flight was deleted in Brief VI §4.3 -
    /// this doc advertised thrusters for two briefs after they died.)
    RobotSuit,
    /// The light counterweight: fast, quiet, self-healing. No abilities.
    Recon,
    /// §owner AGILE SUPPORT MECH: the second chassis.
    ///
    /// A walker like `RobotSuit` and nothing else about it is the same.
    /// Where the heavy is a wall that shoots, this is a runner that keeps
    /// the wall standing: a third of the hull, faster than a man on foot,
    /// a plasma cannon that never runs out but overheats, and a beam that
    /// puts hull back into whoever is taking the fire.
    ///
    /// It is a separate SET rather than a flag on `RobotSuit` because
    /// every number about it differs - armour, pace, hull, mounts, and
    /// what it is afraid of - and a boolean would have meant a branch at
    /// every one of those.
    ScoutMech,
}

impl ArmorSet {
    /// Is this set a WALKER - a piloted chassis rather than worn kit?
    ///
    /// The two mechs share the whole chassis vocabulary: no crouching, a
    /// hull pool instead of armour, mount weapons instead of carried
    /// ones, committal entry and exit. Everything that asked
    /// `== RobotSuit` to mean "in a mech" asks this instead, which is
    /// what stopped the second chassis from having to be retro-fitted
    /// into thirty comparisons one at a time.
    pub fn is_mech(self) -> bool {
        matches!(self, ArmorSet::RobotSuit | ArmorSet::ScoutMech)
    }
}

/// §6.1: flat per-zone reduction applied AFTER the zone multiplier, with
/// a floor of 15% of base damage — heavy sets never make limb shots free,
/// and head flats stay small so headshots remain decisive.
pub struct ArmorSpec {
    pub flat_head: f32,
    pub flat_torso: f32,
    pub flat_limb: f32,
    pub move_mult: f32,
    /// Fraction of explosive damage shrugged off.
    pub explosive_resist: f32,
}

pub fn armor_spec(s: ArmorSet) -> ArmorSpec {
    match s {
        ArmorSet::None => ArmorSpec {
            flat_head: 0.0,
            flat_torso: 0.0,
            flat_limb: 0.0,
            move_mult: 1.0,
            explosive_resist: 0.0,
        },
        ArmorSet::Folk => ArmorSpec {
            flat_head: 12.0,
            flat_torso: 45.0,
            flat_limb: 15.0,
            move_mult: 0.92,
            explosive_resist: 0.0,
        },
        ArmorSet::Pyro => ArmorSpec {
            flat_head: 14.0,
            flat_torso: 30.0,
            flat_limb: 30.0,
            move_mult: 0.96,
            explosive_resist: 0.5,
        },
        ArmorSet::RobotSuit => ArmorSpec {
            flat_head: 16.0,
            flat_torso: 55.0,
            flat_limb: 55.0,
            move_mult: 0.85, // §4.3 (Brief VI): 85% of soldier run pace
            explosive_resist: 0.0,
        },
        ArmorSet::Recon => ArmorSpec {
            flat_head: 12.0,
            flat_torso: 12.0,
            flat_limb: 12.0,
            move_mult: 1.10,
            explosive_resist: 0.0,
        },
        // §owner MECHANICAL MEDIC: a chassis that survives by not being
        // hit. Roughly HALF the heavy's flat reduction, and the FASTEST
        // machine in the game - "relies on mobility instead of
        // durability", expressed in the two numbers that decide it.
        //
        // 1.28 is deliberately 15% clear of the Recon weave's 1.10, the
        // quickest thing a soldier can wear. "Fastest mech" is not worth
        // stating if a man on foot can outrun it.
        ArmorSet::ScoutMech => ArmorSpec {
            flat_head: 10.0,
            flat_torso: 26.0,
            flat_limb: 26.0,
            move_mult: 1.28,
            explosive_resist: 0.0,
        },
    }
}

// ---- §owner AGILE SUPPORT MECH -------------------------------------------
//
// The second chassis. Everything below is a number the heavy already has
// and this one needed a different answer to.

/// Hull pool. A third of the heavy's 600 - it is not meant to trade.
pub const SCOUT_HULL: f32 = 210.0;
/// Scale, against the heavy's chassis. Slimmer and shorter, so it reads
/// as a different silhouette from across a map rather than a repaint.
///
/// §owner: 1.05 - only 5% over `BODY_HEIGHT`, a near-human scout rather
/// than a small mech. Declared and unused until now: nothing in `height()`
/// ever multiplied by this, so a piloted scout collided and hit-tested at
/// plain player size regardless of what this said. See `height()`.
pub const SCOUT_SCALE: f32 = 1.05;
/// §owner WEAKNESS: what a spear or an arrow does to it.
///
/// The brief asks for "very vulnerable to spears, very vulnerable to
/// arrows", and this is the whole of that. It is a MULTIPLIER on the
/// war weapons specifically, not a general fragility, because the point
/// is to give the two weapons that lose to a heavy chassis something
/// they beat - a bow that is useless against every mech is a bow nobody
/// brings to a mech fight.
pub const SCOUT_WAR_WEAPON_MULT: f32 = 2.4;

/// PLASMA: the primary. No magazine, no reserve, no reload - a heat
/// budget instead, and the trigger stops working when you spend it.
///
/// Heat per shot and the cool rate are set so a disciplined pilot fires
/// forever and a panicking one locks themself out for two seconds. The
/// numbers are deliberately kinder than the gatling's: that mount vents
/// as a punishment for holding the trigger, and this one is the weapon's
/// entire ammunition model, so it has to be livable.
/// Tuned so THREE SECONDS of held fire reaches the vent, which is the
/// number the brief names. Derived rather than guessed: at a 0.16 s
/// period that is 6.25 shots a second, so 1.0 / (6.25 * 3.0) = 0.053.
pub const PLASMA_HEAT_PER_SHOT: f32 = 0.053;

// ---- the two FIRING MODES ------------------------------------------------
//
// A support weapon with one trigger is a weapon that does one thing, and
// the medic's job changes second to second: suppress a push, then thread
// a shot into whoever is about to kill the man it is healing. So RAPID
// on the trigger, PRECISION on the right button.
//
// They share the heat budget on purpose. The precision shot is not free
// because you were not shooting - it costs a large slice of the same
// pool, so a pilot who empties the budget on suppression cannot then
// also land the big one.

/// Precision: one heavy bolt, flat and fast, on its own long cooldown.
pub const PLASMA_PRECISION_DAMAGE: f32 = 95.0;
pub const PLASMA_PRECISION_SPEED: f32 = 130.0;
/// The brief's "approximately 5-6 second cooldown".
pub const PLASMA_PRECISION_CD_S: f32 = 5.5;
/// How long the shot takes to charge before it goes. Long enough to be
/// a commitment and to read as a wind-up from outside, short enough that
/// it is a shot rather than a ritual.
pub const PLASMA_CHARGE_S: f32 = 0.85;
/// What a charged shot costs from the shared heat pool - a third of it.
pub const PLASMA_PRECISION_HEAT: f32 = 0.34;
pub const PLASMA_COOL_PER_S: f32 = 0.34;
pub const PLASMA_FIRE_PERIOD: f32 = 0.16;
pub const PLASMA_DAMAGE: f32 = 26.0;
pub const PLASMA_SPEED: f32 = 68.0;
/// Overheat lockout: at 1.0 heat the mount vents and refuses to fire
/// until it has run down.
pub const PLASMA_VENT_S: f32 = 2.0;

/// REPAIR BEAM: the secondary, and the reason this chassis exists.
pub const REPAIR_RANGE_M: f32 = 26.0;
/// Hull per second put into the target. Slower than a rifle removes it,
/// so a support mech extends a fight rather than deciding one.
pub const REPAIR_PER_S: f32 = 42.0;
/// How wide a cone the beam will grab an ally in. Generous - the beam
/// is a support verb, not a skill shot, and fighting the reticle to
/// heal someone is not interesting.
pub const REPAIR_ARC_COS: f32 = 0.90;
/// The beam draws from the same heat budget the cannon does, so a pilot
/// cannot both suppress and sustain at full rate. One mount, one budget.
pub const REPAIR_HEAT_PER_S: f32 = 0.16;

/// §6.1 damage floor: no set reduces a hit below this fraction of the
/// gun's BASE damage — otherwise players stop aiming.
pub const ARMOR_FLOOR_FRAC: f32 = 0.15;
/// Folk Shieldwall Brace: frontal arc, reduction, stacking wall bonus.
pub const BRACE_ARC_COS: f32 = 0.574; // cos(55°) — a 110° frontal arc
pub const BRACE_REDUCTION: f32 = 0.82;
pub const BRACE_STACK_BONUS: f32 = 0.08;
pub const BRACE_STACK_CAP: u32 = 3;
pub const BRACE_SPEED_MULT: f32 = 0.25;

// ---- §A: Mech Brace ------------------------------------------------
// Widen the stance / drop the centre of mass to enlarge the ZMP support
// polygon (Vukobratovic & Borovac). A NEW, mech-scoped set - deliberately
// NOT a reuse of the Folk brace constants above.
//
// WHY A SEPARATE FIELD AND SEPARATE CONSTANTS. `Fighter::brace` drives
// two things. Its damage reduction IS armor_set-gated to Folk, so reuse
// would have been harmless there. But the movement penalty at the two
// sites below is NOT gated on armor_set - so setting `brace` on a mech
// would silently apply the INFANTRY 0.25x, and any later rebalance of
// BRACE_SPEED_MULT would move mech pacing as an invisible side effect.
// The two are calibrated for completely different mass and HP scales
// (MECH_HULL 600.0 vs infantry HP two orders of magnitude smaller).
pub const MECH_BRACE_STANCE_DROP: f32 = 0.12; // fraction of height() the hull sinks
pub const MECH_BRACE_SPEED_MULT: f32 = 0.12; // below infantry's 0.25 - braced is near-planted
pub const MECH_BRACE_RECOIL_DAMP: f32 = 0.30; // fraction of unbraced kick retained

// ---- §C: the mech's hull-mounted weapons ----------------------------
/// The chassis' two hull mounts - rigidly bolted, never held, always
/// BOTH present the moment the suit is equipped. Selecting between them
/// is a targeting-mode switch, not a pickup or a loadout choice.
///
/// WHY THIS IS NOT A `GunKind`. `GunKind` is the spine of the INFANTRY
/// weapon pipeline: `gun(kind) -> GunSpec`, `ALL_WEAPONS`/`N_WEAPONS`
/// and the `vm.weapons[N_WEAPONS]` viewmodel array, `weapon_slot`,
/// `reload_pose`, the loadout screen's `PRIMARIES`/`GunClass` tables,
/// and a per-weapon punch-slot mapping. Every one of those encodes
/// "a carryable, swappable, loadout-selectable gun with a magazine and
/// a pair of hands on it". These two are STRUCTURAL - never picked up,
/// never swapped into a slot, never reloaded, never in a loadout, and
/// there is no hand pose for them. Routing them through `GunKind` would
/// mean answering ~8 exhaustive matches with semantics that do not
/// apply, and every one of those answers would be a lie the next
/// feature reads as truth.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum MechWeapon {
    #[default]
    Gatling,
    Autocannon,
    /// §C.7 (Brief VIII): the missile pod as a SELECTABLE mount. The
    /// pilot's strip is TURRET [1] / ROCKETS [2]; with this selected the
    /// trigger launches a tube (`try_fire_rocket`) and RMB is pure
    /// pre-aim - lock accrual and the amber arc, never a launch. The
    /// autocannon mount still exists on the enum for the BOT brain,
    /// which picks its mount by range, not by number key.
    Rockets,
    /// §owner AGILE SUPPORT MECH: the plasma cannon. Fires forever and
    /// overheats; see `PLASMA_HEAT_PER_SHOT`.
    Plasma,
    /// §owner AGILE SUPPORT MECH: the repair beam. Puts hull into an
    /// ally rather than damage into an enemy - the one mount in the game
    /// whose trigger is aimed at your own side.
    Repair,
}

impl MechWeapon {
    /// The mounts a chassis puts ON THE STRIP - what the pilot can
    /// select with 1 and 2, in that order.
    ///
    /// This is a UI list, and it is deliberately not the same question
    /// as `valid_for`: the heavy's autocannon is a real mount that a bot
    /// picks by range, and it has never had a number key. Treating this
    /// list as "every mount the chassis can hold" is what broke the bot
    /// autocannon the first time the two were confused.
    pub fn for_set(s: ArmorSet) -> &'static [MechWeapon] {
        match s {
            ArmorSet::ScoutMech => &[MechWeapon::Plasma, MechWeapon::Repair],
            _ => &[MechWeapon::Gatling, MechWeapon::Rockets],
        }
    }

    /// Every mount a chassis can legitimately be HOLDING, strip or not.
    ///
    /// Includes the heavy's autocannon, which the bot brain selects by
    /// range and no player can. The two mechs still share nothing: a
    /// heavy cannot heal and a medic cannot put a rocket downrange.
    pub fn valid_for(s: ArmorSet) -> &'static [MechWeapon] {
        match s {
            ArmorSet::ScoutMech => &[MechWeapon::Plasma, MechWeapon::Repair],
            _ => &[
                MechWeapon::Gatling,
                MechWeapon::Rockets,
                MechWeapon::Autocannon,
            ],
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            MechWeapon::Gatling => "TURRET",
            MechWeapon::Autocannon => "AUTOCANNON",
            MechWeapon::Rockets => "ROCKETS",
            MechWeapon::Plasma => "PLASMA BOW",
            MechWeapon::Repair => "REPAIR",
        }
    }
}
/// Gatling: SUPPRESSION. Every number is set against the man-portable
/// minigun, because that is the weapon a player will compare it to.
/// Heat per round is BELOW the minigun's 1.5 and the fire period is a
/// touch longer than its 0.06 - together those two make the hull gun
/// sustain roughly twice as long before it cooks off, which is the
/// whole identity: the minigun is a 4-second scream, this is the wall
/// of fire you walk behind.
pub const GATLING_HEAT_PER_SHOT: f32 = 0.9;
/// Below MINIGUN_HEAT_DECAY (16.5): a sealed hull mount has no open
/// barrel shroud to dump heat through, so it sheds it slower once the
/// trigger comes off. The longer sustain is paid for with a longer wait.
pub const GATLING_HEAT_DECAY: f32 = 9.5;
/// Longer than the minigun's forced 3.0 s, for the same reason.
pub const GATLING_VENT_FORCED_S: f32 = 3.5;
/// The REQUESTED period. What the mount actually cycles at is this value
/// rounded UP to a whole tick — `gatling_cd` is decremented by `DT` and
/// the gate opens at `<= 0`, so the real period is
/// `ceil(0.07 / DT) * DT` = **0.075 s at the 120 Hz sim floor, i.e. 800
/// RPM**, not the 857 the constant reads as. Worth knowing before anyone
/// tunes this against a published RPM figure: at 60 Hz it quantises to
/// 0.0833 s (720 RPM) and at 240 Hz to 0.0708 s (847 RPM).
pub const GATLING_FIRE_PERIOD: f32 = 0.07; // same ROF class as the minigun's 0.06
/// Trigger-intent hold window for the hull mount — deliberately the same
/// 70 ms as `MINIGUN_SPIN_HOLD_S`, because it is the same mechanism: the
/// heat decay is suppressed while the trigger is DOWN, and the timer is
/// what carries that intent across the ticks between rounds.
pub const GATLING_TRIGGER_HOLD_S: f32 = 0.07;
/// §owner: the hull gatling's belt. 300 rounds per chassis; ammo pads
/// top it up. Zero rounds = a silent mount, exactly like a dry gun.
pub const MECH_ROUNDS: u32 = 300;
pub const GATLING_DAMAGE: f32 = 9.0; // near the minigun's 8.0 - high ROF, low per-round
pub const GATLING_SPREAD_COLD: f32 = 0.018;
pub const GATLING_SPREAD_HOT: f32 = 0.052;
/// Autocannon: PRECISION. A handful of unarmoured hits through MECH_HULL,
/// on a slow cycle and a tight cone - the deliberate opposite of the
/// gatling's spray.
pub const AUTOCANNON_DAMAGE: f32 = 145.0;
pub const AUTOCANNON_CYCLE_S: f32 = 1.35;
/// §13 (owner): the cannon's kick, DERIVED - see `autocannon_kick`,
/// which is where the number now comes from. Kept as a named constant
/// only so the old symbol still resolves; nothing reads it.
#[allow(dead_code)]
pub const AUTOCANNON_UNBRACED_KICK: f32 = 6.0;
pub const AUTOCANNON_SPREAD: f32 = 0.006;
// NOTE: there is deliberately NO `AUTOCANNON_BRACED_KICK`. The braced
// value is derived at the call site as
// `AUTOCANNON_UNBRACED_KICK * MECH_BRACE_RECOIL_DAMP`. Two independently
// tunable numbers describing ONE relationship drift out of sync after a
// single balance pass; §A built the damp mechanism generically for
// exactly this consumer.

// ---- §12/§13 (owner): the hull TURRET's fire modes and its recoil -------
//
// Recoil was ALREADY per-weapon everywhere a man carries a gun: every
// `GunSpec` has its own `kick`, and `spray_entry` turns that into a
// per-weapon, per-shot pattern seeded off the weapon's own slot, then
// scales it by the scope, the lean, the walk and the brace. What was
// missing was the hull turret, which wrote NO recoil at all - a
// 800 RPM mount you could hold on a man's head for three hundred rounds
// while the autocannon beside it kicked. That is the gap these fill.

/// How much of a man's recoil the CHASSIS gives back. The one number in
/// this block that is a judgement rather than a derivation, and it is
/// the whole of the brief's sentence: "the mech manages recoil better
/// than a man, but it still kicks hard".
///
/// It lands the turret's per-round kick at 8.3 deg/s of punch velocity:
/// above the man-portable minigun's 7.2 (whose own spec says "the mass
/// eats the recoil" - the hull mount is not that), and well under the
/// M4's 28.8. Held on full auto it settles at about 4.2 deg of punch
/// against the M4's 4.9, so a 800 RPM hull turret walks a little LESS
/// than a rifle does - which is the brief's sentence stated as a
/// measurement. Planted, the existing MECH_BRACE_RECOIL_DAMP takes the
/// settled punch to zero, so the brace stays the answer to wanting the
/// turret to hold still.
///
/// THE CEILING IS SET BY THE BOTS, not by feel. A bot has no mouse and
/// nothing in this file makes it pull down: `punched_aim` deflects a
/// bot's ray by the FULL RECOIL_SCALE while the player's already
/// carries 45% in the camera. At 0.45 a bot mech's rounds walk clean
/// over a man at 10 m within a second of holding the trigger, and
/// `a_bot_mech_never_runs_dry_the_way_the_gun_in_its_hands_does`
/// catches it. That asymmetry is older than this constant - it applies
/// to every recoiling weapon a bot carries - and is deliberately NOT
/// fixed here, because fixing it properly means touching the aim of
/// every bot in the game rather than one hull mount.
pub const MECH_RECOIL_CONTROL: f32 = 0.40;

/// Per-round turret kick, in degrees per second of punch VELOCITY - the
/// same channel and the same units `spray_entry` feeds for a rifle.
///
/// Derived rather than picked, against the M4, which this file's own
/// spec table calls "THE baseline". Two honest ratios:
///
///   * `gun(M4).kick × 9000` is the M4's per-round table magnitude (see
///     `spray_entry`, where that scale factor lives)
///   * `GATLING_DAMAGE / M4 damage` says a hull round is a heavier round
///   * `MECH_RECOIL_CONTROL` gives most of it back to the machine
///
/// A function rather than a `const` for the dull reason that `gun()` is
/// not const - but that is the right trade: reading the M4's kick from
/// the same table everything else reads it from means the turret cannot
/// silently drift away from the weapon it is defined against.
///
/// ONE rule for both hull mounts (see `autocannon_kick`), so the brief's
/// "recoil should vary with projectile power" is a single expression
/// with `damage` in it rather than two hand-set numbers that agree
/// today and disagree after one balance pass.
fn mech_mount_kick(damage: f32) -> f32 {
    let m4 = gun(GunKind::M4);
    m4.kick * 9000.0 * (damage / m4.damage) * MECH_RECOIL_CONTROL
}

pub fn turret_kick_per_round() -> f32 {
    mech_mount_kick(GATLING_DAMAGE)
}

/// §13 (owner): the AUTOCANNON's kick, on the same rule - and it had to
/// change, because the 6.0 it used to be did LITERALLY NOTHING.
///
/// `punch` sheds `PUNCH_DECAY_LIN_DEG` (18 deg/s) on top of its
/// exponential every tick. A lone impulse of 6 deg/s of punch VELOCITY
/// adds about 0.05 deg of punch ANGLE in the tick it lands, and the
/// linear term takes all of it back inside that same tick: the shell
/// moved a number and nothing downstream ever saw it. The constant's own
/// doc comment claimed "a kick big enough that firing it unbraced costs
/// you the next shot's picture". It cost nothing, and no test caught it
/// because every one of them asserted the FIELD had moved rather than
/// that anything came of it - which is why the turret test next door
/// measures peak punch across a window instead.
///
/// A 145-damage shell now kicks about 16x a 9-damage turret round,
/// which is what "recoil varies with projectile power" has to mean if
/// it means anything. On a 1.35 s cycle it is fully recovered before
/// the next shell, so it is a punctuation mark rather than a tax.
pub fn autocannon_kick() -> f32 {
    mech_mount_kick(AUTOCANNON_DAMAGE)
}

/// §12: rounds in a BURST.
pub const TURRET_BURST_N: u32 = 3;
/// Growth in kick per round WITHIN a burst - round 3 leaves at 2.1x
/// round 1. A burst you can walk onto a target and then have to let
/// settle, which is the mode's whole reason to exist.
pub const TURRET_BURST_GROWTH: f32 = 0.55;
/// The settle after a burst completes. Nothing fires during it.
pub const TURRET_BURST_RECOVER_S: f32 = 0.50;
/// §12 AUTO: growth per round on a held trigger...
pub const TURRET_AUTO_GROWTH: f32 = 0.14;
/// ...and the ceiling it STABILISES at (reached on round 9). The brief
/// asks for auto to be "sustained growing recoil, stabilising over
/// time"; without a cap "growing" just means "unusable by round 30".
pub const TURRET_AUTO_KICK_CAP: f32 = 2.10;
/// §12 SINGLE: a deliberate, aimed cadence. One round per press, and
/// this long before the mount will take another press at all.
pub const TURRET_SINGLE_RECOVER_S: f32 = 0.18;
/// ...and the precision that buys: the cone at a fraction of what the
/// same mount sprays. "High precision" as a number rather than a mood.
pub const TURRET_SINGLE_SPREAD_MULT: f32 = 0.55;

/// §12 (owner): how the hull turret's trigger behaves.
///
/// `Auto` is the default and is EXACTLY the mount's historical
/// behaviour, so every existing caller - the bot brain included - keeps
/// firing the gun it has always fired.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TurretMode {
    /// One round per press. Lowest sustained recoil, tightest cone.
    Single,
    /// `TURRET_BURST_N` per press, kick growing across the burst, then
    /// a forced settle.
    Burst,
    /// Hold to fire. Recoil grows with the burst index and plateaus at
    /// `TURRET_AUTO_KICK_CAP`.
    Auto,
}

impl TurretMode {
    /// Cycle order for the mode key - the same order the brief lists
    /// them in, so the HUD reads the way the spec does.
    pub const ALL: [TurretMode; 3] = [TurretMode::Single, TurretMode::Burst, TurretMode::Auto];

    /// What the HUD prints. THE single source for the string - a second
    /// copy in the client is how a readout starts lying about the sim.
    pub fn label(self) -> &'static str {
        match self {
            TurretMode::Single => "SINGLE",
            TurretMode::Burst => "BURST x3",
            TurretMode::Auto => "AUTO",
        }
    }

    pub fn next(self) -> TurretMode {
        match self {
            TurretMode::Single => TurretMode::Burst,
            TurretMode::Burst => TurretMode::Auto,
            TurretMode::Auto => TurretMode::Single,
        }
    }

    /// Kick multiplier for round `i` of the current trigger pull (0 for
    /// the first). Pure and shared: the shot and any readout of "how
    /// hot is this burst" come off the same function.
    pub fn kick_mult(self, i: u32) -> f32 {
        match self {
            // no growth at all - one round, then the mount settles
            TurretMode::Single => 1.0,
            TurretMode::Burst => 1.0 + i as f32 * TURRET_BURST_GROWTH,
            TurretMode::Auto => (1.0 + i as f32 * TURRET_AUTO_GROWTH).min(TURRET_AUTO_KICK_CAP),
        }
    }

    /// Cone multiplier on the mount's own spread.
    pub fn spread_mult(self) -> f32 {
        match self {
            TurretMode::Single => TURRET_SINGLE_SPREAD_MULT,
            _ => 1.0,
        }
    }
}

/// §D: the range at which a BOT mech stops spraying and starts aiming.
///
/// Derived, not tuned. `GATLING_SPREAD_COLD` is the per-axis offset
/// `hitscan_burst` applies to the aim ray, so at range `d` a COLD gatling
/// scatters its rounds over a half-width of `GATLING_SPREAD_COLD * d`. A
/// man is `BODY_RADIUS` wide to each side. Past
/// `BODY_RADIUS / GATLING_SPREAD_COLD` even a cold mount is putting most
/// of its rounds beside the target — and every one of those misses still
/// walks the barrels toward a 3.5 s forced vent. That is exactly where
/// one 145-damage round through a 3× tighter cone becomes the honest
/// trade, so the switch is placed there rather than at a round number.
///
/// ≈18.9 m today, which sits inside EVERY difficulty's engage range
/// (Easy 22 / Normal 35 / Hard 50) — so all three tiers really do use
/// both mounts instead of one tier silently never reaching the switch.
pub const MECH_BOT_AUTOCANNON_RANGE_M: f32 = BODY_RADIUS / GATLING_SPREAD_COLD;

/// Hysteresis band on the switch above. A bare threshold over a
/// dithering quantity is a defect, not a rule: a bot holding station
/// near the line would flip mounts tick to tick, and because the two
/// mounts keep INDEPENDENT cooldown clocks (`gatling_cd` /
/// `autocannon_cd`, deliberately never shared) it would then land BOTH —
/// making "stand at exactly 18.9 m" the highest-DPS thing a bot mech can
/// do. One chassis width is the band: committing to the other mount has
/// to be worth more than a single step.
pub const MECH_BOT_MOUNT_HYSTERESIS_M: f32 = MECH_RADIUS;

/// Robot power core: capacity, recharge (grounded, 5 s after ability use),
/// repulsor cost/cooldown, EMP/explosive drain. (The THRUST_* trio lived
/// here from Brief IV's flight model - §4.3 deleted mech flight, and the
/// constants sat dead with a doc claiming live thrusters for two briefs.)
pub const POWER_MAX: f32 = 100.0;
pub const POWER_REGEN: f32 = 6.0;
pub const POWER_REGEN_DELAY: f32 = 5.0;
pub const REPULSOR_DMG: f32 = 62.0;
pub const REPULSOR_KNOCK: f32 = 6.0;
pub const REPULSOR_CD: f32 = 1.4;
pub const REPULSOR_COST: f32 = 12.0;
pub const EXPLOSIVE_POWER_DRAIN: f32 = 25.0;
pub const ROBOT_DRAINED_MOVE: f32 = 0.88;
/// Pyro flame projector: fuel seconds, dps, reach, cone, refill rate.
pub const FLAME_FUEL_S: f32 = 6.0;
pub const FLAME_DPS: f32 = 34.0;
pub const FLAME_REACH: f32 = 7.5;
pub const FLAME_ARC_COS: f32 = 0.906; // ±25°
pub const FLAME_REFILL: f32 = FLAME_FUEL_S / 9.0;
/// Recon passive regen: hp/s after this long without taking damage.
pub const RECON_REGEN: f32 = 4.0;
pub const RECON_REGEN_DELAY: f32 = 5.0;
// ---- §11 (Brief III): the MECH chassis — supersedes the Robot Suit ------
// A piloted walker above human scale. Damage is classified by the angle
// between the shot and the mech's BODY FACING (never the camera): a
// frontal fortress, a flanking objective. The hull is a resource you
// spend — it never regenerates; at zero the pilot ejects at 25 HP.
// Task 4 (MISSION doc, supersedes Brief VI's 1.15x/2.05m): the art
// measures the hull at ~2.5x soldier height with the soldier's helmet
// only reaching the mech's KNEE - 1.15x threw that presence away
// entirely. Decision: A3 (recommended) - 1.7x, ~3.03m. Keeps the
// tower/leg-cover read the art sells, at the cost of only a widened nav
// radius (MECH_RADIUS below is already a formula, not a bespoke system -
// this scale change needed no new collision/doorway infrastructure).
pub const MECH_SCALE: f32 = 1.7;
// §4.5 (Brief VI): the sensor visor is a ×2.0 weak point applied AFTER
// the angle multiplier (front-arc only). (Brief VI's hull of 1000 was
// superseded by the rebalance below - MECH_HULL is 600.)
/// §owner (rebalance): the chassis dies to sustained FRONTAL fire now.
/// Targets, from the front arc: ~10 AWM body shots, ~14 spear hits
/// (the owner's 15-20 band, hit at its floor because the spear also
/// beats shields now), visor shots still twice as good. The old numbers
/// (hull 1000, front x0.15) made the front a 58-shot wall that only a
/// flank could realistically open.
pub const MECH_HULL: f32 = 600.0;
pub const MECH_VISOR_MULT: f32 = 2.0;
pub const MECH_RADIUS: f32 = BODY_RADIUS * MECH_SCALE; // cannot fit doorways
pub const MECH_EJECT_HP: f32 = 25.0;
/// §B.3: the pilot's eye height inside the hull, as a fraction of full
/// mech height. This formula was duplicated as a bare local in TEN
/// places across the test module and existed nowhere as a constant, so
/// nothing could depend on it without copying it an eleventh time.
/// Promoted here before a camera started reading it too.
pub const MECH_VISOR_Y_FRAC: f32 = 0.90;

/// The pilot's eye position inside the hull.
///
/// Pure and shared, so the visor camera and the hit-zone tests can never
/// disagree about where the pilot's head is - the same single-source
/// discipline `approach_velocity` and `shot_clock` exist for.
pub fn mech_visor_eye_y(pos_y: f32) -> f32 {
    pos_y + BODY_HEIGHT * MECH_SCALE * MECH_VISOR_Y_FRAC
}

// ---- §21: the heavy chassis KNEELS and JUMPS -----------------------------
// Both verbs were genuinely absent, and CROUCH was absent on purpose:
// `set_crouch` refused a mech because `height()` returned the full 3.03 m
// unconditionally, so a crouching chassis kept a standing hitbox while the
// renderer played the squat - and the x2.0 visor band, which `apply_hit_dmg`
// places at frac > 0.82 of `height()`, floated in empty air above the model.
//
// The guard was the right fix for that bug. The fix for the CAUSE is that
// `height()` follows the pose: every consumer of the hitbox (the two
// `ray_vs_cylinder` calls) and every consumer of the bands (the frac tests
// in `apply_hit_dmg` and the projectile path) already divide by `height()`,
// so one honest number moves the capsule and the weak point together and
// keeps them in the same PROPORTION of the machine they were always in.
/// The kneeling chassis's height, as a fraction of its standing height.
/// ASSUMED: 0.72. Shallower than a man's squat (CROUCH_HEIGHT/BODY_HEIGHT
/// = 0.646) because a walker's leg has hydraulic travel where a knee has
/// fold, and deep enough that 0.85 m of hull - and the visor with it -
/// drops behind cover a standing chassis is shot over.
pub const MECH_CROUCH_HEIGHT_FRAC: f32 = 0.72;
/// §21 JUMP, the wind-up. A 3 m machine telegraphs: it must COMPRESS
/// before it launches, and the compression is a window the enemy can read
/// and act on. ASSUMED 0.40 s - comfortably past the ~0.25 s a human
/// takes to react, so seeing it is worth something.
pub const MECH_JUMP_COMPRESS_S: f32 = 0.40;
/// §21 JUMP, the landing. The chassis takes the shock through its knees:
/// it is kneeling (low, planted, slow - see `chassis_kneeling`) for this
/// long and cannot jump again until it is over. ASSUMED 0.55 s.
pub const MECH_JUMP_RECOVER_S: f32 = 0.55;
/// §21 JUMP, the price. Charged to `stride_heat` - the chassis's EXISTING
/// mobility budget - at LAUNCH, never at the wind-up (an aborted coil owes
/// nothing, exactly as `stride_wind_t` owes nothing).
///
/// Deliberately the same pool the power stride spends: jumping and
/// striding are the same resource, so a pilot chooses between them instead
/// of getting both. ASSUMED 45.0 of the 100 pool - two jumps back to back,
/// the third refused, and ~2.25 s at the passive 20/s cool before the bar
/// is clear enough to stride.
///
/// REJECTED: a private `mech_jump_cd` timer. It would have made the jump
/// free of every other mech mobility system, so the strongest thing a
/// chassis could do is alternate stride and jump forever - and it would
/// have added a second resource where the brief already names one.
pub const MECH_JUMP_HEAT: f32 = 45.0;
/// §21 JUMP, the impact ring: how far the shock through the ground
/// reaches. ASSUMED 4.5 m - about eight chassis radii, close enough that
/// standing under a landing mech is a decision.
pub const MECH_LAND_RADIUS_M: f32 = 4.5;
/// §21 JUMP: damage at the epicentre, falling off linearly to zero at
/// `MECH_LAND_RADIUS_M`. ASSUMED 40.0 before zone and armour - it lands on
/// the LEGS band (x0.75), so a full-value hit takes 30 off an unarmoured
/// soldier: a real consequence, never a free kill.
pub const MECH_LAND_DMG: f32 = 40.0;
/// §21 JUMP: and the stagger, which is the half that actually decides
/// fights - `STAGGER_SPEED_MULT` halves the victim's pace while it runs.
/// ASSUMED 0.7 s, under `PARRY_STAGGER_S` (0.9): being shaken off your
/// feet is less than being beaten out of your guard.
pub const MECH_LAND_STAGGER_S: f32 = 0.7;

/// §21 JUMP: the launch velocity, DERIVED rather than picked.
///
/// A jump's apex is v²/2g, so scaling the apex by `MECH_SCALE` - the
/// chassis clears exactly the obstacle a soldier clears, measured in its
/// own body heights - means scaling v by the square root of it. At the
/// current constants that is 7.4 x sqrt(1.7) ≈ 9.65 m/s, an apex of
/// ~2.59 m against the soldier's ~1.52 m.
///
/// A function and not a `const` only because `f32::sqrt` is not const;
/// the point is that re-scaling the chassis re-scales the jump, and no
/// call site has to be found and edited for that to be true.
pub fn mech_jump_speed() -> f32 {
    JUMP_SPEED * MECH_SCALE.sqrt()
}

/// §21: which stage of a jump a heavy chassis is in.
///
/// `Compress` is the readable wind-up, `Air` the flight, `Recover` the
/// landing window it cannot jump out of. Public because the client has to
/// draw all three differently - see `TdmSim::mech_jump_phase_of`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum MechJumpPhase {
    #[default]
    None,
    Compress,
    Air,
    Recover,
}

impl MechJumpPhase {
    /// The one place the phase strings live, on the same principle as
    /// `TurretMode::label` - a HUD that spells them itself is a HUD that
    /// can disagree with the sim about what the machine is doing.
    pub fn label(self) -> &'static str {
        match self {
            MechJumpPhase::None => "",
            MechJumpPhase::Compress => "COMPRESS",
            MechJumpPhase::Air => "AIRBORNE",
            MechJumpPhase::Recover => "RECOVER",
        }
    }
}

/// §21: the INFANTRY half of the stance tax.
///
/// Returns 1.0 for a live heavy chassis even when `crouch` is set, because
/// a kneeling chassis is charged by `mech_stance_speed_mult` instead and
/// charging both would multiply to 6% of walking pace for ONE pose - the
/// exact mistake the old comment at this call site warned about ("a mech
/// is denied crouch, so reading `cmd.crouch` here charged it the crouch
/// speed tax for a stance it never entered"). Before §21 the mech simply
/// could not set the flag, so the two never met; now they do.
///
/// Split from the chassis half rather than merged into one multiplier
/// because the speed ladder is NOT commutative between them: the armour
/// weight penalty in the middle is SUBTRACTIVE and then floored at
/// `MOVE_SPEED * ARMOR_WEIGHT_SPEED_FLOOR`, so a multiplier moved across
/// it lands on a different number. Each half keeps the position in the
/// ladder it has always had; only the collision is new.
///
/// Shared by the player ladder in `step` and the bot ladder in `bot_act`,
/// for the reason this project keeps relearning: two ladders applying the
/// same constants independently always drift.
pub fn crouch_speed_mult(f: &Fighter) -> f32 {
    if f.crouch && !f.in_heavy_mech() {
        CROUCH_SPEED_MULT
    } else {
        1.0
    }
}

/// §21: the CHASSIS half of the stance tax - one multiplier for every way
/// a heavy chassis can be planted.
///
/// Kneeling (`chassis_kneeling`: crouched, coiled for a jump, or absorbing
/// a landing) and bracing (`mech_brace`) are the same physical act - wide,
/// settled, near-stationary - and the crouch key sets both. So a planted
/// chassis pays `MECH_BRACE_SPEED_MULT` ONCE, however many flags say it is
/// planted, and never the infantry constant.
///
/// Gated on `in_heavy_mech` inside `chassis_kneeling`, and re-gated here
/// for `mech_brace`, so a pilot whose hull was blown out from under him
/// mid-brace does not carry a chassis pace onto his feet.
pub fn mech_stance_speed_mult(f: &Fighter) -> f32 {
    if f.in_heavy_mech() && (f.chassis_kneeling() || f.mech_brace) {
        MECH_BRACE_SPEED_MULT
    } else {
        1.0
    }
}
// §6.2 (Brief VII v2): boarding/leaving the mech is COMMITTED, not
// instant - the chassis needs real seconds to seal up or power down.
pub const MECH_ENTER_S: f32 = 1.6;
pub const MECH_EXIT_S: f32 = 1.2;

// ---- R&D Cycle 1: mech entry sequence (backlog #1) -----------------------
// [S-01b]: the human-factors literature on staged, must-not-skip
// sequences under time pressure argues for a Do-List pattern (the
// system executes every stage on a fixed timeline, no player action
// mid-sequence) over an interactive challenge-response one - which
// matches §7.6's existing "committed, no cancel" rule and gives it a
// real citation instead of just flavor text. Eight named stages divide
// MECH_ENTER_S evenly; this is presentation SEQUENCING only - it reads
// `mech_transition_t`, never writes gameplay-relevant state, so it
// cannot desync a replay even though it's exposed from the sim layer
// (the sim layer is simply the only place `mech_transition_t` lives).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MechEnterStage {
    CockpitOpen,
    ClimbIn,
    Harness,
    PowerUp,
    ServoSync,
    GyroCalibration,
    WeaponDiagnostics,
    HudBoot,
}
pub const MECH_ENTER_STAGES: [MechEnterStage; 8] = [
    MechEnterStage::CockpitOpen,
    MechEnterStage::ClimbIn,
    MechEnterStage::Harness,
    MechEnterStage::PowerUp,
    MechEnterStage::ServoSync,
    MechEnterStage::GyroCalibration,
    MechEnterStage::WeaponDiagnostics,
    MechEnterStage::HudBoot,
];

/// Pure: which named stage is active `elapsed_s` into the entry window.
/// Clamped at both ends so a caller need not pre-validate its input.
pub fn mech_enter_stage(elapsed_s: f32) -> MechEnterStage {
    let frac = (elapsed_s / MECH_ENTER_S).clamp(0.0, 0.999_999);
    let idx = (frac * MECH_ENTER_STAGES.len() as f32) as usize;
    MECH_ENTER_STAGES[idx.min(MECH_ENTER_STAGES.len() - 1)]
}

/// The active stage for a fighter currently mid-entry, or `None` if
/// they aren't (not a mech, not transitioning, or exiting rather than
/// entering - `mech_exiting` reuses the same timer for the power-DOWN
/// countdown, which has no stage list of its own).
pub fn mech_enter_stage_for(f: &Fighter) -> Option<MechEnterStage> {
    if f.armor_set != ArmorSet::RobotSuit || f.mech_transition_t <= 0.0 || f.mech_exiting {
        return None;
    }
    Some(mech_enter_stage(MECH_ENTER_S - f.mech_transition_t))
}
// §6.3: armor drops in three stages as hull falls - the exposed
// under-frame at each stage takes MORE damage, rewarding the strip.
pub const MECH_PLATE_70_PCT: f32 = 0.70;
pub const MECH_PLATE_40_PCT: f32 = 0.40;
pub const MECH_PLATE_15_PCT: f32 = 0.15;

// ---- infantry-vs-mech: HULL CLIMBING (research/mech-climb/DESIGN.md) ----
// Attach points ARE the dropped-plate zones - climbing is the PAYOFF for
// stripping a mech, not a free action from full health. SIM-authoritative
// and deterministic: fixed drain rates, nearest-valid-zone selection, no
// randomness, so the replay guarantee is untouched by construction.

/// The three plate-detach zones, NAMED - the bitmask bits finally get
/// identities (bit0 = 70% skirts, bit1 = 40% drum/antenna, bit2 = 15%
/// cleats). Checklist item 1.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PlateZone {
    /// 70%: the hip skirts - right flank grip.
    Skirts,
    /// 40%: the rear drum - back grip.
    Drum,
    /// 15%: the foot cleats - low front grip.
    Cleats,
}

impl PlateZone {
    pub const ALL: [PlateZone; 3] = [Self::Skirts, Self::Drum, Self::Cleats];
    /// The `mech_plates_dropped` bit that must be SET before this zone
    /// is climbable.
    pub fn bit(self) -> u8 {
        match self {
            Self::Skirts => 0b001,
            Self::Drum => 0b010,
            Self::Cleats => 0b100,
        }
    }
    /// Grip-point offset in the mech's LOCAL frame (metres, world scale),
    /// rotated by its yaw when resolved.
    pub fn offset(self) -> [f32; 3] {
        match self {
            Self::Skirts => [1.15, 0.95, 0.15],
            Self::Drum => [0.0, 1.45, -1.15],
            Self::Cleats => [0.0, 0.55, 1.15],
        }
    }
}

/// Checklist item 2: the grip, `None` for everyone not hanging on.
#[derive(Clone, Debug)]
pub struct ClimbState {
    pub mech_target: usize,
    pub attach_zone: PlateZone,
    /// 0..100. Drains while attached; recovers ONLY while released -
    /// [S-02]'s rest-only recovery, so release-regrip beats one long
    /// hold of equal total duration.
    pub grip_stamina: f32,
}

/// Reach from which a grab can start.
pub const CLIMB_ATTACH_RANGE_M: f32 = 2.9;
pub const CLIMB_GRIP_MAX: f32 = 100.0;
/// ~8.3 s of continuous hold from full.
pub const CLIMB_GRIP_DRAIN_PER_S: f32 = 12.0;
/// Rest-only, and SLOWER than the drain - the asymmetry is the [S-02]
/// finding, not a tuning accident.
pub const CLIMB_GRIP_RECOVER_PER_S: f32 = 9.0;
/// A strike landed AT the stripped zone, reachable only by being there.
/// Stacks ON TOP of angle armor and the exposed-frame x1.25.
pub const CLIMB_STRIKE_MULT: f32 = 1.6;
pub const MECH_EXPOSED_DMG_MULT: f32 = 1.25;
/// Frontal 0–60°: 47.5% reduction (×0.525 through). Side 60–120°: 30%
/// (×0.70). Rear: none.
///
/// Brief VI specified 85%/70%, and this comment still claimed those long
/// after the constants below were rebalanced - see the §owner note above
/// MECH_HULL for why the front was opened up. Read the constants, not
/// the brief.
pub const MECH_RED_FRONT: f32 = 0.475;
pub const MECH_RED_SIDE: f32 = 0.30;
/// §11.2 rule 2: explosives bypass HALF the reduction; fire bypasses ALL
/// of it (it attacks cooling, not plating — Pyro's defined role).
/// §11: the mech TURNS to face a threat — a real, visible, punishable
/// commitment. The pilot's view is free; the armor follows the body.
// §4.3 (Brief VI): 180°/s — a soldier circling close feels the lag
pub const MECH_TURN_RATE: f32 = 3.1416; // rad/s

// ---- §7.4 (BRIEF VIII): power stride --------------------------------
// "The mech's answer to being outrun, without ever leaving the
// ground." Held sprint winds the hull forward, then bursts to 110% of
// soldier run speed for a BOUNDED window — not a second walk speed.
// Shares the §7.8 heat pool with the minigun by the brief's own
// cross-reference ("costs heat (§7.8)"): a mech running hot from its
// gun cannot also stride, one budget for how hard the machine is
// pushed, not two independent ones.
pub const POWER_STRIDE_WINDUP_S: f32 = 0.35;
pub const POWER_STRIDE_DURATION_S: f32 = 2.5;
pub const POWER_STRIDE_SPEED_MULT: f32 = 1.10;
pub const POWER_STRIDE_HEAT_PER_S: f32 = 100.0 / POWER_STRIDE_DURATION_S; // 40/s - a full burst spends the whole bar
pub const POWER_STRIDE_TURN_RATE: f32 = MECH_TURN_RATE * 0.5; // 90 deg/s, half the normal pivot cap
// ---- §10 (Brief III): base health regeneration ---------------------------
// Every fighter, independent of armor. Deliberately slow: worst case from
// one bullet to full is 24 s — it rewards disengaging, not trading. ANY
// damage resets the timer, so DoT (fire pools, toxin) denies regen
// entirely and area denial keeps its value. Restores HEALTH only, never
// armor — armor is a consumable found in the world.
pub const REGEN_DELAY_S: f32 = 12.0;
pub const REGEN_RATE_HPS: f32 = 8.33;
// ---- §5 (Brief III): the knife -------------------------------------------
// Tap: quick slash. Hold: committed lunge — visibly wound up, punishable.
// Silent (4 m noise), backstabs are lethal, and it works on the horde:
// the correct tool for zombie extraction and (later) mech rear arcs.
// ---- melee depth v1 (BACKLOG #4): the PARRY --------------------------
// Swing INTO the incoming strike. A fighter whose own blade is in its
// WIND (raised, not yet through) deflects any melee blow arriving
// through their front arc: zero damage, and the ATTACKER staggers -
// briefly unable to fire or swing, and slowed. Deliberately the same
// front-arc cosine the shield uses: one facing rule for the whole game.
/// How long a parried attacker is staggered.
pub const PARRY_STAGGER_S: f32 = 0.9;

// ---- §owner SQUAD AI ------------------------------------------------------
// Bots were five strangers who happened to share a field: every one of
// them picked its own waypoint, its own target, and pushed on its own.
// The visible symptom is TRICKLING - you hold one angle and they arrive
// one at a time to be shot, so five opponents never feel like five.
//
// Everything below is deterministic by construction. Roles come from
// fighter INDEX order, never from `rng`, because the replay tests assert
// a full match is bit-identical and a coordination system that rolled
// dice would desync every one of them.

/// How near a teammate has to be to count as fighting alongside you.
pub const SQUAD_RADIUS_M: f32 = 22.0;
/// A target a squadmate is already on is treated as this much closer
/// when picking who to shoot. Enough to break the "everyone shoots their
/// own nearest" pattern, not enough to drag a bot across the map past a
/// man in its face.
pub const SQUAD_FOCUS_BONUS_M: f32 = 9.0;
/// Bots closer together than this push apart. Stops a squad stacking
/// into one grenade and makes the spread look deliberate.
pub const SQUAD_SPACING_M: f32 = 3.4;
pub const SQUAD_SPACING_PUSH: f32 = 0.55;
/// How wide a flanker swings off the direct line to its target.
pub const SQUAD_FLANK_STRENGTH: f32 = 0.85;

// ---- SUPPRESSION ---------------------------------------------------------
//
// The half of squad AI that acts on the man being shot AT rather than on
// the men shooting. Until now a round that missed by 20 cm and a round
// that missed by 20 m were the same event: nothing. That is why a squad
// could put a hundred rounds through a doorway and the man in it would
// walk out of it at full speed, shooting straight.
//
// Produced by GEOMETRY, not by intent. A bot does not decide to suppress
// you; rounds pass close to you and that is the whole mechanism. Which
// means the player suppresses bots by shooting near them, with no special
// case, and a wild burst that happens to crack past someone's ear counts
// exactly as much as a deliberate one - because to the man behind the
// wall those are the same thing.

/// How near a round has to pass to count. A shade over a metre: close
/// enough that it went past YOU rather than past the room.
pub const SUPPRESS_RADIUS_M: f32 = 1.15;
/// Seconds of suppression one close round buys, and the ceiling it stacks
/// to. The ceiling matters more than the increment: without it, sustained
/// fire from a belt gun would pin a target for the rest of the round.
pub const SUPPRESS_PER_ROUND_S: f32 = 0.55;
pub const SUPPRESS_MAX_S: f32 = 1.8;
/// How much a suppressed bot's aim degrades, at full suppression. It is a
/// MULTIPLIER on the difficulty's own `aim_sigma`, so a hard bot under
/// fire is still better than an easy one in the open - suppression makes
/// a bot worse than itself, never worse than the difficulty below it.
pub const SUPPRESS_AIM_PENALTY: f32 = 1.9;

// ---- BOUNDING OVERWATCH --------------------------------------------------
//
// Anchor/flank answers WHERE a bot goes. This answers WHEN it moves, and
// the two are deliberately separate axes: a flanker still bounds, an
// anchor still takes its turn to hold. Collapsing them into one enum
// would have made "the flanker" and "the one who is moving" the same
// fighter forever, which is the single-file advance the spacing fix
// already had to clean up once.
//
// One element moves while the other shoots, then they swap. The swap is a
// function of the sim clock and the fighter's rank among the squadmates
// on that target - no stored phase, no timer to get out of sync, nothing
// rolled. Two runs of the same seed bound on exactly the same ticks.

/// How long one bound lasts before the pair swaps. Long enough to cross a
/// lane, short enough that the stationary half is never a free target for
/// more than a breath.
pub const BOUND_PERIOD_S: f32 = 1.6;
/// The bounding element pushes harder than a lone bot would - it is
/// moving under someone else's covering fire, which is the entire point.
pub const BOUND_CLOSE_MULT: f32 = 1.7;
/// Squads only bound when they are far enough out for it to mean
/// anything. Inside this it is a room fight, and stopping dead to shoot
/// while a man closes on you is just dying on schedule.
pub const BOUND_MIN_RANGE_M: f32 = 11.0;

/// What a bot is doing inside a shared engagement.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum SquadRole {
    /// Fighting alone, or the one holding the enemy's attention.
    #[default]
    Anchor,
    /// Working around the side while the anchor holds the front.
    Flank,
}

// ---- RETREAT -------------------------------------------------------------
//
// The last quarter of squad AI, and the only part of it that needed
// something the TDM sim did not have: MEMORY. Focus fire, roles, bounding
// and suppression are all derived fresh every tick from live positions -
// nothing is remembered, which is what keeps them free and replay-safe. A
// squad that BREAKS cannot work that way. Breaking is a response to what
// has been happening to you, and a bot with no memory of the last ten
// seconds has nothing to break from.
//
// So `fear` is the first genuinely accumulated bot state in this file,
// and it is modelled on `jk_wall`'s morale pass, which the backlog named
// as the right source years before this. What is borrowed is the SHAPE:
// fear flows in from what a man sees and feels, bleeds out over time, and
// crosses a threshold with HYSTERESIS so a squad breaks and rallies
// instead of flickering on the boundary.
//
// What is NOT borrowed is `jk_wall`'s per-man `rout_tolerance`, which it
// rolls from rng at spawn. This build asserts bit-identical replays, so
// the threshold comes from CLASS instead - which is better anyway: it
// makes nerve a fifth thing the four classes trade, and a Warden that
// holds when a Skirmisher runs is a Warden you can feel.

/// How near a man has to fall for it to shake you, and how much it does
/// at zero range. Distance-weighted to nothing at the edge.
pub const FEAR_WITNESS_M: f32 = 18.0;
pub const FEAR_WITNESS_DOWN: f32 = 0.40;
/// Fear per second while pinned, at full suppression.
///
/// This is where the two systems meet: rounds cracking past you are the
/// most direct thing that makes a man want to be elsewhere, and
/// suppression was already measuring exactly that. Bounding overwatch
/// produces the suppression, the suppression produces the fear, the fear
/// breaks the squad. None of those three needed a new input.
pub const FEAR_SUPPRESSED_PER_S: f32 = 0.42;
/// Fear per second per NET enemy in the local fight.
pub const FEAR_OUTNUMBER_PER_S: f32 = 0.20;
/// Fear per second from your own blood, scaled by the fraction of health
/// already gone. A man at full health feels none of it.
pub const FEAR_WOUNDED_PER_S: f32 = 0.34;
/// Nerve recovers at this rate, multiplied once contact is broken -
/// distance calms, which is what makes a retreat self-limiting rather
/// than a one-way exit from the match.
pub const FEAR_RECOVERY_PER_S: f32 = 0.26;
pub const FEAR_ROUTING_RECOVERY_MULT: f32 = 3.0;
/// The break threshold, before the class multiplier.
pub const ROUT_TOLERANCE: f32 = 1.0;
/// And the rally threshold. Well below the break point ON PURPOSE: equal
/// thresholds would put a bot on a knife edge, flipping stance every few
/// ticks and reading as a twitch rather than a decision.
pub const RALLY_FEAR: f32 = 0.34;
pub const FEAR_MAX: f32 = 1.6;
/// How fast a broken man moves away. Faster than a fighting advance -
/// he is not trading any more, he is leaving.
pub const ROUT_SPEED_MULT: f32 = 1.15;

/// Which half of a bounding pair a bot is in this instant.
///
/// Orthogonal to `SquadRole` - see the comment above. `Free` is the
/// ordinary case: no squadmate to bound with, or too close for it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum BoundPhase {
    /// Not in a bounding pair - moves and shoots as bots always did.
    #[default]
    Free,
    /// Moving. Pushes hard, holds fire - a man at a run is not shooting.
    Bounding,
    /// Planted and firing, so the other half can move.
    Overwatch,
}

/// §owner MELEE v2: which way a swing travels.
///
/// Chosen by the attacker's own MOVEMENT at the moment the blade starts
/// its wind - strafing left throws a left swing, strafing right a right
/// one, standing or pushing forward an overhead. No new keys: the
/// direction is something the hand is already on.
///
/// It exists so a knife fight is a READ rather than a timing check. A
/// parry only meets a blade travelling the same way (see
/// `is_parrying_dir`), so defending means guessing the attacker's line.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum MeleeDir {
    /// Straight down the middle - what standing still gives you.
    #[default]
    Overhead,
    Left,
    Right,
}

/// How hard you must be strafing before the swing follows the strafe
/// rather than coming overhead. Below this, drifting sideways during a
/// fight cannot silently change your attack out from under you.
pub const MELEE_DIR_DEADZONE: f32 = 0.35;

impl MeleeDir {
    /// The swing a given movement input produces.
    pub fn from_move(move_x: f32) -> MeleeDir {
        if move_x <= -MELEE_DIR_DEADZONE {
            MeleeDir::Left
        } else if move_x >= MELEE_DIR_DEADZONE {
            MeleeDir::Right
        } else {
            MeleeDir::Overhead
        }
    }
    pub fn name(self) -> &'static str {
        match self {
            MeleeDir::Overhead => "OVERHEAD",
            MeleeDir::Left => "LEFT",
            MeleeDir::Right => "RIGHT",
        }
    }
}
/// Move-speed multiplier while staggered.
pub const STAGGER_SPEED_MULT: f32 = 0.55;
/// A parried ZOMBIE eats a longer stun - the claw has no discipline to
/// recover with.
pub const ZOMBIE_PARRY_STUN_S: f32 = 1.8;

pub const KNIFE_QUICK_WIND_S: f32 = 0.28;
pub const KNIFE_QUICK_ACTIVE_S: f32 = 0.12;
pub const KNIFE_QUICK_RECOVER_S: f32 = 0.34;
pub const KNIFE_QUICK_DMG: f32 = 55.0;
pub const KNIFE_QUICK_BACKSTAB: f32 = 160.0;
pub const KNIFE_RANGE_M: f32 = 1.9;
pub const KNIFE_LUNGE_WIND_S: f32 = 0.55;
pub const KNIFE_LUNGE_RANGE_M: f32 = 2.9;
pub const KNIFE_LUNGE_DMG: f32 = 95.0;
pub const KNIFE_LUNGE_BACKSTAB: f32 = 999.0;
/// Holding past this commits the lunge instead of the quick slash.
pub const KNIFE_COMMIT_S: f32 = 0.30;
// ---- §6 (Brief IV): the axe ----------------------------------------------
// The knife's heavy sibling: slower on every beat, hits harder, and the
// swing is a SWEEP — every enemy inside the 90° frontal arc takes the
// hit. Louder than the blade (6 m), still quiet next to any gun.
pub const AXE_QUICK_WIND_S: f32 = 0.45;
pub const AXE_QUICK_ACTIVE_S: f32 = 0.15;
pub const AXE_QUICK_RECOVER_S: f32 = 0.50;
pub const AXE_QUICK_DMG: f32 = 85.0;
pub const AXE_QUICK_BACKSTAB: f32 = 190.0;
pub const AXE_RANGE_M: f32 = 2.1;
/// cos of the sweep half-angle (±45° — the full 90° arc).
pub const AXE_ARC_COS: f32 = 0.707;
pub const AXE_LUNGE_WIND_S: f32 = 0.70;
pub const AXE_LUNGE_DMG: f32 = 130.0;
pub const AXE_LUNGE_BACKSTAB: f32 = 999.0;
// ---- §7 (Brief IV): the minigun ------------------------------------------
// Never in a loadout — a pad weapon. The whole design is the tradeoff
// loop: spin-up latency before the stream, heat while it pours, a forced
// 3 s vent at 100 heat (R vents early on YOUR schedule instead). 400
// rounds, no reloads — the pad respawn is the reload.
pub const MINIGUN_SPINUP_S: f32 = 0.4; // §5.1 (Brief VI)
/// §5.1: 100 heat in exactly 4 s of continuous fire at 1000 RPM
/// (66.7 rounds): 1.5 heat per round.
pub const MINIGUN_HEAT_PER_SHOT: f32 = 1.5;
pub const MINIGUN_VENT_FORCED_S: f32 = 3.0;
/// Manual (R) vent clears heat at this rate — 60 heat ≈ 1.4 s.
pub const MINIGUN_VENT_RATE: f32 = 42.9;
/// §5.1: idle cooling — a full 99% cooldown in 6 s.
pub const MINIGUN_HEAT_DECAY: f32 = 16.5;
/// §5.1: the spread cone WIDENS with heat — 1.2° → 3.5° half-angle
/// (as tangents: tan 1.2° = 0.021, tan 3.5° = 0.061).
pub const MINIGUN_SPREAD_COLD: f32 = 0.021;
pub const MINIGUN_SPREAD_HOT: f32 = 0.061;

/// §3.4 (BRIEF VIII): sprint-carry threshold and per-class sprint-out
/// times - the delay between leaving a sprint and being able to fire.
/// Class mapping: light/one-handed 0.15, rifles 0.20, heavy 0.30.
/// (The minigun keeps its own spin-up as its readiness cost; projectile
/// draws - bow/spear - already pay windup+stability, so their sprint-out
/// uses the rifle beat rather than stacking a second heavy tax.)
pub const SPRINT_CARRY_FRAC: f32 = 0.85;
pub fn sprint_out_s(kind: GunKind) -> f32 {
    match kind {
        GunKind::Glock | GunKind::Deagle | GunKind::Mp5 | GunKind::Fists => 0.15,
        GunKind::M4 | GunKind::Ak47 | GunKind::Bow => 0.20,
        GunKind::Shotgun | GunKind::M249 | GunKind::Awm => 0.30,
        // spin-up IS the minigun's ready cost - no double tax
        GunKind::Minigun => 0.0,
        // §5.4: the spear's OWN windup already pays the "can't
        // insta-fire out of a sprint" cost the generic gate exists
        // for - and the running-throw bonus explicitly REWARDS
        // throwing while still at running speed. Stacking the sprint
        // gate on top would make that condition unreachable: the gate
        // holds at any speed above the 85% carry threshold, but the
        // bonus wants exactly a throw released AT that speed. Found
        // by the running-throw bonus's own test failing against this.
        GunKind::Spear => 0.0,
    }
}

/// §3.4: the empty reload (bolt/charge cycle on top of the mag swap) is
/// SLOWER than a tactical reload with a round still chambered. The ammo
/// math already kept the chambered round; the TIME cost of running dry
/// did not exist - tactical and empty took identical seconds, deleting
/// the count-your-shots skill the split exists to reward.
pub const RELOAD_EMPTY_MULT: f32 = 1.35;

/// §5.1 (Brief VI): a gun's base cone BEFORE movement/bloom. For the
/// minigun this WIDENS with heat instead of blooming - 1.2 deg cold to
/// 3.5 deg at full heat - which is that weapon's entire cost model.
///
/// Public and shared because the client's crosshair must show the same
/// number the sim shoots: `GunSpec.spread` holds only the COLD value, so
/// a client reading the spec directly showed a stability bracket that
/// never moved across a full heat cycle while the real cone nearly
/// tripled.
pub fn base_spread(kind: GunKind, heat: f32) -> f32 {
    if kind == GunKind::Minigun {
        MINIGUN_SPREAD_COLD
            + (MINIGUN_SPREAD_HOT - MINIGUN_SPREAD_COLD) * (heat / 100.0).clamp(0.0, 1.0)
    } else {
        gun(kind).spread
    }
}
/// Carrying the mass: ×0.70 walk; barrels spun: ×0.55.
pub const MINIGUN_MOVE_MULT: f32 = 0.70;
pub const MINIGUN_SPUN_MOVE_MULT: f32 = 0.55;
/// Trigger-intent hold window — long enough to bridge the 15 Hz far-bot
/// LOD (8 ticks), short enough to be imperceptible on release (70 ms).
pub const MINIGUN_SPIN_HOLD_S: f32 = 0.07;
// ---- §6 (Brief III): shield rules ----------------------------------------
/// Throwing from behind the raised shield LOWERS it for this long — a
/// real window of vulnerability that makes the lob a decision.
pub const SHIELD_DIP_S: f32 = 0.62;
// ---- §3 (Brief III): the Achilles throw ----------------------------------
/// The spear now has a VISIBLE windup before release — plant, hips, whip.
/// Enemies can see it coming; the spear is a committal weapon, the
/// correct counterweight to its flat trajectory. The release uses the
/// thrower's aim AT RELEASE (athletes track their target through the
/// plant), refreshed while winding.
// §3.1 (Brief VII v2): the raise is 0.4s (was 0.5s) - Sons of the Forest's
// grammar, retuned.
pub const SPEAR_WINDUP_S: f32 = 0.40;

/// §owner JAVELIN: the throw is CHARGED now.
///
/// It used to leave the hand at one fixed speed whether you flicked it
/// or leaned into it, which made the most physical weapon in the game
/// the least expressive - a javelin is the one throw where how hard you
/// wind up obviously ought to matter.
///
/// Hold the trigger to wind, release to throw. Below the minimum it is
/// a quick flick that still leaves the hand (never a dead trigger);
/// past the full mark it stops gaining, so there is a right amount to
/// hold rather than "always hold longest".
pub const SPEAR_CHARGE_MIN_S: f32 = 0.12;
pub const SPEAR_CHARGE_FULL_S: f32 = 0.85;
/// Velocity multiplier at the two ends of that window. A faster spear
/// flies FLATTER, so this buys range and lead-time as much as speed -
/// which is the "further" half of the ask.
///
/// §9 (owner): the FLOOR came up, 0.82 → 0.90. Because drop goes as
/// 1/v², the bottom of this window is where an unpredictable arc lives -
/// the same 8-percentage-point move costs the top of the band almost
/// nothing and buys the bottom a visibly flatter throw. The full-wind
/// payoff is untouched at 1.30, so the spread between a flick and a
/// committed throw is still 1.44x and winding up still obviously means
/// something.
pub const SPEAR_CHARGE_V0_MIN: f32 = 0.90;
pub const SPEAR_CHARGE_V0_MAX: f32 = 1.30;

/// How hard a javelin held for `held_s` leaves the hand, as a multiplier
/// on the weapon's base velocity. Pure, so the HUD read and the throw
/// itself cannot disagree about how charged a throw was.
pub fn spear_charge_mult(held_s: f32) -> f32 {
    let t = ((held_s - SPEAR_CHARGE_MIN_S)
        / (SPEAR_CHARGE_FULL_S - SPEAR_CHARGE_MIN_S))
        .clamp(0.0, 1.0);
    SPEAR_CHARGE_V0_MIN + (SPEAR_CHARGE_V0_MAX - SPEAR_CHARGE_V0_MIN) * t
}

// ---- §4 (Brief III): aerial flips ----------------------------------------
// Q + direction while airborne. ONE flip per airborne period, no firing
// until landing recovery — pure mobility, never a combat move.
pub const FLIP_S: f32 = 0.62;
pub const FLIP_BOOST: f32 = 1.4;
pub const FLIP_RECOVER_S: f32 = 0.18;
pub const FLIP_RECOVER_SPEED: f32 = 0.6;

/// §4.3: how `apply_hit` classifies zones on this fighter RIGHT NOW.
/// Halfway through a backflip the head occupies the BOTTOM of the capsule
/// — the banded frac test would call a boot shot a ×4 headshot. Airborne
/// acrobatics force Uniform (×1.0 everywhere) for the full flip plus the
/// landing recovery, in BOTH directions.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HitZoneMode {
    Banded,
    Uniform,
}

// ---- §8 (Brief II): zombie extraction ------------------------------------

/// The enemy roster. Headshots (×4.0) one-shot the mass — that's the
/// skeleton and hit-zone work paying rent directly to the player.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ZKind {
    /// The mass. A headshot is a one-shot kill.
    Shambler,
    /// Fast, after the 4-minute mark. Stops you moving backwards.
    Runner,
    /// Staggers on every 3rd headshot; a wall of meat.
    Brute,
    /// 2.2 s wind-up, then calls the horde. The tension engine.
    Screamer,
    /// Bursts into a toxic cloud on death. Punishes close range.
    Bloater,
}

pub struct ZSpec {
    pub hp: f32,
    pub speed: f32,
    pub dmg: f32,
    pub height: f32,
    pub girth: f32,
}

pub fn zspec(k: ZKind) -> ZSpec {
    match k {
        ZKind::Shambler => ZSpec { hp: 42.0, speed: 1.6, dmg: 14.0, height: 1.7, girth: 0.38 },
        ZKind::Runner => ZSpec { hp: 30.0, speed: 6.9, dmg: 11.0, height: 1.6, girth: 0.32 },
        ZKind::Brute => ZSpec { hp: 340.0, speed: 2.8, dmg: 48.0, height: 2.2, girth: 0.62 },
        ZKind::Screamer => ZSpec { hp: 24.0, speed: 3.1, dmg: 0.0, height: 1.7, girth: 0.34 },
        ZKind::Bloater => ZSpec { hp: 90.0, speed: 1.2, dmg: 0.0, height: 1.8, girth: 0.55 },
    }
}

#[derive(Clone, Debug)]
